മറ്റൊരു റിപ്പോർട്ടിൽ: ഹുദൈബിയാ സന്ധിയിലേർപ്പെട്ട കാലഘട്ടത്തിലെ ഒരു വെള്ളിയാഴ്ച ദിവസം അവരുടെ ചെരുപ്പടികളെപ്പോലും നനക്കാത്ത മഴ അവർക്ക് ബാധിക്കുകയും നബി(സ) അവരോട് അവരുടെ തമ്പുകളിൽ നിസ്കരിക്കുവാൻ കൽപിക്കുകയും ചെയ്തതിന് അദ്ദേഹം സാക്ഷിയായി.¹ (ദ,ന,ജ)', 'أُسَامَةَ بْنِ عُمَيْرٍ', 'ഉസാമതുബ്നു അമീർ(റ)', '¹. അറേബ്യയിൽ മഴവെള്ളം മണ്ണിലേക്കു പെട്ടെന്ന് ഇറങ്ങിപ്പോവാത്തതു കൊണ്ട് ചെറിയ മഴയും പ്രയാസങ്ങളുണ്ടാക്കും.', null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 357, 357, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
