മറ്റൊരു നിവേദനം: ഒരു പട്ടുവസ്ത്രം അങ്ങാടിയൽ വിൽപനക്ക് വെച്ചതായി ഉമർ(റ) കണ്ടു. അപ്പോൾ അതെടുത്ത് അതുമായി പ്രവാചകസന്നിധിയിൽ ചെന്നു. അപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "നീ ഇത് വാങ്ങി പെരുന്നാളിനും യാത്രാവേളയിലും ഉപയോഗിക്കുക." ഹദീസ് തുടർന്നു. ഒന്നാമത്തേതാണ് പൂർണ്ണമായത്. (ബു,മു,ദ,ന)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്‌നു ഉമർ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 363, 364, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
