insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "نَحْنُ الْآخِرُونَ السَّابِقُونَ يَوْمَ الْقِيَامَةِ، وَنَحْنُ أَوَّلُ مَنْ يَدْخُلُ الْجَنَّةَ، بَيْدَ أَنَّهُمْ أُوتُوا الْكِتَابَ مِنْ قَبْلِنَا، وَأُوتِينَاهُ مِنْ بَعْدِهِمْ فَاخْتَلَفُوا، فَهَدَانَا اللهُ لِمَا اخْتَلَفُوا فِيهِ مِنَ الْحَقِّ، ثُمَّ هَذَا يَوْمُهُمُ الَّذِي اخْتَلَفُوا فِيهِ، هَدَانَا اللهُ لَهُ – قَالَ: يَوْمُ الْجُمُعَةِ – فَالْيَوْمُ لَنَا، وَغَدًا لِلْيَهُودِ، وَبَعْدَ غَدٍ لِلنَّصَارَى". (ق,ن)', 'അബൂഹുറൈറ(റ): അല്ലാഹുവിന്റെ ദൂതൻ അരുളി: "നാം (കാലഘട്ടത്തിൽ) അവസാനത്തവരും അന്ത്യനാളിൽ (ശ്രേഷ്ഠതയിൽ) ആദ്യത്തവരുമാണ്. സ്വർഗ്ഗത്തിൽ ആദ്യമായി പ്രവേശിക്കുന്നവർ നമ്മളാണ്. പക്ഷേ, നമുക്ക് മുമ്പേ അവർക്ക് (പൂർവ്വികർക്ക്) ഗ്രന്ഥങ്ങൾ നൽകപ്പെട്ടു, അവർക്ക് ശേഷമാണ് നമുക്കത് നൽകപ്പെട്ടത്. അവർ ഭിന്നിച്ചു. അവർ ഭിന്നിച്ച വിഷയത്തിൽ അല്ലാഹു നമുക്ക് യാഥാർത്ഥ്യം കാണിച്ചുതന്നു. അവർ ഭിന്നിക്കുകയും അല്ലാഹു നമുക്ക് അറിയിച്ചു തരികയും ചെയ്ത വെള്ളിയാഴ്ച ദിനമാണിത്. ഇന്ന് നമ്മുടേത്, നാളെ (ശനി) യഹൂദികളുടേത്, മറ്റന്നാൾ (ഞായർ) ക്രിസ്ത്യാനികളുടേതും." (ബു,മു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','ن']::text[], array['ബു','മു','ന']::text[], null, null, 345, 345, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنْ أَبِي هُرَيْرَةَ وَحُذَيْفَةَ رَضِيَ اللهُ عَنْهُمَا قَالَا: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَضَلَّ اللَّهُ عَنِ الْجُمُعَةِ مَنْ كَانَ قَبْلَنَا، فَكَانَ لِلْيَهُودِ يَوْمُ السَّبْتِ، وَكَانَ لِلنَّصَارَى يَوْمُ الْأَحَدِ، فَجَاءَ اللَّهُ بِنَا فَهَدَانَا اللَّهُ لِيَوْمِ الْجُمُعَةِ، فَجَعَلَ الْجُمُعَةَ وَالسَّبْتَ وَالْأَحَدَ، وَكَذَلِكَ هُمْ تَبَعٌ لَنَا يَوْمَ الْقِيَامَةِ. نَحْنُ الْآخِرُونَ مِنْ أَهْلِ الدُّنْيَا، وَالْأَوَّلُونَ يَوْمَ الْقِيَامَةِ، الْمَقْضِيُّ لَهُمْ قَبْلَ الْخَلَائِقِ". (م,ن,جه)', 'അബൂഹുറൈറ(റ), ഹുദൈഫ(റ): നബി(സ) പറഞ്ഞു: "നമ്മുടെ മുൻഗാമികളെ അല്ലാഹു വെള്ളിയാഴ്ചയിൽ നിന്ന് തെറ്റിച്ചു. (ശ്രേഷ്ഠ ദിവസം വെള്ളിയാഴ്ചയാണെന്ന് അവർ തിരിച്ചറിഞ്ഞില്ല). യഹൂദികൾക്ക് ശനിയാഴ്ച ദിവസമായിരുന്നു. ക്രിസ്ത്യാനികൾക്ക് ഞായറാഴ്ചയും. അല്ലാഹു നമ്മെ കൊണ്ടുവന്നു, വെള്ളിയാഴ്ച ദിവസത്തിന് സൗഭാഗ്യം നൽകി. അവൻ വെള്ളി, ശനി, ഞായർ ദിവസങ്ങൾ (ഓരോ വിഭാഗത്തിന്റെയും ശ്രേഷ്ഠ ദിവസങ്ങൾ ആക്കി). ഇപ്രകാരം പൂർവ്വ വേദക്കാർ അവസാന നാളിൽ നമ്മെ പിന്തുടർന്നുവരും. ഇഹലോക വാസികളിൽ അവസാനത്തവരും, അന്ത്യനാളിൽ ആദ്യത്തവരും ആദ്യമായി വിധി നിർണ്ണയിക്കപ്പെടുന്നവരും നാമായിരിക്കും." (മു,ന,ജ)', 'أَبِي هُرَيْرَةَ وَحُذَيْفَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','ن','جه']::text[], array['മു','ന','ജ']::text[], null, null, 345, 345, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "نَحْنُ الْآخِرُونَ السَّابِقُونَ يَوْمَ الْقِيَامَةِ، أُوتُوا الْكِتَابَ مِنْ قَبْلِنَا، وَأُوتِينَاهُ مِنْ بَعْدِهِمْ، فَهَذَا الْيَوْمُ الَّذِي اخْتَلَفُوافِيهِ، فَهَدَانَا اللَّهُ، فَغَدًا لِلْيَهُودِ، وَبَعْدَ غَدٍ لِلنَّصَارَى. فَسَكَتَ ثُمَّ قَالَ: "عَلَى كُلِّ مُسْلِمٍ أَنْ يَغْتَسِلَ فِي كُلِّ سَبْعَةِ أَيَّامٍ يَوْمًا، يَغْسِلُ فِيهِ رَأْسَهُ وَجَسَدَهُ". (خ)', 'അബൂഹുറൈറ(റ): നബി (സ) പറഞ്ഞു: "നാം അവസാന കാലക്കാരും അന്ത്യദിനത്തിൽ ആദ്യത്തവരുമാണ്. മുൻഗാമികൾക്ക് ഗ്രന്ഥങ്ങൾ നൽകപ്പെട്ടു. അവർക്ക് ശേഷം നമുക്കും. മുൻഗാമികൾ ഭിന്നിക്കുകയും നമുക്ക് അല്ലാഹു മാർഗ്ഗദർശനം നൽകുകയും ചെയ്ത ദിവസമാണിത്. നാളത്തെ ദിനം യഹൂദികളുടേത്, മറ്റന്നാൾ ക്രിസ്ത്യാനികളുടേതും." ശേഷം റസൂൽ(സ) മൗനം ദീക്ഷിച്ചു. പിന്നെ പറഞ്ഞു: "എല്ലാ ഏഴ് ദിവസങ്ങളിലും ഒരു ദിവസം ശിരസ്സും ശരീരവും കഴുകി കുളിക്കൽ ഓരോ മുസ്ലിമിനും ബാധ്യതയാണ്." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 345, 345, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنْ أَبِي لُبَابَةَ بْنِ عَبْدِ الْمُنْذِرِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ يَوْمَ الْجُمُعَةِ سَيِّدُ الْأَيَّامِ، وَأَعْظَمُهَا عِنْدَ اللَّهِ، وَهُوَ أَعْظَمُ عِنْدَ اللَّهِ مِنْ يَوْمِ الْأَضْحَى وَيَوْمِ الْفِطْرِ. فِيهِ خَمْسُ خِلَالٍ: خَلَقَ اللَّهُ فِيهِ آدَمَ، وَأَهْبَطَ اللَّهُ فِيهِ آدَمَ إِلَى الْأَرْضِ، وَفِيهِ تَوَفَّى اللَّهُ آدَمَ، وَفِيهِ سَاعَةٌ لَا يَسْأَلُ اللَّهَ فِيهَا الْعَبْدُ شَيْئًا إِلَّا أَعْطَاهُ مَا لَمْ يَسْأَلْ حَرَامًا، وَفِيهِ تَقُومُ السَّاعَةُ. مَا مِنْ مَلَكٍ مُقَرَّبٍ، وَلَا سَمَاءٍ وَلَا أَرْضٍ وَلَا رِيَاحٍ وَلَا جِبَالٍ وَلَا بَحْرٍ، إِلَّا وَهُنَّ يُشْفِقْنَ مِنْ يَوْمِ الْجُمُعَةِ". (م,جه)', 'അബീലുബാബതുബ്നു അബ്ദുൽമുൻദിർ(റ): നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ അടുക്കൽ ഏറ്റവും മഹത്വമുള്ളതും ദിവസങ്ങളുടെ നേതാവുമാണ് വെള്ളിയാഴ്ച ദിവസം. ബലി പെരുന്നാളിനെക്കാളും ഈദുൽ ഫിത്വ്റിനെക്കാളും മാഹാത്മ്യമുള്ള ദിവസമാണ് അല്ലാഹുവിന്റെയടുക്കൽ വെള്ളിയാഴ്ച ദിവസം. ആ ദിവസത്തിൽ അഞ്ച് കാര്യങ്ങളുണ്ട്; അല്ലാഹു ആദമി(അ)നെ സൃഷ്ടിക്കുകയും, ഭൂമിയിലേക്കയക്കുകയും, ആദമിനെ മരിപ്പിക്കുകയും ചെയ്ത ദിവസമാണത്. നിഷിദ്ധമല്ലാത്ത വല്ല കാര്യങ്ങളും ഒരു ദാസൻ അല്ലാഹുവിനോട് ചോദിച്ചാൽ അതിനുത്തരം ലഭിക്കുന്ന ഒരു പ്രത്യേക സമയം ഈ ദിവസത്തിലുണ്ട്. അന്ത്യദിനം ഈ ദിവസത്തിലായിരിക്കും. ദൈവ സാമീപ്യമുള്ള മലക്കുകളും, ആകാശവും, ഭൂമിയും, കാറ്റും, മലകളും, സമുദ്രവും വെള്ളിയാഴ്ച ദിനത്തിന്റെ കാര്യത്തിൽ (അന്ത്യ നാൾ സംഭവിക്കുന്ന ദിനമാണ് എന്നുള്ള നിലക്ക്) ഉൽകണ്ഠ കാണിക്കാതിരിക്കില്ല. (മു,ജ)', 'أَبِي لُبَابَةَ بْنِ عَبْدِ الْمُنْذِرِ', 'അബീലുബാബതുബ്നു അബ്ദുൽമുൻദിർ(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 346, 346, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنْ شَدَّادِ بْنِ أَوْسٍ رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ مِنْ أَفْضَلِ أَيَّامِكُمْ يَوْمَ الْجُمُعَةِ: فِيهِ خُلِقَ آدَمُ عَلَيْهِ السَّلَامِ، وَفِيهِ قُبِضَ وَفِيهِ النَّفْخَةُ، وَفِيهِ الصَّعْقَةُ. فَأَكْثِرُوا عَلَيَّ مِنَ الصَّلَاةِ فِيهِ، فَإِنَّ صَلَاتَكُمْ مَعْرُوضَةٌ عَلَيَّ". فَقَالَ الرَّجُلُ: يَا رَسُولَ اللهِ، وَكَيْفَ تُعْرَضُ صَلَاتُنَا عَلَيْكَ وَقَدْ أَرَمْتَ، يَعْنِي: قَدْ بَلِيتَ؟ فَقَالَ: "إِنَّ اللَّهَ عَزَّ وَجَلَّ قَدْ حَرَّمَ عَلَى الْأَرْضِ أَنْ تَأْكُلَ أَجْسَادَ الْأَنْبِيَاءِ عَلَيْهِمُ السَّلَامِ". (د,ت,ن,جه)', 'ശദ്ദാദുബ്നു ഔസ്(റ): നബി(സ) പറഞ്ഞു: "നിശ്ചയം, നിങ്ങളുടെ ദിവസങ്ങളിൽ ഏറ്റവും വിശിഷ്ടമായ ദിനം വെള്ളിയാഴ്ചയാണ്. ആദം(അ) സൃഷ്ടിക്കപ്പെട്ടതും വഫാത്തായതും ഈ ദിവസത്തിലാണ്. ഊത്തും, അട്ടഹാസവും (അവസാന നാളിന്റെ അടയാളങ്ങൾ) ഈ ദിനത്തിൽ തന്നെ. അതിനാൽ ഈ ദിനത്തിൽ നിങ്ങൾ എന്റെമേൽ സ്വലാത്ത് വർദ്ധിപ്പിക്കുക. നിങ്ങൾ ചൊല്ലുന്ന സ്വലാത്ത് എനിക്ക് വെളിവാക്കപ്പെടുന്നു." അപ്പോൾ ഒരാൾ ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരെ, ഞങ്ങൾ ചൊല്ലുന്ന സ്വലാത്ത് എങ്ങനെ അവിടുത്തേക്ക് വെളിവാക്കപ്പെടും. (വഫാത്തിനു ശേഷം) അവിടുത്തെ ശരീരം മണ്ണായിപ്പോകില്ലേ? അഥവാ നശിച്ച് പോകില്ലേ? പ്രവാചകൻ(സ) പ്രതിവചിച്ചു: "നിശ്ചയം, നബിമാരുടെ ശരീരം ഭക്ഷിക്കൽ ഭൂമിക്ക് അല്ലാഹു നിഷിദ്ധമാക്കിയിരിക്കുന്നു." (ദ,തു,ന,ജ)', 'شَدَّادِ بْنِ أَوْسٍ', 'ശദ്ദാദുബ്നു ഔസ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 346, 346, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْجُمُعَةُ إِلَى الْجُمُعَةِ كَفَّارَةُ مَا بَيْنَهُمَا، مَا لَمْ تُغْشَ الْكَبَائِرُ". (جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഒരു ജുമുഅ മറ്റൊരു ജുമുഅക്കിടയിലുള്ള ദോഷങ്ങൾക്കുള്ള പ്രായശ്ചിത്തമാണ്. വൻ ദോഷങ്ങളുമായി അവൻ ബന്ധപ്പെടാതിരിക്കുന്നിടത്തോളം കാലം (അതു പ്രായശ്ചിത്തമായി പരിഗണിക്കും)." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 346, 346, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "خَيْرُ يَوْمٍ طَلَعَتْ فِيهِ الشَّمْسُ يَوْمُ الْجُمُعَةِ: فِيهِ خُلِقَ آدَمُ، وَفِيهِ أُهْبِطَ، وَفِيهِ تِيبَ عَلَيْهِ، وَفِيهِ قُبِضَ، وَفِيهِ تَقُومُ السَّاعَةُ. مَا عَلَى الْأَرْضِ مِنْ دَابَّةٍ إِلَّا وَهِيَ تُصْبِحُ يَوْمَ الْجُمُعَةِ مُصِيخَةً حَتَّى تَطْلُعَ الشَّمْسُ، شَفَقًا مِنَ السَّاعَةِ، إِلَّا الْجِنَّ وَالْإِنْسَ، وَفِيهِ سَاعَةٌ لَا يُصَادِفُهَا عَبْدٌ مُسْلِمٌ وَهُوَ يُصَلِّي، يَسْأَلُ اللَّهَ حَاجَةً، إِلَّا أَعْطَاهُ إِيَّاهَا". قَالَ كَعْبٌ: ذَلِكَ فِي كُلِّ سَنَةٍ يَوْمٌ، فَقُلْتُ: بَلْ فِي كُلِّ جُمُعَةٍ. قَالَ: فَقَرَأَ كَعْبٌ التَّوْرَاةَ: فَقَالَ: صَدَقَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ أَبُو هُرَيْرَةَ: ثُمَّ لَقِيتُ عَبْدَ اللَّهِ بْنَ سَلَامٍ فَحَدَّثْتُهُ بِمَجْلِسِي مَعَ كَعْبٍ، فَقَالَ عَبْدُ اللَّهِ بْنُ سَلَامٍ: قَدْ عَلِمْتُ أَيَّةَ سَاعَةٍ هِيَ؟ قَالَ أَبُو هُرَيْرَةَ: فَقُلْتُ لَهُ: فَأَخْبِرْنِي بِهَا، فَقَالَ: عَبْدُ اللَّهِ بْنُ سَلَامٍ هِيَ آخِرُ سَاعَةٍ مِنْ يَوْمِ الْجُمُعَةِ. فَقُلْتُ: كَيْفَ هِيَ آخِرُ سَاعَةٍ مِنْ يَوْمِ الْجُمُعَةِ؟ وَقَدْ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا يُصَادِفُهَا عَبْدٌ مُسْلِمٌ وَهُوَ يُصَلِّي". وَتِلْكَ السَّاعَةُ لَا يُصَلِّي فِيهَا؟ فَقَالَ عَبْدُ اللَّهِ بْنُ سَلَامٍ: أَلَمْ يَقُلْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ جَلَسَ مَجْلِسًا يَنْتَظِرُ الصَّلَاةَ فَهُوَ فِي صَلَاةٍ حَتَّى يُصَلِّيَ". قَالَ: فَقُلْتُ: بَلَى، قَالَ: هُوَ ذَاكَ. (ق,د,ت,ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "സൂര്യനുദിക്കുന്ന ദിവസങ്ങളിലേറ്റവും വിശിഷ്ടമായ ദിനം വെള്ളിയാഴ്ചയാണ്. ഈ ദിവസത്തിൽ ആദം(അ) സൃഷ്ടിക്കപ്പെട്ടു. ഇതേ ദിനത്തിൽ (ആദമിനെ) സ്വർഗ്ഗത്തിൽ നിന്ന് താഴെയിറക്കി. (ആദമിന്റെ) തൗബ സ്വീകരിക്കപ്പെട്ടതും, ആദം മരണമടഞ്ഞതും ഈ ദിനത്തിൽ തന്നെ. വിധി നിർണ്ണയ നാൾ ഈ ദിവസത്തിലാണുണ്ടാകുക. അന്ത്യനാളിനെ ഭയന്ന്, മനുഷ്യരും ജിന്നുകളുമൊഴികെയുള്ള മറ്റു ജീവികൾ വെള്ളിയാഴ്ച ദിവസത്തിൽ സുബ്ഹ് മുതൽ സൂര്യനസ്തമിക്കുന്നതുവരെ ജാഗരൂകരാകുന്നതാണ്. ആ ദിവസത്തിൽ ഒരു സമയമുണ്ട്. ആ സമയത്ത് മുസ്ലിമായ ഒരു അടിമ നമസ്കാരത്തിലായിരിക്കെ, അല്ലാഹുവിനോട് തന്റെ ആവശ്യങ്ങൾ ചോദിക്കുകയാണെങ്കിൽ അല്ലാഹു അതവന് നൽകുക തന്നെ ചെയ്യും." കഅ്ബ്(റ) പറഞ്ഞു: ആ സമയം ഓരോ വർഷത്തിലും ഒരു ദിവസമാണ്. അപ്പോൾ ഞാൻ പറഞ്ഞു: അത് എല്ലാ വെള്ളിയാഴ്ച ദിവസത്തിലുമുണ്ട്. നിവേദകൻ പറയുന്നു: കഅ്ബ് തൗറാത്ത് ഓതിക്കേൾപ്പിച്ച് പറഞ്ഞു: നബി(സ) പറഞ്ഞത് സത്യമാണ്. അബൂഹുറൈറ(റ) പറഞ്ഞു: പിന്നീട് ഞാൻ അബ്ദുല്ലാഹിബ്നു സലാമി(റ)നെ കണ്ടുമുട്ടിയപ്പോൾ കഅ്ബുമായി നടന്ന സംഭാഷണത്തെക്കുറിച്ച് അദ്ദേഹത്തോട് പറഞ്ഞു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: അത് ഏതു സമയമാണെന്ന് ഞാൻ മനസ്സിലാക്കിയിട്ടുണ്ട്. അബൂഹുറൈറ(റ) പറയുന്നു: അതിനെപ്പറ്റി താങ്കളെനിക്ക് അറിയിച്ച് തന്നാലും എന്നു ഞാൻ അദ്ദേഹത്തോട് പറഞ്ഞു. അബ്ദുല്ലാഹിബ്നു സലാം(റ) പറഞ്ഞു: വെള്ളിയാഴ്ച ദിവസത്തിലെ അവസാന സമയമാണത്. ഞാൻ ചോദിച്ചു: വെള്ളിയാഴ്ചയിൽ നിന്ന് അവസാന സമയമാകുന്നതെങ്ങനെ? "നിസ്കരിച്ചു കൊണ്ടിരിക്കുന്ന ഒരടിമയും തന്റെ പ്രാർത്ഥനക്ക് ഉത്തരം ലഭിച്ചിട്ടല്ലാതെ ആ സമയവുമായി സന്ധിക്കുന്നില്ല." എന്നാണ് നബി(സ) പറഞ്ഞിരിക്കുന്നത്. ആ സമയത്ത് നാം നിസ്കരിക്കുകയില്ലല്ലോ? അപ്പോൾ അബ്ദുല്ലാഹിബ്നു സലാം പറഞ്ഞു: "ഒരാൾ ഒരു സ്ഥലത്ത് നിസ്കാരത്തെ പ്രതീക്ഷിച്ച് കൊണ്ടിരുന്നാൽ നിസ്കാരമാരംഭിക്കുന്നതു വരെ അവൻ നിസ്കാരത്തിൽ തന്നെയാണ്." എന്ന് നബി(സ) പറഞ്ഞിട്ടില്ലേ? (അബൂഹുറൈറ(റ) പറയുന്നു:) ഞാൻ പറഞ്ഞു: അതെ, അബ്ദുല്ലാഹിബ്നു സലാം(റ) പറഞ്ഞു: അത് തന്നെയാണിതിന്റെ ഉദ്ദേശ്യം. (ബു,മു,ദ,തു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 346, 347, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَيْتُ الطُّورَ فَوَجَدْتُ ثَمَّ كَعْبًا، فَمَكَثْتُ أَنَا وَهُوَ يَوْمًا أُحَدِّثُهُ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَيُحَدِّثُنِي عَنِ التَّوْرَاةِ، فَقُلْتُ لَهُ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "خَيْرُ يَوْمٍ طَلَعَتْ فِيهِ الشَّمْسُ يَوْمُ الْجُمُعَةِ، فِيهِ خُلِقَ آدَمُ، وَفِيهِ أُهْبِطَ، وَفِيهِ تِيبَ عَلَيْهِ، وَفِيهِ قُبِضَ، وَفِيهِ تَقُومُ السَّاعَةُ، مَا عَلَى الْأَرْضِ مِنْ دَابَّةٍ إِلَّا وَهِيَ تُصْبِحُ يَوْمَ الْجُمُعَةِ مُصِيخَةً حَتَّى تَطْلُعَ الشَّمْسُ، شَفَقًا مِنَ السَّاعَةِ، إِلَّا ابْنَ آدَمَ. وَفِيهِ سَاعَةٌ لَا يُصَادِفُهَا مُؤْمِنٌ – وَهُوَ فِي الصَّلَاةِ – يَسْأَلُ اللَّهَ فِيهَا شَيْئًا إِلَّا أَعْطَاهُ إِيَّاهُ". فَقَالَ كَعْبٌ: ذَلِكَ يَوْمٌ فِي كُلِّ سَنَةٍ؟ فَقُلْتُ: بَلْ هِيَ فِي كُلِّ جُمُعَةٍ. فَقَرَأَ كَعْبٌ التَّوْرَاةَ ثُمَّ قَالَ: صَدَقَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، هُوَ فِي كُلِّ جُمُعَةٍ. فَخَرَجْتُ فَلَقِيتُ بَصْرَةَ بْنَ أَبِي بَصْرَةَ الْغِفَارِيَّ رَضِيَ اللهُ عَنْهُ، فَقَالَ: مِنْ أَيْنَ جِئْتَ؟ قُلْتُ: مِنَ الطُّورِ. قَالَ: لَوْ لَقِيتُكَ مِنْ قَبْلِ أَنْ تَأْتِيَهُ لَمْ تَأْتِهِ. قُلْتُ لَهُ: وَلِمَ؟ قَالَ: إِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا تُعْمَلُ الْمَطِيُّ إِلَّا إِلَى ثَلَاثَةِ مَسَاجِدَ: الْمَسْجِدِ الْحَرَامِ، وَمَسْجِدِي، وَمَسْجِدِ بَيْتِ الْمَقْدِسِ". فَلَقِيتُ عَبْدَ اللَّهِ بْنَ سَلَامٍ فَقُلْتُ: لَوْ رَأَيْتَنِي خَرَجْتُ إِلَى الطُّورِ، فَلَقِيتُ كَعْبًا، فَمَكَثْتُ أَنَا وَهُوَ يَوْمًا أُحَدِّثُهُ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَيُحَدِّثُنِي عَنِ التَّوْرَاةِ، فَقُلْتُ لَهُ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "خَيْرُ يَوْمٍ طَلَعَتْ فِيهِ الشَّمْسُ يَوْمُ الْجُمُعَةِ، فِيهِ خُلِقَ آدَمُ، وَفِيهِ أُهْبِطَ، وَفِيهِ تِيبَ عَلَيْهِ، وَفِيهِ قُبِضَ، وَفِيهِ تَقُومُ السَّاعَةُ، مَا عَلَى الْأَرْضِ مِنْ دَابَّةٍ إِلَّا وَهِيَ تُصْبِحُ يَوْمَ الْجُمُعَةِ مُصِيخَةً حَتَّى تَطْلُعَ الشَّمْسُ، شَفَقًا مِنَ السَّاعَةِ إِلَّا ابْنَ آدَمَ. وَفِيهِ سَاعَةٌ لَا يُصَادِفُهَا عَبْدٌ مُؤْمِنٌ – وَهُوَ فِي الصَّلَاةِ – يَسْأَلُ اللَّهَ شَيْئًا إِلَّا أَعْطَاهُ إِيَّاهُ". قَالَ كَعْبٌ: ذَلِكَ يَوْمٌ فِي كُلِّ سَنَةٍ؟ فَقَالَ عَبْدُ اللَّهِ بْنُ سَلَامٍ: كَذَبَ كَعْبٌ. قُلْتُ: ثُمَّ قَرَأَ كَعْبٌ فَقَالَ: صَدَقَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، هُوَ فِي كُلِّ جُمُعَةٍ. فَقَالَ عَبْدُ اللَّهِ: صَدَقَ كَعْبٌ، إِنِّي لَأَعْلَمُ تِلْكَ السَّاعَةَ. فَقُلْتُ: يَا أَخِي حَدِّثْنِي بِهَا. قَالَ: هِيَ آخِرُ سَاعَةٍ مِنْ يَوْمِ الْجُمُعَةِ قَبْلَ أَنْ تَغِيبَ الشَّمْسُ. فَقُلْتُ: أَلَيْسَ قَدْ سَمِعْتَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا يُصَادِفُهَا مُؤْمِنٌ وَهُوَ فِي الصَّلَاةِ....". وَلَيْسَتْ تِلْكَ السَّاعَةُ صَلَاةً؟ قَالَ: أَلَيْسَ قَدْ سَمِعْتَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ صَلَّى وَجَلَسَ يَنْتَظِرُ الصَّلَاةَ لَمْ يَزَلْ فِي صَلَاتِهِ حَتَّى تَأْتِيَهُ الصَّلَاةُ الَّتِي تُلَاقِيهَا". قُلْتُ: بَلَى. قَالَ: فَهُوَ كَذَلِكَ. (ن)', 'അബൂഹുറൈറ(റ): ഞാൻ ത്വൂറിൽ പോയപ്പോൾ അവിടെ കഅ്ബ്(റ)വിനെ കണ്ടു. ഞാനും അദ്ദേഹവും അവിടെ ഒരു ദിവസം താമസിച്ചു. ഞാനദ്ദേഹത്തോട് നബിയെപ്പറ്റിയും അദ്ദേഹമെന്നോട് തൗറാത്തിനെപ്പറ്റിയും സംസാരിച്ചു. ഞാൻ പറഞ്ഞു: നബി(സ) പറഞ്ഞു: "സൂര്യനുദിച്ചതിൽ വെച്ചേറ്റവും നല്ല ദിവസം വെള്ളിയാഴ്ചയാണ്, അന്നാണ് ആദം(അ) സൃഷ്ടിക്കപ്പെട്ടത്. സ്വർഗ്ഗത്തിൽ നിന്ന് പുറത്താക്കപ്പെട്ടതും ആദം(അ)മിന്റ തൗബ സ്വീകരിക്കപ്പെട്ടതും ആദം(അ) മരിച്ചതും വെള്ളിയാഴ്ചയാണ്. അന്ത്യദിനം വെള്ളിയാഴ്ചയായിരിക്കും. വെള്ളിയാഴ്ച നേരം പുലർന്നാൽ മനുഷ്യരൊഴികെ മറ്റെല്ലാ മൃഗങ്ങളും സൂര്യനുദിക്കുന്നതുവരെ ജാഗരൂകരായിരിക്കും. ആ സമയത്തോടുള്ള ഭയം കാരണമാണത്. വെള്ളിയാഴ്ച ഒരു സമയമുണ്ട്, ആ സമയത്ത് ഏതെങ്കിലുമൊരു വിശ്വാസി നിസ്കരിച്ച് അല്ലാഹുവിനോട് ചോദിച്ചാൽ അല്ലാഹു അവൻ ചോദിച്ചത് നൽകും." കഅ്ബ് പറഞ്ഞു: അത് വർഷത്തിൽ ഒരു ദിവസമാണ്, ഞാൻ പറഞ്ഞു: അല്ല, എല്ലാ വെള്ളിയാഴ്ചയുമാണ്. അപ്പോൾ കഅ്ബ്(റ) തൗറാത്ത് പാരായണം ചെയ്തശേഷം പറഞ്ഞു: നബി(സ) സത്യം പറഞ്ഞു. അത് എല്ലാ വെള്ളിയാഴ്ചയുമാണ്. പിന്നെ ഞാൻ പുറത്തുപോയി ബസ്റതുബ്നു അബൂബസറതുൽ ഗിഫാരി(റ)വിനെ കണ്ടു, അദ്ദേഹം ചോദിച്ചു: താങ്കൾ എവിടെ നിന്നാണ് വരുന്നത്? ഞാൻ പറഞ്ഞു: ത്വൂറിൽ നിന്നാണ്. അദ്ദേഹം പറഞ്ഞു: താങ്കൾ അങ്ങോട്ടു പോവും മുമ്പ് ഞാൻ താങ്കളെ കണ്ടിരുന്നുവെങ്കിൽ താങ്കൾ അതിന്റെ അടുത്ത് പോവില്ലായിരുന്നു. ഞാൻ ചോദിച്ചു: എന്തുകൊണ്ട്? അദ്ദേഹം പറഞ്ഞു: നബി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "മൂന്ന് പള്ളികളിലേക്കല്ലാതെ വാഹനം കയറരുത്, ഒന്ന്, മസ്ജിദുൽ ഹറാം, രണ്ട്, എന്റെ പള്ളി. മൂന്ന്, മസ്ജിദുൽ അഖ്സ്വാ." പിന്നെ ഞാൻ അബ്ദുല്ലാഹിബ്നു സലാമിനെ കണ്ടു പറഞ്ഞു: ഞാൻ ത്വൂറിൽ പോയി കഅ്ബിനെ കണ്ട് ഒരു ദിവസം അവിടെ താമസിച്ചു. അദ്ദേഹം താനറിഞ്ഞതിനെപ്പറ്റിയും ഞാൻ നബിയെപ്പറ്റിയും പരസ്പരം സംസാരിച്ചു. ഞാൻ പറഞ്ഞു: നബി(സ) പറഞ്ഞു: "സൂര്യനുദിച്ചതിൽ വെച്ചേറ്റവും നല്ല ദിവസം വെള്ളിയാഴ്ചയാണ്, അന്നാണ് ആദം(അ) സൃഷ്ടിക്കപ്പെട്ടത്, സ്വർഗ്ഗത്തിൽ നിന്ന് പുറത്താക്കപ്പെട്ടതും ആദം(അ)മിന്റെ തൗബ സ്വീകരിക്കപ്പെട്ടതും ആദം(അ) മരിച്ചതും അന്നുതന്നെയാണ്, അന്നു തന്നെയാണ് അന്ത്യദിനം സംഭവിക്കുക. വെള്ളിയാഴ്ച നേരം പുലർന്നാൽ മനുഷ്യരൊഴികെ മറ്റെല്ലാ മൃഗങ്ങളും സൂര്യനുദിക്കുന്നതുവരെ ജാഗരൂകരായിരിക്കും. ആ സമയത്തോടുള്ള ഭയം കാരണമാണത്. വെള്ളിയാഴ്ച ഒരു സമയമുണ്ട്, ആ സമയത്ത് ഏതെങ്കിലുമൊരു വിശ്വാസി നിസ്കരിച്ച് അല്ലാഹുവിനോട് ചോദിച്ചാൽ അല്ലാഹു അവൻ ചോദിച്ചത് നൽകാതിരിക്കില്ല." കഅ്ബ്(റ) പറഞ്ഞു: അത് വർഷത്തിൽ ഒരു ദിവസമാണ്. അബ്ദുല്ലാഹിബ്നു സലാം(റ) പറഞ്ഞു: കഅ്ബ് കള്ളം പറഞ്ഞിരിക്കുന്നു. ഞാൻ പറഞ്ഞു: കഅ്ബ് ഓതുകയും പിന്നെ പറയുകയും ചെയ്തു: നബി(സ) സത്യം പറഞ്ഞു, അത് എല്ലാ വെള്ളിയാഴ്ചയുമാണ്. അപ്പോൾ അബ്ദുല്ല(റ) പറഞ്ഞു: കഅ്ബ് സത്യം പറഞ്ഞു, ഞാൻ ആ സമയത്തെ അറിയും. ഞാൻ പറഞ്ഞു: സഹോദരാ, എനിക്കത് പറഞ്ഞു തരിക! അദ്ദേഹം പറഞ്ഞു: വെള്ളിയാഴ്ച സൂര്യനസ്തമിക്കുന്നതിനു തൊട്ടുമുമ്പുള്ള സമയമാണത്. ഞാൻ ചോദിച്ചു: "ഒരു വിശ്വാസി നിസ്കാരത്തിൽ ആയിരിക്കെ ആസമയം ആസന്നമായാൽ...." എന്ന് നബി(സ) പറയുന്നത് നീ കേട്ടിട്ടില്ലേ? എന്നാൽ ആ സമയമാകട്ടെ നിസ്കാരം നിർവ്വഹിക്കാറുള്ള സമയമല്ല താനും! അദ്ദേഹം പറഞ്ഞു: "ആരെങ്കിലും നിസ്കരിച്ച് മറ്റൊരു നിസ്കാരത്തെ പ്രതീക്ഷിച്ചിരുന്നാൽ അവൻ അടുത്ത നിസ്കാരം വരെ നിസ്കാരത്തിലാണ്." എന്ന് നബി(സ) പറയുന്നത് നീ കേട്ടിട്ടില്ലേ? ഞാൻ പറഞ്ഞു: അതെ. അദ്ദേഹം പറഞ്ഞു: എന്നാലത് അപ്രകാരമാണ്. (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 347, 349, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ تَوَضَّأَ فَأَحْسَنَ الْوُضُوءَ، ثُمَّ أَتَى الْجُمُعَةَ وَأَنْصَتَ وَاسْتَمَعَ، غُفِرَ لَهُ مَا بَيْنَهُ وَبَيْنَ الْجُمُعَةِ الْأُخْرَى وَزِيَادَةُ ثَلَاثَةِ أَيَّامٍ، وَمَنْ مَسَّ الْحَصَى فَقَدْ لَغَا". (م,د,ت,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഒരാൾ നന്നായി വുദു ചെയ്തു, പിന്നെ ജുമുഅക്ക് ചെന്നു (ഖുത്വുബ) ശ്രദ്ധിച്ചു കേൾക്കുകയും മൗനം ദീക്ഷിക്കുകയും ചെയ്താൽ ഒരു ജുമുഅഃ മുതൽ മറ്റൊരു ജുമുഅഃ വരെയുള്ളതും പുറമെ മൂന്ന് ദിവസത്തെയും ദോഷങ്ങൾ അവന് പൊറുക്കപ്പെടും. വല്ലവരും ചരൽകല്ലുകൾ സ്പർശിച്ചാൽ (ശ്രദ്ധതിരിയും വിധം വല്ല പ്രവർത്തനത്തിലുമേർപ്പെട്ടാൽ) അവൻ നിരർത്ഥകവും ആക്ഷേപാർഹവുമായ കാര്യം ചെയ്തു." (മു,ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ت','جه']::text[], array['മു','ദ','തു','ജ']::text[], null, null, 349, 349, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ عَلَى مِنْبَرِ الْكُوفَةِ: "إِذَا كَانَ يَوْمُ الْجُمُعَةِ غَدَتِ الشَّيَاطِينُ بِرَايَاتِهَا إِلَى الْأَسْوَاقِ، فَيَرْمُونَ النَّاسَ بِالتَّرَابِيثِ، أَوِ الرَّبَائِثِ، وَيُثَبِّطُونَهُمْ عَنِ الْجُمُعَةِ. وَتَغْدُو الْمَلَائِكَةُ فَيَجْلِسُونَ عَلَى أَبْوَابِ الْمَسْجِدِ، فَيَكْتُبُونَ الرَّجُلَ مِنْ سَاعَةٍ وَالرَّجُلَ مِنْ سَاعَتَيْنِ حَتَّى يَخْرُجَ الْإِمَامُ، فَإِذَا جَلَسَ الرَّجُلُ مَجْلِسًا يَسْتَمْكِنُ فِيهِ مِنَ الِاسْتِمَاعِ وَالنَّظَرِ فَأَنْصَتَ وَلَمْ يَلْغُ كَانَ لَهُ كِفْلَانِ مِنْ أَجْرٍ، فَإِنْ نَأَى وَجَلَسَ حَيْثُ لَا يَسْمَعُ فَأَنْصَتَ وَلَمْ يَلْغُ لَهُ كِفْلٌ مِنْ أَجْرٍ، وَإِنْ جَلَسَ مَجْلِسًا يَسْتَمْكِنُ فِيهِ مِنَ الِاسْتِمَاعِ وَالنَّظَرِ فَلَغَا وَلَمْ يُنْصِتْ كَانَ لَهُ كِفْلٌ مِنْ وِزْرٍ، وَمَنْ قَالَ يَوْمَ الْجُمُعَةِ لِصَاحِبِهِ: صَهْ فَقَدْ لَغَا، وَمَنْ لَغَا فَلَيْسَ لَهُ فِي جُمُعَتِهِ تِلْكَ شَيْءٌ". ثُمَّ يَقُولُ فِي آخِرِ ذَلِكَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ ذَلِكَ. (د)', 'അലി(റ): കൂഫയിലെ മിമ്പറിൽ വെച്ച് അലി(റ) പറഞ്ഞു: "വെള്ളിയാഴ്ച ദിവസമായാൽ പിശാചുകൾ അവരുടെ പതാകകളുമായി രാവിലെ അങ്ങാടിയിലേക്ക് പുറപ്പെടുന്നു. അങ്ങനെ അവർ ചതികളും വഞ്ചനകളുമെറിയുകയും ജുമുഅയിൽ നിന്ന് ജനങ്ങളെ തടയുകയും ചെയ്യുന്നു. മലക്കുകൾ അതിരാവിലെ പുറപ്പെട്ട് പള്ളിയുടെ വാതിലിൽ ഇരിക്കുന്നു. ഇമാം പുറപ്പെടുന്നതുവരെ ഓരോരുത്തരും വന്ന സമയം അവർ രേഖപ്പെടുത്തുന്നു. അങ്ങനെ ഒരാൾ കടന്നുവന്ന് ഖുത്വുബ സശ്രദ്ധം വീക്ഷിക്കാൻ സൗകര്യപ്രദമായ സ്ഥലത്ത് ഇരുന്ന് മൗനം ദീക്ഷിക്കുകയും നിരർത്ഥകങ്ങൾ ഒഴിവാക്കുകയും ചെയ്താൽ അവന് പ്രതിഫലത്തിൽ നിന്ന് രണ്ടോഹരിയുണ്ട്. ഇനി ഒരാൾ കേൾക്കാൻ കഴിയാത്തത്ര ദൂരെ ഇരുന്നു. നിരർത്ഥകങ്ങളൊന്നും ചെയ്യാതെ മൗനം ദീക്ഷിച്ചു. എന്നാൽ അവന് പ്രതിഫലത്തിൽ നിന്ന് ഒരോഹരിയുണ്ട്. ഇനി ഒരാൾ കാണാനും ശ്രദ്ധിച്ച് കേൾക്കാനും സാധിക്കുന്ന വിധത്തിൽ ഇരുന്ന് മൗനം ദീക്ഷിക്കാതെ, പ്രതിഫലം നഷ്ടപ്പെടുത്തുന്ന കാര്യങ്ങൾ പ്രവർത്തിക്കുകയും ചെയ്താൽ അവന് കുറ്റത്തിൽ ഒരംശവുമുണ്ട്. ജുമുഅഃ ദിവസം ഒരാൾ തന്റെ സുഹൃത്തിനോട് ''മിണ്ടാതിരിക്ക്'' എന്നു പറഞ്ഞാൽ അവൻ നിരർത്ഥകമാകുന്ന കാര്യം പ്രവർത്തിച്ചു. വല്ലവനും നിരർത്ഥകമാകുന്ന കാര്യങ്ങൾ പ്രവർത്തിച്ചാൽ അവന് അവന്റെ ജുമുഅയിൽ നിന്ന് ഒന്നും ഉണ്ടാവുകയില്ല. അതിന്റെ അവസാനത്തിൽ അലി(റ) പറഞ്ഞു: നബി(സ) ഇപ്രകാരം പറയുന്നത് ഞാൻ കേട്ടിരിക്കുന്നു. (ദ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 349, 350, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنْ سَلْمَانَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا مِنْ رَجُلٍ يَتَطَهَّرُ يَوْمَ الْجُمُعَةِ كَمَا أُمِرَ، ثُمَّ يَخْرُجُ مِنْ بَيْتِهِ حَتَّى يَأْتِيَ الْجُمُعَةَ، وَيُنْصِتُ حَتَّى يَقْضِيَ صَلَاتَهُ، إِلَّا كَانَ كَفَّارَةً لِمَا قَبْلَهُ مِنَ الْجُمُعَةِ". (ن)', 'സൽമാൻ(റ): നബി(സ) എന്നോട് പറഞ്ഞു: "കൽപിക്കപ്പെട്ട പ്രകാരം വെള്ളിയാഴ്ച ശുദ്ധിയാവുകയും, തന്റെ വീട്ടിൽ നിന്ന് ജുമുഅക്കു പുറപ്പെടുകയും, നിസ്കാരം തീരുംവരെ നിശ്ശബ്ദനായിരിക്കുകയും ചെയ്താൽ അതവന് കഴിഞ്ഞ വെള്ളിയാഴ്ച മുതലുള്ള സർവ്വ പാപങ്ങൾക്കും പ്രായശ്ചിത്തമായിരിക്കും." (ന)', 'سَلْمَانَ', 'സൽമാൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 350, 350, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا: عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يَحْضُرُ الْجُمُعَةَ ثَلَاثَةُ نَفَرٍ: رَجُلٌ حَضَرَهَا يَلْغُو، وَهُوَ حَظُّهُ مِنْهَا. وَرَجُلٌ حَضَرَهَا يَدْعُو، فَهُوَ رَجُلٌ دَعَا اللَّهَ عَزَّ وَجَلَّ. إِنْ شَاءَ أَعْطَاهُ، وَإِنْ شَاءَ مَنَعَهُ. وَرَجُلٌ حَضَرَهَا بِإِنْصَاتٍ وَسُكُوتٍ، وَلَمْ يَتَخَطَّ رَقَبَةَ مُسْلِمٍ وَلَمْ يُؤْذِ أَحَدًا، فَهِيَ كَفَّارَةٌ إِلَى الْجُمُعَةِ الَّتِي تَلِيهَا وَزِيَادَةُ ثَلَاثَةِ أَيَّامٍ. وَذَلِكَ بِأَنَّ اللَّهَ عَزَّ وَجَلَّ يَقُولُ: {مَنْ جَاءَ بِالْحَسَنَةِ فَلَهُ عَشْرُ أَمْثَالِهَا}. (د)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) പറഞ്ഞു: "മൂന്നു വിഭാഗങ്ങൾ ജുമുഅക്കു വരും; ഒരുകൂട്ടർ അനാവശ്യങ്ങൾ ചെയ്യും. അതിന്റെ വിഹിതം അവനു ലഭിക്കും. ഒരുകൂട്ടർ പ്രാർത്ഥിക്കാൻ വേണ്ടി വരും. അവർ അല്ലാഹുവോട് പ്രാർത്ഥിക്കും. അവനുദ്ദേശിച്ചാൽ ഉത്തരം നൽകും, ഇല്ലെങ്കിൽ നൽകില്ല. ഒരുകൂട്ടർ ശാന്തരായി നിശ്ശബ്ദരായി വരും, ഒരു മുസ്ലിമിന്റെയും പിരടിയിലൂടെ ചാടിക്കടക്കുകയോ ബുദ്ധിമുട്ടിക്കുകയോ ഇല്ല. അതവന്ന് ഒരു ജുമുഅഃ മുതൽ അടുത്ത ജുമുഅഃ വരെയുള്ള പ്രായശ്ചിത്തമാണ്. അല്ലാഹു പറയുന്നു: ''ആരെങ്കിലുമൊരു നന്മ ചെയ്താൽ അവന് പത്തിരട്ടി പ്രതിഫലം ലഭിക്കും." (ദ)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 350, 350, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ أَبُو الْقَاسِمِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ فِي الْجُمُعَةِ لَسَاعَةً، لَا يُوَافِقُهَا مُسْلِمٌ وَهُوَقَائِمٌ يُصَلِّي، يَسْأَلُ اللَّهَ خَيْرًا إِلَّا أَعْطَاهُ إِيَّاهُ ". وَقَالَ بِيَدِهِ يُقَلِّلُهَا: يُزَهِّدُهَا. (ق,جه)', 'അബൂഹുറൈറ(റ): അബുൽഖാസിം(സ) പറഞ്ഞു: "നിശ്ചയം, വെള്ളിയാഴ്ച ദിനത്തിൽ ഒരു സമയമുണ്ട്. പ്രാർത്ഥനാ നിരതനായി ഒരു മുസ്ലിം ആ സമയത്ത് വല്ല നല്ല കാര്യവും അല്ലാഹുവിനോട് ചോദിച്ചാൽ അല്ലാഹു അവനത് നൽകാതിരിക്കുകയില്ല." റിപ്പോർട്ടർ പറയുന്നു: റസൂൽ(സ) കൈ കൊണ്ട് അത് അൽപ്പം സമയമേ ഉള്ളൂവെന്ന് ആംഗ്യം കാണിച്ചു. (ബു,മു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 350, 350, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُ: عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: "يَوْمُ الْجُمُعَةِ ثِنْتَا عَشْرَةَ – يُرِيدُ سَاعَةً – لَا يُوجَدُ مُسْلِمٌ يَسْأَلُ اللَّهَ عَزَّ وَجَلَّ شَيْئًا، إِلَّا أَتَاهُ اللَّهُ عَزَّ وَجَلَّ، فَالْتَمِسُوهَا آخِرَ سَاعَةٍ بَعْدَ الْعَصْرِ". (د,ن)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): നബി(സ) പറഞ്ഞു: "വെള്ളിയാഴ്ച ദിവസം പന്ത്രണ്ടാകുന്നു. - പന്ത്രണ്ട് എന്നതുകൊണ്ട് നബി(സ) സമയത്തെയാണ് ഉദ്ദേശിച്ചത് - മുസ്ലിമായ ഒരാൾ അല്ലാഹുവിനോട് എന്തെങ്കിലും ചോദിച്ചാൽ അല്ലാഹു അതവന് നൽകാതിരിക്കില്ല. അതിനാൽ അസ്റിനു ശേഷമുള്ള അവസാന സമയത്ത് നിങ്ങൾ അതന്വേഷിക്കുക." (ദ,ന)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 350, 350, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنْ أَبِي بُرْدَةَ بْنِ أَبِي مُوسَى الْأَشْعَرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ لِي عَبْدُ اللَّهِ بْنُ عُمَرَ: أَسَمِعْتَ أَبَاكَ يُحَدِّثُ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي شَأْنِ الْجُمُعَةِ، يَعْنِي السَّاعَةَ؟ قَالَ: قُلْتُ: نَعَمْ، سَمِعْتُهُ يَقُولُ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "هِيَ مَا بَيْنَ أَنْ يَجْلِسَ الْإِمَامُ إِلَى أَنْ تُقْضَى الصَّلَاةُ". قَالَ أَبُو دَاوُدَ: يَعْنِي عَلَى الْمِنْبَرِ. (د)', 'അബീബുർദതുബ്നു അബീമൂസൽ അശ്അരി(റ): അബിദുല്ലാഹിബ്നു ഉമർ(റ) എന്നോട് ചോദിച്ചു: വെള്ളിയാഴ്ചയിലെ സമയത്തെപ്പറ്റി വല്ല ഹദീസും റസൂലി(സ)ൽ നിന്നും താങ്കളുടെ പിതാവ് ഉദ്ധരിക്കുന്നതായി താങ്കൾ കേട്ടുവോ? ഞാൻ പറഞ്ഞു: അതെ, അദ്ദേഹം ഇപ്രകാരം പറയുന്നത് ഞാൻ കേട്ടു: റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ഇമാം ഇരിക്കുന്നതു മുതൽ നിസ്കാരം നിർവ്വഹിക്കുന്നതിന്റെ ഇടയിലുള്ള സമയമാണത്." അബൂദാവൂദ് പറയുന്നു: മിമ്പറിൻ മേൽ (ഇരിക്കുന്നതു മുതൽ) എന്നാണദ്ദേഹം ഉദ്ദേശിച്ചത്. (ദ)', 'أَبِي بُرْدَةَ بْنِ أَبِي مُوسَى الْأَشْعَرِيِّ', 'അബീബുർദതുബ്നു അബീമൂസൽ അശ്അരി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 351, 351, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنْ عَبْدِ اللَّهِ بْنِ سَلَامٍ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْتُ وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَالِسٌ: إِنَّا لَنَجِدُ فِي كِتَابِ اللَّهِ: فِي يَوْمِ الْجُمُعَةِ سَاعَةً، لَا يُوَافِقُهَا عَبْدٌ مُؤْمِنٌ يُصَلِّي يَسْأَلُ اللَّهَ فِيهَا شَيْئًا، إِلَّا قَضَى لَهُ حَاجَتَهُ. قَالَ عَبْدُ اللَّهِ: فَأَشَارَ إِلَيَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَوْ بَعْضُ سَاعَةٍ. فَقُلْتُ: صَدَقْتَ، أَوْ بَعْضُ سَاعَةٍ. قُلْتُ: أَيُّ سَاعَةٍ هِيَ؟ قَالَ: "هِيَ آخِرُ سَاعَاتِ النَّهَارِ". قُلْتُ: إِنَّهَا لَيْسَتْ سَاعَةَ صَلَاةٍ؟ قَالَ: "بَلَى، إِنَّ الْعَبْدَ الْمُؤْمِنَ إِذَا صَلَّى ثُمَّ جَلَسَ، لَا يَحْبِسُهُ إِلَّا الصَّلَاةُ، فَهُوَ فِي الصَّلَاةِ". (جه)', 'അബ്ദുല്ലാഹിബ്നു സലാം(റ): റസൂൽ(സ) ഇരിക്കുമ്പോൾ ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ ഗ്രന്ഥത്തിൽ വെള്ളിയാഴ്ച ദിവസത്തെ ഒരു സമയത്തെക്കുറിച്ച് ഇങ്ങനെ കാണുന്നു: ഒരു മുസ്ലിമായ അടിമ നിസ്കാരത്തിലായിരിക്കെ ആ സമയത്ത് അല്ലാഹുവിനോട് വല്ലതും ആവശ്യപ്പെട്ടാൽ അല്ലാഹു അവന്റെ ആവശ്യങ്ങൾ നിർവ്വഹിച്ചു കൊടുക്കുന്നതാണ്. അബ്ദുല്ല(റ) പറഞ്ഞു: അത് സ്വല്പം സമയമേ ഉള്ളൂവെന്ന് നബി(സ) ആംഗ്യം കാണിച്ചു. അതെ കുറഞ്ഞ സമയം. ഞാൻ പ്രതികരിച്ചു. തുടർന്ന് ഞാൻ ചോദിച്ചു: അത് ഏത് സമയമാണ്? നബി(സ) പറഞ്ഞു: "അത് പകലിന്റെ അന്ത്യ സമയമാണ്." ഞാൻ ചോദിച്ചു: അത് നിസ്കാര സമയമല്ലല്ലോ? നബി(സ) പറഞ്ഞു: "അതെ, ഒരു വിശ്വാസിയായ ദാസൻ നിസ്കരിക്കുകയും പിന്നെ നിസ്കാരം പ്രതീക്ഷിച്ചിരിക്കുകയും ചെയ്താൽ അവൻ നിസ്കാരത്തിലാണ്." (ജ)', 'عَبْدِ اللَّهِ بْنِ سَلَامٍ', 'അബ്ദുല്ലാഹിബ്നു സലാം(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 351, 351, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنْ عَمْرِو بْنِ عَوْفٍ الْمُزَنِيِّ رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ فِي الْجُمُعَةِ سَاعَةً: لَا يَسْأَلُ اللَّهَ الْعَبْدُ فِيهَا شَيْئًا إِلَّا آتَاهُ اللَّهُ إِيَّاهُ". قَالُو: يَا رَسُولَ اللَّهِ، أَيَّةُ سَاعَةٍ هِيَ؟ قَالَ: "حِينَ تُقَامُ الصَّلَاةُ إِلَى الِانْصِرَافِ مِنْهَا". حَسَنٌ غَرِيبٌ. (ت)', 'അംറുബ്നു ഔഫിൽ മുസ്നി(റ): റസൂൽ(സ) പറഞ്ഞു: "വെള്ളിയാഴ്ച ഒരു പ്രത്യേക സമയമുണ്ട്. ആ സമയത്ത് അല്ലാഹുവിനോട് എന്ത് ചോദിച്ചാലും അല്ലാഹു അവനത് നൽകും." അവർ ചോദിച്ചു: പ്രവാചകരേ! ഏതാണാ സമയം? നബി(സ) പറഞ്ഞു: "നിസ്കാരത്തിന് ഇഖാമത്ത് കൊടുത്തതു മുതൽ നിസ്കാരം കഴിയുന്നത് വരെയുള്ള സമയം." ഹദീസ് ഹസനും ഗരീബുമാണ്. (തു)', 'عَمْرِو بْنِ عَوْفٍ الْمُزَنِيِّ', 'അംറുബ്നു ഔഫിൽ മുസ്നി(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 351, 351, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 18, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَنَّهُ قَالَ: "الْتَمِسُوا السَّاعَةَ الَّتِي تُرْجَى فِي يَوْمِ الْجُمُعَةِ بَعْدَ الْعَصْرِ إِلَى غَيْبُوبَةِ الشَّمْسِ". (ت)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) പറഞ്ഞു: "ജുമുഅഃ ദിവസം പ്രതീക്ഷിത സമയത്തെ നിങ്ങൾ അസ്റ് കഴിഞ്ഞതു മുതൽ സൂര്യാസ്തമയം വരെ അന്വേഷിക്കുക". (തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 351, 351, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 19, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: خَطَبَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "يَا أَيُّهَا النَّاسُ، تُوبُوا إِلَى اللَّهِ قَبْلَ أَنْ تَمُوتُوا، وَبَادِرُوا بِالْأَعْمَالِ الصَّالِحَةِ قَبْلَ أَنْ تُشْغَلُوا، وَصِلُوا الَّذِي بَيْنَكُمْ وَبَيْنَ رَبِّكُمْ بِكَثْرَةِ ذِكْرِكُمْ لَهُ، وَكَثْرَةِ الصَّدَقَةِ فِي السِّرِّ وَالْعَلَانِيَةِ، تُرْزَقُوا وَتُنْصَرُوا وَتُجْبَرُوا. وَاعْلَمُوا أَنَّ اللَّهَ قَدِ افْتَرَضَ عَلَيْكُمُ الْجُمُعَةَ فِي مَقَامِي هَذَا، فِي يَوْمِي هَذَا، فِي شَهْرِي هَذَا، مِنْ عَامِي هَذَا، إِلَى يَوْمِ الْقِيَامَةِ. فَمَنْ تَرَكَهَا فِي حَيَاتِي أَوْ بَعْدِي، وَلَهُ إِمَامٌ عَادِلٌ أَوْ جَائِرٌ، اسْتِخْفَافًا بِهَا أَوْ جُحُودًا لَهَا، فَلَا جَمَعَ اللَّهُ لَهُ شَمْلَهُ، وَلَا بَارَكَ لَهُ فِي أَمْرِهِ. أَلَا، وَلَا صَلَاةَ لَهُ، وَلَا زَكَاةَ لَهُ، وَلَا حَجَّ لَهُ، وَلَا صَوْمَ لَهُ، وَلَا بِرَّ لَهُ، حَتَّى يَتُوبَ، فَمَنْ تَابَ تَابَ اللَّهُ عَلَيْهِ. أَلَا، لَا تَؤُمَّنَّ امْرَأَةٌ رَجُلًا، وَلَا يَؤُمَّ أَعْرَابِيٌّ مُهَاجِرًا، وَلَا يَؤُمَّ فَاجِرٌ مُؤْمِنًا، إِلَّا أَنْ يَقْهَرَهُ بِسُلْطَانٍ، يَخَافُ سَيْفَهُ وَسَوْطَهُ". [ز: في إسناده ضعيف] (جه)', 'ജാബിറുബ്നു അബ്ദുല്ല(റ): നബി(സ) ഞങ്ങളെ അഭിസംബോധന ചെയ്ത് പ്രസംഗിച്ചു കൊണ്ടിരിക്കെ പറഞ്ഞു: "ജനങ്ങളേ, നിങ്ങളെ മരണം പിടികൂടുന്നതിനു മുമ്പായി അല്ലാഹുവിനോട് പൊറുക്കലിനെ തേടുക. നിങ്ങൾക്ക് രോഗം വരുന്നതിന് മുമ്പായി സൽകർമ്മങ്ങൾ പ്രവർത്തിക്കുന്നതിൽ ധൃതി കാണിക്കുക. നിങ്ങളും നിങ്ങളുടെ നാഥനും തമ്മിലുള്ള ബന്ധം അവനോട് ദിക്റുകൾ അധികരിപ്പിച്ചും രഹസ്യമായും പരസ്യമായും നിങ്ങൾ സ്വദഖ(ദാനധർമ്മം)കൾ അധികരിപ്പിച്ചും ഊട്ടിയുറപ്പിക്കുക. അപ്പോൾ നിങ്ങൾക്ക് രിസ്ഖ് (വിഭവങ്ങൾ) നൽകപ്പെടുകയും സഹായിക്കപ്പെടുകയും, പ്രായശ്ചിത്തം നൽകപ്പെടുകയും ചെയ്യും. ഈ സ്ഥലത്ത് വെച്ച്, ഈ ദിവസത്തിൽ, ഈ മാസത്തിൽ, ഈ വർഷത്തിൽ, അന്ത്യനാൾ വരേക്കുമായി അല്ലാഹു നിങ്ങൾക്ക് ജുമുഅഃ നിർബന്ധമാക്കിയിരിക്കുന്നു എന്ന് നിങ്ങൾ അറിയുക. ഞാൻ ജീവിച്ചിരിക്കുമ്പോഴോ അല്ലെങ്കിൽ എനിക്ക് ശേഷമോ വല്ലവനും അവന് നീതിമാനായ അല്ലെങ്കിൽ അനീതി പ്രവർത്തിക്കുന്നവനായ ഒരു ഇമാം ഉണ്ടായിരിക്കെ, അതിനെ (ജുമഅയെ) നിഷേധിച്ചു കൊണ്ടോ നിന്ദിച്ചു കൊണ്ടോ അതുപേക്ഷിച്ചാൽ അവന്റെ കാര്യത്തിൽ അല്ലാഹു അനുഗ്രഹം ചൊരിയുകയില്ല. അറിയുക, അവന് നിസ്കാരമില്ല, ഹജ്ജും സകാത്തും നോമ്പും ഇല്ല. അവന് പുണ്യവും ഇല്ല. അവൻ പശ്ചാത്തപിക്കുന്നത് വരെ, ആരെങ്കിലും പശ്ചാത്തപിച്ചാൽ അല്ലാഹു അവന് പൊറുത്തു കൊടുക്കും. അറിയുക, ഒരു സ്ത്രീയും ഒരു പുരുഷന് ഇമാം നിൽക്കരുത്, ഒരു അഅ്റാബിയും ഒരു മുഹാജിറിന് ഇമാം നിൽക്കരുത് ഒരു ദുർമാർഗ്ഗിയും ഒരു വിശ്വാസിക്ക് ഇമാമാകരുത്. വാളും വടിയും കൊണ്ട് ഭയപ്പെടുത്തുന്ന ഒരു ഭരണാധികാരി മുഖേന നിർബന്ധിക്കപ്പെട്ടാലല്ലാതെ." [ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ] (ജ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദുല്ല(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', null, 352, 352, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 20, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ كَعْبِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمْ قَالَ: كُنْتُ قَائِدَ أَبِي حِينَ ذَهَبَ بَصَرُهُ، فَكُنْتُ إِذَا خَرَجْتُ بِهِ إِلَى الْجُمُعَةِ فَسَمِعَ الْأَذَانَ اسْتَغْفَرَ لِأَبِي أُمَامَةَ أَسْعَدَ بْنِ زُرَارَةَ، وَدَعَا لَهُ. فَمَكَثْتُ حِينًا أَسْمَعُ ذَلِكَ مِنْهُ ثُمَّ قُلْتُ فِي نَفْسِي: وَاللَّهِ إِنَّ ذَا لَعَجْزٌ، إِنِّي أَسْمَعُهُ كُلَّمَا سَمِعَ أَذَانَ الْجُمُعَةِ يَسْتَغْفِرُ لِأَبِي أُمَامَةَ وَيُصَلِّي عَلَيْهِ، وَلَا أَسْأَلُهُ عَنْ ذَلِكَ لِمَ هُوَ؟ فَخَرَجْتُ بِهِ كَمَا كُنْتُ أَخْرُجُ بِهِ إِلَى الْجُمُعَةِ، فَلَمَّا سَمِعَ الْأَذَانَ اسْتَغْفَرَ كَمَا كَانَ يَفْعَلُ، فَقُلْتُ لَهُ: يَا أَبَتَاهُ، أَرَأَيْتَكَ صَلَاتَكَ عَلَى أَسْعَدَ بْنِ زُرَارَةَ كُلَّمَا سَمِعْتَ النِّدَاءَ بِالْجُمُعَةِ، لِمَ هُوَ؟ قَالَ: أَيْ بُنَيَّ، كَانَ أَوَّلَ مَنْ صَلَّى بِنَا صَلَاةَ الْجُمُعَةِ قَبْلَ مَقْدَمِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ مَكَّةَ، فِي نَقِيعِ الْخَضَمَاتِ، فِي هَزْمٍ مِنْ حَرَّةِ بَنِي بَيَاضَةَ. قُلْتُ: كَمْ كُنْتُمْ يَوْمَئِذٍ؟ قَالَ: أَرْبَعِينَ رَجُلًا. (د,جه)', 'അബ്ദുർറഹ്മാനുബ്നു കഅ്ബ്(റ): എന്റെ പിതാവിന്റെ കാഴ്ച ശക്തി നഷ്ടപ്പെട്ടപ്പോൾ ഞാനായിരുന്നു കൈ പിടിച്ചിരുന്നത്. ഞാൻ പിതാവിനെയും കൂട്ടി ജുമുഅക്ക് പുറപ്പെട്ടു. അപ്പോൾ ബാങ്ക് കേട്ടു. പിതാവ് അബൂഉമാമ അസ്അദുബ്നു സുറാറക്കു വേണ്ടി പൊറുക്കലിനെ തേടുകയും പ്രാർത്ഥിക്കുകയും ചെയ്തു. ഇതുകേട്ടപ്പോൾ ഞാൻ മനസ്സിൽ പറഞ്ഞു: അല്ലാഹുവാണെ, ജുമുഅയുടെ ബാങ്ക് കേൾക്കുമ്പോഴൊക്കെ പിതാവ് അബൂഉമാമക്ക് വേണ്ടി പൊറുക്കലിനെ തേടുന്നതും പ്രാർത്ഥിക്കുന്നതും ഞാൻ കേൾക്കുന്നു. കുറച്ചു സമയം കാത്തുനിന്നു. എന്നിട്ടെന്തുകൊണ്ട് ഞാൻ പിതാവിനോട് ചോദിക്കുന്നില്ല? ഇതു വല്ലാത്തൊരു അശക്തി തന്നെ. അങ്ങനെ ഞാൻ ചോദിച്ചു: ഉപ്പാ, അങ്ങ് ജുമുഅഃ ബാങ്ക് കേൾക്കുമ്പോഴൊക്കെ അബൂഉമാമക്ക് വേണ്ടി പ്രാർത്ഥിക്കുന്നവല്ലോ, അതെന്തുകൊണ്ടാണ്? പിതാവ് പറഞ്ഞു: "എന്റെ പൊന്നുമോനേ, നബി(സ) മക്കയിൽ നിന്ന് വരുന്നതിനു മുമ്പേ ''നഖീഉൽ ഖളമാത്തിൽ'' ബനൂ ബയാദ്വയുടെ ഹർറയിൽ വെച്ച് ഞങ്ങൾക്ക് ജുമുഅക്ക് നേതൃത്വം നൽകിയത് അദ്ദേഹമായിരുന്നു. ഞാൻ ചോദിച്ചു: അന്ന് നിങ്ങൾ എത്രപേരുണ്ടായിരുന്നു? പിതാവ് പറഞ്ഞു: നാല്പതു പേർ. (ദ,ജ)', 'عَبْدِ الرَّحْمَنِ بْنِ كَعْبِ بْنِ مَالِكٍ', 'അബ്ദുർറഹ്മാനുബ്നു കഅ്ബ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 352, 353, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 21, 'عَنْ أَبِي عَبْسٍ رَضِيَ اللهُ عَنْهُ أَنَّهُ قَالَ: وَهُوَ ذَاهِبٌ إِلَى الْجُمُعَةِ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنِ اغْبَرَّتْ قَدَمَاهُ فِي سَبِيلِ اللَّهِ حَرَّمَهُ اللَّهُ عَلَى النَّارِ ". (خ)', 'അബൂ അബസ്(റ): അദ്ദേഹം ജുമുഅക്ക് പോവുകയായിരുന്നു അപ്പോൾ നബി(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ ആരുടെയെങ്കിലും പാദങ്ങൾ പൊടി പുരണ്ടാൽ അല്ലാഹു അവനെ നരകത്തിന് നിഷിദ്ധമാക്കും." (ബു)', 'أَبِي عَبْسٍ', 'അബൂ അബസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 353, 353, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 22, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا يَقُولُ: نَهَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُقِيمَ الرَّجُلُ أَخَاهُ مِنْ مَقْعَدِهِ وَيَجْلِسَ فِيهِ. قِيلَ: الْجُمُعَةَ؟ قَالَ: الْجُمُعَةَ وَغَيْرَهَا. (خ)', 'ഇബ്നുഉമർ(റ): ഒരാൾ തന്റെ സഹോദരനെ അവന്റെ ഇരിപ്പിടത്തിൽ നിന്നെഴുന്നേൽപ്പിക്കുന്നതും എന്നിട്ടവിടെ ഇരിക്കുന്നതും നബി(സ) നിരോധിച്ചിരിക്കുന്നു. അപ്പോൾ ചോദിക്കപ്പെട്ടു; ജുമുഅ(യുടെ അവസരത്തിൽ എഴുന്നേൽപ്പിക്കുന്നതിനെ)യാണോ ഉദ്ദേശിക്കുന്നത്?. ഇബ്നു ഉമർ(റ) പറഞ്ഞു: ജുമുഅയിലും അല്ലാത്ത അവസരങ്ങളിലും. (ബു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 353, 353, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 23, 'عَنِ الْحَكَمِ بْنِ مِينَاءَ رَضِيَ اللهُ عَنْهُ: أَنَّ عَبْدَ اللَّهِ بْنَ عُمَرَ وَأَبَا هُرَيْرَةَ حَدَّثَاهُ: أَنَّهُمَا سَمِعَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ عَلَى أَعْوَادِ مِنْبَرِهِ: "لَيَنْتَهِيَنَّ أَقْوَامٌ عَنْ وَدْعِهِمُ الْجُمُعَاتِ أَوْ لَيَخْتِمَنَّ اللَّهُ عَلَى قُلُوبِهِمْ، ثُمَّ لَيَكُونُنَّ مِنَ الْغَافِلِينَ". (م,ن)', 'ഹകമുബ്നു മീനാഅ(റ): അബ്ദുല്ലാഹിബ്നു ഉമറും അബൂഹുറൈറ(റ)യും പറഞ്ഞു: നബി(സ) തന്റെ മിമ്പറിൽ വെച്ച് ഇങ്ങനെ പറയുന്നതായി കേട്ടു: "ജുമുഅഃ ഉപേക്ഷിക്കുന്നത് ജനങ്ങൾ നിർത്തിയേ തീരൂ. അല്ലെങ്കിൽ അല്ലാഹു അവരുടെ ഹൃദയങ്ങൾ സീൽ ചെയ്യും. അങ്ങനെയവർ അശ്രദ്ധവാന്മാരിൽ പെട്ടവരാകും. തീർച്ച." (മു,ന)', 'الْحَكَمِ بْنِ مِينَاءَ', 'ഹകമുബ്നു മീനാഅ(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 353, 353, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 24, 'عَنْ بُرَيْدَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "الْعَهْدُ الَّذِي بَيْنَنَا وَبَيْنَهُمُ الصَّلَاةُ، فَمَنْ تَرَكَهَا فَقَدْ كَفَرَ". (ت,ن,جه)', 'ബുറൈദ(റ): നബി(സ) പറഞ്ഞു: "നമ്മുടെയും അവരുടെയും ഇടയിലുള്ള ഉടമ്പടി നിസ്കാരമാണ്. വല്ലവരും അതിനെ ഉപേക്ഷിച്ചാൽ അവൻ സത്യ നിഷേധിയായി." (തു,ന,ജ)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['ت','ن','جه']::text[], array['തു','ന','ജ']::text[], null, null, 353, 353, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 25, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَيْسَ بَيْنَ الْعَبْدِ وَالشِّرْكِ إِلَّا تَرْكُ الصَّلَاةِ، فَإِذَا تَرَكَهَا فَقَدْ أَشْرَكَ". [ز: في إسناده ضعيف] (جه)', 'അനസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "അടിമയുടെയും ബഹുദൈവാരാധനയുടെയും ഇടയിലുള്ള വ്യത്യാസം നിസ്കാരം ഉപേക്ഷിക്കൽ മാത്രമാണ്. ആരെങ്കിലും അതുപേക്ഷിച്ചാൽ അവൻ അല്ലാഹുവിൽ പങ്കുചേർത്തവനായി." ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു. (ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', null, 353, 354, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 26, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "بَيْنَ الْعَبْدِ وَبَيْنَ الْكُفْرِ تَرْكُ الصَّلَاةِ". (د,ت,جه)', 'ജാബിർ(റ): നബി(സ) പറഞ്ഞു: "വിശ്വാസിയായ ഒരു അടിമയുടെയും കുഫ്റിന്റെയും ഇടയിലുള്ള വ്യത്യാസം നിസ്കാരം ഉപേക്ഷിക്കലാണ്." (ദ,തു,ജ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിർ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 354, 354, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 27, 'عَنْ سَمُرَةَ ابْنِ جُنْدُبٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ تَرَكَ الْجُمُعَةَ مِنْ غَيْرِ عُذْرٍ فَلْيَتَصَدَّقْ بِدِينَارٍ، فَإِنْ لَمْ يَجِدْ فَبِنِصْفِ دِينَارٍ". (ن)', 'സമുറ(റ): നബി(സ) പറഞ്ഞു: "കാരണമില്ലാതെ ജുമുഅഃ ഒഴിവാക്കിയവൻ ഒരു സ്വർണ്ണ നാണയം ദാനം ചെയ്യട്ടെ, അതില്ലെങ്കിൽ അര സ്വർണ്ണ നാണയം." (ന)', 'سَمُرَةَ ابْنِ جُنْدُبٍ', 'സമുറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 354, 354, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 28, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُ، عَنْ حَفْصَةَ رَضِيَ اللهُ عَنْهَا – زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ – أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "رَوَاحُ الْجُمُعَةِ وَاجِبٌ عَلَى كُلِّ مُحْتَلِمٍ". (ن)', 'പ്രവാചക പത്നി ഹഫ്സ(റ)യിൽ നിന്നും ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "പ്രായപൂർത്തിയായ എല്ലാ പുരുഷന്മാർക്കും ജുമുഅക്കു പോവൽ നിർബന്ധമാണ്." (ന)', 'ابْنِ عُمَرَ', 'പ്രവാചക പത്നി ഹഫ്സ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 354, 354, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 29, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَلَا هَلْ عَسَى أَحَدُكُمْ أَنْ يَتَّخِذَ الصُّبَّةَ مِنَ الْغَنَمِ عَلَى رَأْسِ مِيلٍ أَوْ مِيلَيْنِ، فَيَتَعَذَّرَ عَلَيْهِ الْكَلَأُ، فَيَرْتَفِعَ. ثُمَّ تَجِيءُ الْجُمُعَةُ فَلَا يَجِيءُ وَلَا يَشْهَدُهَا، وَتَجِيءُ الْجُمُعَةُ فَلَا يَشْهَدُهَا، وَتَجِيءُ الْجُمُعَةُ فَلَا يَشْهَدُهَا، حَتَّى يُطْبَعَ عَلَى قَلْبِهِ". (جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിലൊരാൾ ആട്ടിൻ പറ്റത്തെ ഒന്നോ രണ്ടോ മൈൽ അതിർത്തിയിലാക്കുകയും അവന് പുല്ലുകൾ കിട്ടാതെ വരികയും (പുല്ലുകൾ തേടി) അവൻ വിദൂരതയിലേക്ക് പോവുകയും ചെയ്യുന്നു. അങ്ങനെ അവന് ജുമുഅഃ ദിനം വന്നണയുന്നു. അതിലവൻ പങ്കെടുക്കുന്നില്ല. വീണ്ടും അവന് ജുമുഅഃ വന്നണയുന്നു അതിലുമവൻ പങ്കെടുക്കുന്നില്ല. (മൂന്നാമതും) ജുമുഅഃ അവന് വന്നെത്തുന്നു. അതിലും അവൻ പങ്കെടുക്കുന്നില്ലെങ്കിൽ അവന്റെ ഹൃദയം സീൽ വെക്കപ്പെടുന്നതാണ്." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 354, 354, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 30, 'عَنْ سَمُرَةَ بْنِ جُنْدَبٍ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ تَرَكَ الْجُمُعَةَ مُتَعَمِّدًا فَلْيَتَصَدَّقْ بِدِينَارٍ، فَإِنْ لَمْ يَجِدْ فَبِنِصْفِ دِينَارٍ". (د,ن,جه)', 'സമുറത്ത്ബ്നു ജുൻദുബ്(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും മനഃപൂർവ്വം ഒരു ജുമുഅ ഉപേക്ഷിച്ചാൽ അയാൾ ഒരു ദീനാർ ദാനം നൽകട്ടെ, അതിന്നു കഴിയില്ലെങ്കിൽ അര ദീനാറെങ്കിലും." (ദ,ന,ജ)', 'سَمُرَةَ بْنِ جُنْدَبٍ', 'സമുറത്ത്ബ്നു ജുൻദുബ്(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 354, 354, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 31, 'عَنْ أَبِي الْجَعْدِ الضَّمْرِيِّ رَضِيَ اللهُ عَنْهُمَا، وَكَانَتْ لَهُ صُحْبَةٌ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ تَرَكَ ثَلَاثَ جُمَعٍ تَهَاوُنًا بِهَا طَبَعَ اللَّهُ عَلَى قَلْبِهِ". (د,ت,ن,جه)', 'അബുൽ ജുഅ്ദിള്ളംരി(റ): അദ്ദേഹം തിരുമേനി(സ)യുടെ സഹചാരിയായിരുന്നു. നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും നിസ്സാരമായി കരുതിക്കൊണ്ട് മൂന്ന് ജുമുഅഃ ഉപേക്ഷിച്ചാൽ അല്ലാഹു അവന്റെ ഹൃദയത്തിനുമേൽ സീൽ ചെയ്യുന്നതാണ്." (ദ,തു,ന,ജ)', 'أَبِي الْجَعْدِ الضَّمْرِيِّ', 'അബുൽ ജുഅ്ദിള്ളംരി(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 354, 354, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 32, 'عَنْ جَابِرٍ ابْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ تَرَكَ الْجُمُعَةَ ثَلَاثًا، مِنْ غَيْرِ ضَرُورَةٍ، طَبَعَ اللَّهُ عَلَى قَلْبِهِ". (ن,جه)', 'ജാബിർ(റ): നബി(സ) പറഞ്ഞു: "ഒരാൾ നിർബന്ധിത സാഹചര്യം കൂടാതെ മൂന്നു പ്രാവശ്യം ജുമുഅഃ ഉപേക്ഷിച്ചാൽ അല്ലാഹു അവന്റെ ഹൃദയത്തിന്മേൽ മുദ്ര വെക്കുന്നതാണ്." (ന,ജ)', 'جَابِرٍ ابْنِ عَبْدِ اللَّهِ', 'ജാബിർ(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 354, 355, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 33, 'عَنْ قُدَامَةَ بْنِ وَبَرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ فَاتَهُ الْجُمُعَةُ مِنْ غَيْرِ عُذْرٍ فَلْيَتَصَدَّقْ بِدِرْهَمٍ، أَوْ نِصْفِ دِرْهَمٍ، أَوْ صَاعِ حِنْطَةٍ، أَوْ نِصْفِ صَاعٍ". وَفِي رِوَايَةٍ: "مُدًّا أَوْ نِصْفَ مُدٍّ". (د,ن,جه)', 'ഖുദാമതുബ്നു വബ്റ(റ): നബി(സ) പറഞ്ഞു: "കാരണം കൂടാതെ ഒരാൾക്ക് ഒരു ജുമുഅഃ നഷ്ടപ്പെട്ടാൽ ഒരു ദിർഹം ദാനം ചെയ്യട്ടെ, അല്ലെങ്കിൽ അര ദിർഹം, അല്ലെങ്കിൽ ഒരു സ്വാഅ് (മൂന്ന് ലിറ്റർ, ഇരുനൂറ് മി.ലി) ഗോതമ്പ് ദാനം ചെയ്യട്ടെ. അല്ലെങ്കിൽ അര സ്വാഅ്." മറ്റൊരു റിപ്പോർട്ടിൽ: ഒരു മുദ്ദ് (800 മി.ലി) അല്ലെങ്കിൽ അര മുദ്ദ്. (ദ,ന,ജ)', 'قُدَامَةَ بْنِ وَبَرَةَ', 'ഖുദാമതുബ്നു വബ്റ(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 355, 355, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=18 and h.hadith_no=33), 1, 'وَفِي رِوَايَةٍ: "مُدًّا أَوْ نِصْفَ مُدٍّ". (د,ن,جه)', 'മറ്റൊരു നിവേദനിൽ: ഒരു മുദ്ദ് (800 മി.ലി) അല്ലെങ്കിൽ അര മുദ്ദ്. (ദ,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 34, 'عَنْ طَارِقِ بْنِ شِهَابٍ رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْجُمُعَةُ حَقٌّ وَاجِبٌ عَلَى كُلِّ مُسْلِمٍ فِي جَمَاعَةٍ، إِلَّا أَرْبَعَةً: عَبْدٌ مَمْلُوكٌ، أَوِ امْرَأَةٌ، أَوْ صَبِيٌّ، أَوْ مَرِيضٌ". (د)', 'ത്വാരിഖുബ്നു ശിഹാബ്(റ): നബി(സ) പറഞ്ഞു: "ജുമുഅഃ നിസ്കാരം സംഘടിതമായി നിർവ്വഹിക്കൽ എല്ലാ മുസ്ലിമിനും - നിർബ്ബന്ധ ബാധ്യതയാണ്- കടമയാണ്. നാലു പേർക്കൊഴികെ; ഉടമയാക്കപ്പെട്ട അടിമ, സ്ത്രീ, കുട്ടി, രോഗി." (ദ)', 'طَارِقِ بْنِ شِهَابٍ', 'ത്വാരിഖുബ്നു ശിഹാബ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 355, 355, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 35, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: إِنَّ أَوَّلَ جُمُعَةٍ جُمِّعَتْ فِي الْإِسْلَامِ – بَعْدَ جُمُعَةٍ جُمِّعَتْ فِي مَسْجِدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالْمَدِينَةِ – لَجُمُعَةٌ جُمِّعَتْ بِجُوثَاءَ، قَرْيَةٌ مِنْ قُرَى الْبَحْرَيْنِ. وَقِيلَ: قَرْيَةٌ مِنْ قُرَى عَبْدِ الْقَيْسِ. (خ,د)', 'ഇബ്നുഅബ്ബാസ്(റ): ഇസ്ലാമിൽ ആദ്യമായി ജുമുഅഃ സംഘടിപ്പിക്കപ്പെട്ടത് -നബി(സ)യുടെ മദീന പള്ളിയിലെ ജുമുഅക്കുശേഷം- ബഹ്റൈനിലെ ''ജൗസാഅ്'' എന്ന ഗ്രാമത്തിലായിരുന്നു. അത് അബ്ദുൽ ഖൈസിൽപെട്ട ഗ്രാമമാണെന്നും അഭിപ്രായമുണ്ട്. (ബു,ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 355, 355, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 36, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ النَّاسُ يَنْتَابُونَ يَوْمَ الْجُمُعَةِ مِنْ مَنَازِلِهِمْ، وَمِنَ الْعَوَالِي. (د)', 'ആഇശ(റ): ജനങ്ങൾ (ആദ്യ കാലങ്ങളിൽ) അവരുടെ വീടുകളിൽ നിന്നും ഉയർന്ന പ്രദേശങ്ങളിൽ നിന്നും ഊഴമിട്ടായിരുന്നു ജുമുഅക്ക് വരാറുണ്ടായിരുന്നത്. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 355, 355, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 37, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا: عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْجُمُعَةُ عَلَى كُلِّ مَنْ سَمِعَ النِّدَاءَ". (د)', 'അബ്ദില്ലാഹിബ്നു അംറ്(റ): നബി(സ) പറഞ്ഞു: "ബാങ്ക് കേൾക്കുന്നവർക്കെല്ലാം ജുമുഅഃ നിർബന്ധമാണ്." (ദ)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദില്ലാഹിബ്നു അംറ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 355, 355, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 38, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: إِنَّ أَهْلَ قُبَاءَ كَانُوا يُجَمِّعُونَ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ الْجُمُعَةِ. [ز: في إسناده ضعيف] (جه)', 'ഇബ്നുഉമർ(റ): ''ഖുബാഅ്'' പ്രദേശത്തുള്ള ആളുകൾ വെള്ളിയാഴ്ച ദിവസം നബി(സ)യോടൊപ്പം ജുമുഅഃ നിസ്കരിക്കാറുണ്ടായിരുന്നു. [ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു] (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', null, 356, 356, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 39, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: صَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي حُجْرَتِهِ، وَالنَّاسُ يَأْتَمُّونَ بِهِ مِنْ وَرَاءِ الْحُجْرَةِ. (خ,د)', 'ആഇശ(റ): റസൂൽ(സ) തന്റെ മുറിയിൽ വെച്ച് നിസ്കരിച്ചിരുന്നു. ജനങ്ങൾ മുറിയുടെ പിന്നിൽ നിന്ന് നബി(സ)യെ പിൻതുടരുകയും ചെയ്തിരുന്നു. (ബു,ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 356, 356, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 40, 'عَنْ ثُوَيْرٍ رَضِيَ اللهُ عَنْهُ عَنْ رَجُلٍ مِنْ أَهْلِ قُبَاءَ، عَنْ أَبِيهِ – وَكَانَ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ – قَالَ: أَمَرَنَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ نَشْهَدَ الْجُمُعَةَ مِنْ قُبَاءَ. (ت)', 'സുവൈർ(റ), ''ഖുബാഅ്'' പ്രദേത്തുകാരിൽപെട്ട ഒരാളിൽ നിന്ന്: അദ്ദേഹം തന്റെ പിതാവിൽ നിന്ന്: (അദ്ദേഹം നബി(സ)യുടെ സഹാബിമാരിൽ പെട്ട ആളായിരുന്നു.) അദ്ദേഹം പറഞ്ഞു: ഖുബാഇൽ നിന്നും ജുമുഅക്ക് ഹാജരാകുവാൻ നബി(സ) ഞങ്ങളോട് കൽപിച്ചു. (തു)', 'ثُوَيْرٍ', 'സുവൈർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 356, 356, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 41, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: "الْجُمُعَةُ عَلَى مَنْ آوَاهُ اللَّيْلُ إِلَى أَهْلِهِ". (ت)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "രാത്രി തന്റെ കുടുംബത്തിലേക്ക് മടങ്ങിച്ചെല്ലുന്നവർക്കാണ് ജുമുഅഃ നിർബ്ബന്ധമുള്ളത്." (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 356, 356, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 42, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقْرَأُ فِي صَلَاةِ الْفَجْرِ يَوْمَ الْجُمُعَةِ: {تَنْزِيلُ} السَّجْدَةَ، وَ{هَلْ أَتَى عَلَى الْإِنْسَانِ} فِي صَلَاةِ الْجُمُعَةِ بِسُورَةِ الْجُمُعَةِ وَ{إِذَا جَاءَكَ الْمُنَافِقُونَ}. (م,ت,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): വെള്ളിയാഴ്ച ദിവസം സുബ്ഹ് നിസ്കാരത്തിൽ റസൂൽ(സ) (തൻസീലു.......) സൂറ:സജദയും, ''ഹൽ അതാ അലൽ ഇൻസാനി.....''യും (സൂറത്തുൽ ഇൻസാനും) ഓതാറുണ്ടായിരുന്നു. ജുമുഅഃ നിസ്കാരത്തിൽ സൂറ:ജുമുഅയും ''ഇദാജാഅകൽ മുനാഫിഖൂന......''യും (സൂറത്തു മുനാഫിഖൂനും) പാരായണം ചെയ്തു. (മു,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م','ت','ن','جه']::text[], array['മു','തു','ന','ജ']::text[], null, null, 356, 356, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 43, 'عَنْ أُسَامَةَ بْنِ عُمَيْرٍ: أَنَّ يَوْمَ حُنَيْنٍ كَانَ يَوْمَ مَطَرٍ، فَأَمَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُنَادِيَهُ: "أَنَّ الصَّلَاةَ فِي الرِّحَالِ". وَفِي رِوَايَةٍ: أَنَّهُ شَهِدَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ زَمَنَ الْحُدَيْبِيَةِ فِي يَوْمِ جُمُعَةٍ وَأَصَابَهُمْ مَطَرٌ لَمْ تَبْتَلَّ أَسْفَلُ نِعَالِهِمْ فَأَمَرَهُمْ أَنْ يُصَلُّوا فِي رِحَالِهِمْ. (د,ن,جه)', 'ഉസാമതുബ്നു അമീർ(റ): ഹുനൈൻ യുദ്ധം നടന്നത് മഴയുള്ള ദിവസത്തിലായിരുന്നു. അപ്പോൾ നബി(സ) ബാങ്ക് വിളിക്കുന്നവനോട് "നിശ്ചയം, നിസ്കാരം തമ്പുകളിലാണ്" എന്നു വിളിച്ചു പറയാൻ കൽപിച്ചു.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=18 and h.hadith_no=43), 1, 'وَفِي رِوَايَةٍ: أَنَّهُ شَهِدَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ زَمَنَ الْحُدَيْبِيَةِ فِي يَوْمِ جُمُعَةٍ وَأَصَابَهُمْ مَطَرٌ لَمْ تَبْتَلَّ أَسْفَلُ نِعَالِهِمْ فَأَمَرَهُمْ أَنْ يُصَلُّوا فِي رِحَالِهِمْ. (د,ن,جه)', 'മറ്റൊരു നിവേദനിൽ: ഹുദൈബിയാ സന്ധിയിലേർപ്പെട്ട കാലഘട്ടത്തിലെ ഒരു വെള്ളിയാഴ്ച ദിവസം അവരുടെ ചെരുപ്പടികളെപ്പോലും നനക്കാത്ത മഴ അവർക്ക് ബാധിക്കുകയും നബി(സ) അവരോട് അവരുടെ തമ്പുകളിൽ നിസ്കരിക്കുവാൻ കൽപിക്കുകയും ചെയ്തതിന് അദ്ദേഹം സാക്ഷിയായി.¹ (ദ,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 44, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: بَعَثَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَبْدَ اللَّهِ بْنَ رَوَاحَةَ فِي سَرِيَّةٍ، فَوَافَقَ ذَلِكَ يَوْمَ الْجُمُعَةِ، فَغَدَا أَصْحَابُهُ، فَقَالَ: أَتَخَلَّفُ فَأُصَلِّي مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثُمَّ أُلْحِقُهُمْ. فَلَمَّا صَلَّى مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَآهُ، فَقَالَ: "مَا مَنَعَكَ أَنْ تَغْدُوَ مَعَ أَصْحَابِكَ". فَقَالَ: أَرَدْتُ أَنْ أُصَلِّيَ مَعَكَ ثُمَّ أُلْحِقَهُمْ. قَالَ: "لَوْ أَنْفَقْتَ مَا فِي الْأَرْضِ جَمِيعًا مَا أَدْرَكْتَ فَضْلَ غَدْوَتِهِمْ". (ت)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) അബ്ദുല്ലാഹിബ്നു റവാഹ(റ)വിനെ യുദ്ധ സംഘത്തിലയച്ചു. അതു വെള്ളിയാഴ്ച ദിവസമായിരുന്നു. തന്റെ കൂട്ടുകാർ മുന്നിൽ പോവുകയും അദ്ദേഹം ഇങ്ങനെ പറയുകയും ചെയ്തു: ഞാൻ നബി(സ)യോടൊപ്പം ജുമുഅഃ നിസ്കരിക്കുകയും എന്നിട്ട് നിങ്ങളോടൊപ്പം വന്നു ചേരുകയും ചെയ്യാം. ജുമുഅഃ നിസ്കരിച്ച ശേഷം നബി(സ) അദ്ദേഹത്തെ കണ്ടപ്പോൾ ചോദിച്ചു: "നിങ്ങൾക്ക് കൂട്ടുകാരോടൊന്നിച്ച് രാവിലെ പോകാൻ തടസ്സമെന്തായിരുന്നു?" അബ്ദുല്ലാഹിബ്നു റവാഹ പറഞ്ഞു: ഞാൻ അങ്ങയോടൊപ്പം ജുമുഅഃ നിസ്കരിക്കുകയും പിന്നെ അവരോടൊപ്പം ചെന്നു ചേരുകയും ചെയ്യാമെന്നുദ്ദേശിച്ചു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ഭൂമിയിലുള്ളത് മുഴുവൻ ചിലവഴിച്ചാലും രാവിലെ അവരോടൊപ്പം പോയാൽ കിട്ടുന്ന പ്രതിഫലം നിനക്ക് കിട്ടുകയില്ല." (തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 357, 357, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 45, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: نَزَلَ بِضَجْنَانَ فِي لَيْلَةٍ بَارِدَةٍ، فَأَمَرَ الْمُنَادِيَ فَنَادَى: أَنِ الصَّلَاةُ فِي الرِّحَالِ. وَحَدَّثَ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا كَانَتْ لَيْلَةٌ بَارِدَةٌ أَوْ مَطِيرَةٌ أَمَرَ الْمُنَادِيَ فَنَادَى: الصَّلَاةُ فِي الرِّحَالِ. وَفِي رِوَايَةٍ: نَادَى ابْنُ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا بِالصَّلَاةِ بِضَجْنَانَ، ثُمَّ نَادَى: أَنْ صَلُّوا فِي رِحَالِكُمْ، قَالَ فِيهِ: ثُمَّ حَدَّثَ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ كَانَ يَأْمُرُ الْمُنَادِيَ فَيُنَادِي بِالصَّلَاةِ، ثُمَّ يُنَادِي: "أَنْ صَلُّوا فِي رِحَالِكُمْ" فِي اللَّيْلَةِ الْبَارِدَةِ وَفِي اللَّيْلَةِ الْمُطِيرَةِ، فِي السَّفَرِ. (د)', 'ഇബ്നു ഉമർ(റ): അദ്ദേഹം ഒരു തണുപ്പുള്ള രാത്രിയിൽ ''ദജ്നാൻ'' എന്ന പ്രദേശത്ത് ഇറങ്ങി. ''നിശ്ചയം, നിസ്കാരം തമ്പുകളിലാണ്'' എന്ന് വിളിച്ചു പറയാൻ ഒരാളോട് കൽപിച്ചു. ഇബ്നുഉമർ(റ) പറയുന്നു: തണുപ്പുള്ളതോ മഴയുള്ളതോ ആയ രാത്രിയിൽ നബി(സ) വിളിച്ച് പറയാൻ കൽപിക്കും. അപ്പോൾ ഒരാൾ ഇപ്രകാരം വിളിച്ചു പറയും: നിസ്കാരം തമ്പുകളിലാണ്. മറ്റൊരു റിപ്പോർട്ടിൽ: ഇബ്നുഉമർ(റ) ദജ്നാനിൽ വെച്ച് നിസ്കാരത്തെ കുറിച്ച് വിളിച്ച് പറഞ്ഞു: നിങ്ങൾ നിങ്ങളുടെ തമ്പുകളിൽ നിസ്കരിക്കുക. പിന്നെ അദ്ദേഹം പറഞ്ഞു: നബി(സ) വിളിച്ച് പറയുന്നവനോട് വിളിച്ച് പറയാൻ കൽപിക്കും. അപ്പോൾ അയാൾ നിസ്കാരത്തെക്കുറിച്ച് വിളിച്ച് പറയും: "നിങ്ങൾ നിങ്ങളുടെ തമ്പുകളിൽ നിസ്കരിക്കുവിൻ." യാത്രയിൽ തണുപ്പുള്ള രാത്രിയായാലും മഴയുള്ള രാത്രിയായാലും ശരി. (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നു ഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 357, 358, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=18 and h.hadith_no=45), 1, 'وَفِي رِوَايَةٍ: نَادَى ابْنُ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا بِالصَّلَاةِ بِضَجْنَانَ، ثُمَّ نَادَى: أَنْ صَلُّوا فِي رِحَالِكُمْ، قَالَ فِيهِ: ثُمَّ حَدَّثَ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ كَانَ يَأْمُرُ الْمُنَادِيَ فَيُنَادِي بِالصَّلَاةِ، ثُمَّ يُنَادِي: "أَنْ صَلُّوا فِي رِحَالِكُمْ" فِي اللَّيْلَةِ الْبَارِدَةِ وَفِي اللَّيْلَةِ الْمُطِيرَةِ، فِي السَّفَرِ. (د)', 'മറ്റൊരു നിവേദനിൽ: ഇബ്നുഉമർ(റ) ദജ്നാനിൽ വെച്ച് നിസ്കാരത്തെ കുറിച്ച് വിളിച്ച് പറഞ്ഞു: നിങ്ങൾ നിങ്ങളുടെ തമ്പുകളിൽ നിസ്കരിക്കുക. പിന്നെ അദ്ദേഹം പറഞ്ഞു: നബി(സ) വിളിച്ച് പറയുന്നവനോട് വിളിച്ച് പറയാൻ കൽപിക്കും. അപ്പോൾ അയാൾ നിസ്കാരത്തെക്കുറിച്ച് വിളിച്ച് പറയും: "നിങ്ങൾ നിങ്ങളുടെ തമ്പുകളിൽ നിസ്കരിക്കുവിൻ." യാത്രയിൽ തണുപ്പുള്ള രാത്രിയായാലും മഴയുള്ള രാത്രിയായാലും ശരി. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 46, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كُنَّا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي سَفَرٍ فَمُطِرْنَا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لِيُصَلِّ مَنْ شَاءَ مِنْكُمْ فِي رَحْلِهِ". (م,د,ت)', 'ജാബിർ(റ): ഒരിക്കൽ മഴയുള്ളപ്പോൾ ഞങ്ങൾ നബി(സ)യോടൊപ്പം യാത്രയിലായിരുന്നു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങളിൽ ഉദ്ദേശിക്കുന്നവൻ തന്റെ തമ്പിൽ നിസ്കരിക്കുക." (മു,ദ,തു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 358, 358, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 47, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّهُ قَالَ لِمُؤَذِّنِهِ فِي يَوْمٍ مَطِيرٍ: إِذَا قُلْتُ: أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، فَلَا تَقُلْ: حَيَّ عَلَى الصَّلَاةِ. قُلْ: صَلُّوا فِي بُيُوتِكُمْ. فَكَأَنَّ النَّاسَ اسْتَنْكَرُوا ذَلِكَ، فَقَالَ قَدْ فَعَلَ ذَا مَنْ هُوَ خَيْرٌ مِنِّي، إِنَّ الْجُمُعَةَ عَزْمَةٌ، وَإِنِّي كَرِهْتُ أَنْ أُخْرِجَكُمْ، فَتَمْشُونَ فِي الطِّينِ وَالْمَطَرِ. (ق,د,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): മഴയുള്ള ദിവസം അദ്ദേഹം തന്റെ ബാങ്ക് വിളിക്കാരനോട് പറഞ്ഞു: നീ ''അശ്ഹദു അന്ന മുഹമ്മദൻ റസൂലുല്ല'' എന്ന് പറഞ്ഞാൽ ഹയ്യ അലസ്സ്വലാത്ത് എന്ന് പറയുന്നതിന് പകരം ''നിങ്ങളുടെ വീട്ടിൽ വെച്ച് നിസ്കരിക്കുക'' എന്ന് പറയണം. ജനങ്ങൾ ഇത് വെറുത്തതു പോലെ തോന്നി. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: എന്നേക്കാൾ ഉത്തമനായ ഒരാൾ ഇതുപോലെ ചെയ്തിട്ടുണ്ട് ജുമുഅഃ ഒരു തീരുമാനമാണ്, ചെളിയിലും മഴയിലും നടത്തി നിങ്ങളെ വിഷമിപ്പിക്കാൻ ഞാനിഷ്ടപ്പെടുന്നില്ല. (ബു,മു,ദ,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','د','جه']::text[], array['ബു','മു','ദ','ജ']::text[], null, null, 358, 358, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 48, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: أَصَابَتِ النَّاسَ سَنَةٌ عَلَى عَهْدِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَبَيْنَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ فِي يَوْمِ جُمُعَةٍ، قَامَ أَعْرَابِيٌّ فَقَالَ: يَا رَسُولَ اللَّهِ، هَلَكَ الْمَالُ وَجَاعَ الْعِيَالُ، فَادْعُ اللَّهَ لَنَا. فَرَفَعَ يَدَيْهِ، وَمَا نَرَى فِي السَّمَاءِ قَزَعَةً، فَوَالَّذِي نَفْسِي بِيَدِهِ، مَا وَضَعَهَا حَتَّى ثَارَ السَّحَابُ أَمْثَالَ الْجِبَالِ، ثُمَّ لَمْ يَنْزِلْ عَنْ مِنْبَرِهِ حَتَّى رَأَيْتُ الْمَطَرَ يَتَحَادَرُ عَلَى لِحْيَتِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَمُطِرْنَا يَوْمَنَا ذَلِكَ، وَمِنَ الْغَدِ وَبَعْدَ الْغَدِ، وَالَّذِي يَلِيهِ، حَتَّى الْجُمُعَةِ الْأُخْرَى. وَقَامَ ذَلِكَ الْأَعْرَابِيُّ، أَوْ قَالَ غَيْرُهُ، فَقَالَ: يَا رَسُولَ اللَّهِ، تَهَدَّمَ الْبِنَاءُ وَغَرِقَ الْمَالُ، فَادْعُ اللَّهَ لَنَا. فَرَفَعَ يَدَيْهِ، فَقَالَ: "اللَّهُمَّ حَوَالَيْنَا وَلَا عَلَيْنَا". فَمَا يُشِيرُ بِيَدِهِ إِلَى نَاحِيَةٍ مِنَ السَّحَابِ إِلَّا انْفَرَجَتْ، وَصَارَتِ الْمَدِينَةُ مِثْلَ الْجَوْبَةِ، وَسَالَ الْوَادِي قَنَاةُ شَهْرًا، وَلَمْ يَجِئْ أَحَدٌ مِنْ نَاحِيَةٍ إِلَّا حَدَّثَ بِالْجَوْدِ. (خ)', 'അനസുബ്നുമാലിക്(റ): നബി(സ)യുടെ കാലത്ത് ജനങ്ങൾക്ക് ഒരു ക്ഷാമം ബാധിച്ചു. അങ്ങനെ ഒരുദിവസം നബി(സ) വെള്ളിയാഴ്ച ഖുത്വുബ നിർവ്വഹിക്കവെ ഒരു ഗ്രാമവാസി എഴുന്നേറ്റുനിന്ന് പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, ധനം നശിച്ചു, കുടുംബം പട്ടിണിയിലായി. അല്ലാഹുവിനോട് ഞങ്ങൾക്ക് വേണ്ടി പ്രാർത്ഥിച്ചാലും, തിരുനബി(സ) തന്റെ കൈകൾ ഉയർത്തി. അപ്പോൾ മേഘത്തിന്റെ തുണ്ട് പോലും ഞങ്ങൾക്ക് കാണാൻ സാധിച്ചിരുന്നില്ല. എന്റെ ആത്മാവ് ആരുടെ കയ്യിലാണോ അവൻ സത്യം, അവിടുന്ന് തന്റെ കൈ താഴ്ത്തും മുമ്പെ പർവ്വതങ്ങൾ കണക്കെ മേഘങ്ങൾ പ്രത്യക്ഷപ്പെട്ടു. തുടർന്ന് അവിടുന്ന് മിമ്പറിൽ നിന്ന് ഇറങ്ങുമ്പോഴേക്കും മഴത്തുള്ളികൾ അദ്ദേഹത്തിന്റെ താടിയിലൂടെ ഒലിച്ചു വീഴുന്നത് ഞാൻ കണ്ടു. അങ്ങനെ അന്നും പിറ്റേന്നും, അതിന്റെ പിറ്റേന്നും അതിന്റെടുത്ത ദിവസവും, അടുത്ത ജുമുഅഃ വരെയും ഞങ്ങൾക്ക് മഴ ലഭിച്ചു കൊണ്ടേയിരുന്നു. അന്നും അതേ ഗ്രാമവാസി (അതേ ഗ്രാമത്തിൽ താമസിക്കുന്ന മറ്റൊരാൾ) തന്നെ എഴുന്നേറ്റുനിന്ന് പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, കെട്ടിടങ്ങൾ വീണു, ധനം വെള്ളത്തിലാണ്ടു. അതുകൊണ്ട് അവിടുന്ന് ഞങ്ങൾക്കു വേണ്ടി അല്ലാഹുവിനോട് പ്രാർത്ഥിച്ചാലും, ഉടനെ തിരുനബി(സ) തന്റെ കൈകൾ ഉയർത്തി ഇങ്ങനെ പ്രാർത്ഥിച്ചു: "അല്ലാഹുവേ ഞങ്ങളുടെ ചുറ്റും മഴ വർഷിപ്പിക്കേണമേ, ഞങ്ങൾക്കു മീതെയല്ല." അങ്ങിനെ തിരുമേനി ചൂണ്ടിക്കാണിക്കുന്ന ഭാഗത്തെ മേഘങ്ങളെല്ലാം നീങ്ങാൻ തുടങ്ങി. മദീന ഒരു തടാകം പോലെയായി. മലഞ്ചെരുവുകളിലെ അരുവികൾ ഒരു മാസം വരെ ഒഴുകി. എല്ലാ ഭാഗങ്ങളിൽ നിന്ന് വന്നവരും മഴയുടെ സമൃദ്ധിയെ കുറിച്ച് സംസാരിക്കാൻ തുടങ്ങി. (ബു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നുമാലിക്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 358, 359, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 49, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: بَيْنَمَا عُمَرُ بْنُ الْخَطَّابِ يَخْطُبُ النَّاسَ يَوْمَ الْجُمُعَةِ، إِذْ دَخَلَ عُثْمَانُ ابْنُ عَفَّانَ فَعَرَّضَ بِهِ عُمَرُ فَقَالَ: مَا بَالُ رِجَالٍ يَتَأَخَّرُونَ بَعْدَ النِّدَاءِ؟ فَقَالَ عُثْمَانُ: يَا أَمِيرَ الْمُؤْمِنِينَ، مَا زِدْتُ حِينَ سَمِعْتُ النِّدَاءَ أَنْ تَوَضَّأْتُ ثُمَّ أَقْبَلْتُ. فَقَالَ عُمَرُ: وَالْوُضُوءَ أَيْضًا؟ أَلَمْ تَسْمَعُوا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِذَا جَاءَ أَحَدُكُمْ إِلَى الْجُمُعَةِ فَلْيَغْتَسِلْ". (م)', 'അബൂഹുറൈറ(റ): ഉമറുബ്നുൽ ഖത്താബ്(റ) ഒരു ജുമുഅഃ ദിനം ജനങ്ങളെ അഭിസംബോധന ചെയ്തു പ്രസംഗിച്ചു കൊണ്ടിരിക്കെ ഉസ്മാൻ(റ) കടന്നുവന്നു. അദ്ദേഹത്തെ സൂചിപ്പിച്ചുകൊണ്ട് ഉമർ(റ) ചോദിച്ചു: ബാങ്കിനു ശേഷം വൈകി വരുന്നവരുടെ അവസ്ഥ എന്താണ്? അപ്പോൾ ഉസ്മാൻ(റ) പറഞ്ഞു: "അമീറുൽ മുഅ്മിനീൻ! ബാങ്ക് കേട്ട ശേഷം ഞാൻ വുദു എടുക്കുകയേ ചെയ്തുള്ളൂ. പിന്നെ ഇങ്ങോട്ടു പോന്നു. അപ്പോൾ ഉമർ(റ) ചോദിച്ചു: അപ്പോൾ വുദു മാത്രമാണോ നിർവ്വഹിച്ചത്. നബി(സ) അരുളിയത് താങ്കൾ കേട്ടിട്ടില്ലേ: "നിങ്ങളാരെങ്കിലും ജുമുഅക്കു വരുമ്പോൾ അയാൾ കുളിച്ചു കൊള്ളട്ടെ." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 359, 359, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 50, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ أَتَى الْجُمُعَةَ فَلْيَغْتَسِلْ". حسن صحيح. (ق,د,ت,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ആരെങ്കിലും ജുമുഅയിൽ പങ്കെടുക്കുന്നുവെങ്കിൽ അവൻ കുളിക്കട്ടെ." [ഹദീസ് ഹസനും സഹീഹുമാണെന്ന് തുർമുദി] (ബു,മു,ദ,തു,ന,ജ)', 'ابْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 359, 359, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 51, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ تَوَضَّأَ يَوْمَ الْجُمُعَةِ فَبِهَا وَنِعْمَتْ، تُجْزِئُ عَنْهُ الْفَرِيضَةُ، وَمَنِ اغْتَسَلَ فَالْغُسْلُ أَفْضَلُ". [إسناده ضعيف] (جه)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും വുദു ചെയ്ത് ജുമുഅക്ക് പോയാൽ അത് വളരെ നന്നായി. അത്കൊണ്ട് നിർബന്ധബാധ്യത തീരും. ആരെങ്കിലും കുളിക്കുകയാണെങ്കിൽ അങ്ങനനെ ചെയ്യുന്നതാണ് ഏറ്റവും ശ്രേഷ്ടം." ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു. (ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'إسناده ضعيف', null, 359, 359, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 52, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: بَيْنَمَا عُمَرُ بْنُ الْخَطَّابِ يَخْطُبُ يَوْمَ الْجُمُعَةِ إِذْ دَخَلَ رَجُلٌ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: أَيَّةُ سَاعَةٍ هَذِهِ؟ فَقَالَ: مَا هُوَ إِلَّا أَنْ سَمِعْتُ النِّدَاءَ، وَمَا زِدْتُ عَلَى أَنْ تَوَضَّأْتُ. قَالَ: وَالْوُضُوءَ أَيْضًا، وَقَدْ عَلِمْتَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَرَ بِالْغُسْلِ؟ (خ,ت)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): ഉമറുബ്നുൽ ഖത്താബ്(റ) ജുമുഅഃ ഖുത്വുബ നിർവ്വഹിച്ചു കൊണ്ടിരിക്കെ നബി(സ)യുടെ അനുചരരിൽപ്പെട്ട ഒരാൾ വന്നു. അപ്പോൾ ഉമർ(റ) ചോദിച്ചു: സമയം എത്രയായിരിക്കുന്നു? ആഗതൻ പറഞ്ഞു: ഞാൻ ബാങ്കു കേട്ട് വുദു ചെയ്യുന്ന സമയമല്ലാതെ വൈകിയിട്ടില്ല. ഉമർ(റ) പറഞ്ഞു: നബി(സ) കുളിക്കുവാൻ കൽപ്പിച്ചിരിക്കുന്നുവെന്ന് അറിഞ്ഞിരിക്കെ വുദു മാത്രം നിർവ്വഹിക്കുകയോ? (ബു,തു)', 'ابْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['خ','ت']::text[], array['ബു','തു']::text[], null, null, 359, 359, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 53, 'عَنْ سَلْمَانَ الْفَارِسِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا يَغْتَسِلُ رَجُلٌ يَوْمَ الْجُمُعَةِ، وَيَتَطَهَّرُ مَا اسْتَطَاعَ مِنْ طُهْرٍ، وَيَدَّهِنُ مِنْ دُهْنِهِ، أَوْ يَمَسُّ مِنْ طِيبِ بَيْتِهِ، ثُمَّ يَخْرُجُ فَلَا يُفَرِّقُ بَيْنَ اثْنَيْنِ، ثُمَّ يُصَلِّي مَا كُتِبَ لَهُ، ثُمَّ يُنْصِتُ إِذَا تَكَلَّمَ الْإِمَامُ، إِلَّا غُفِرَ لَهُ مَا بَيْنَهُ وَبَيْنَ الْجُمُعَةِ الْأُخْرَى". (خ)', 'സൽമാനുൽ ഫാരിസി(റ): തിരുമേനി(സ) അരുളി: "ഒരാൾ വെള്ളിയാഴ്ച ദിവസം കുളിക്കുകയും കഴിയുന്നത്ര ശുദ്ധി വരുത്തുകയും തന്റെ പക്കലുള്ള എണ്ണയിൽ നിന്ന് അൽപമെടുത്ത് മുടിയിൽ തേച്ച് അല്ലെങ്കിൽ തന്റെ വീട്ടിലുള്ള സുഗന്ധം അൽപമെടുത്ത് ശരീരത്തിൽ പൂശി ജുമുഅക്കായി പുറപ്പെട്ടു. പള്ളിയിൽ ചേർന്നിരിക്കുന്ന രണ്ടാളുകളെ അകറ്റിയിരുത്തി അവർക്കിടയിൽ കയറിയിരിക്കാതെ അവനോട് കൽപിച്ചത് നിസ്കരിക്കുകയും പിന്നെ ഇമാം സംസാരിക്കുമ്പോൾ അവൻ മൗനം പാലിക്കുകയും ചെയ്താൽ ആ ജുമുഅഃ മുതൽ അടുത്ത ജുമുഅഃ വരെയുള്ള കുറ്റങ്ങൾ അല്ലാഹു അവന് പൊറുത്തുകൊടുക്കാതിരിക്കില്ല." (ബു)', 'سَلْمَانَ الْفَارِسِيِّ', 'സൽമാനുൽ ഫാരിസി(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 360, 360, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 54, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُ:أَنَّهُ قِيلَ:ذَكَرُوا أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "اغْتَسِلُوا يَوْمَ الْجُمُعَةِ وَاغْسِلُوا رُءُوسَكُمْ وَإِنْ لَمْ تَكُونُوا جُنُبًا، وَأَصِيبُوا مِنَ الطِّيبِ". قَالَ ابْنُ عَبَّاسٍ: أَمَّا الْغُسْلُ فَنَعَمْ، وَأَمَّا الطِّيبُ فَلَا أَدْرِي. (خ)', 'ഇബ്നുഅബ്ബാസ്(റ): അദ്ദേഹത്തോട് ചോദിക്കപ്പെട്ടു: "നിങ്ങൾ വെള്ളിയാഴ്ച കുളിക്കുകയും നിങ്ങളുടെ തല കഴുകുകയും ചെയ്തു കൊള്ളുക. നിങ്ങൾക്ക് ജനാബത്തില്ലെങ്കിലും. നിങ്ങൾ സുഗന്ധദ്രവ്യം ഉപയോഗിക്കുകയും ചെയ്യുക." എന്ന് റസൂൽ(സ) അരുളിയതായി ജനങ്ങൾ പറയുന്നുണ്ടല്ലോ? അദ്ദേഹം പറഞ്ഞു: കുളിയുടെ കാര്യം ശരിതന്നെ. സുഗന്ധദ്രവ്യത്തിന്റേത് എനിക്കറിയില്ല. (ബു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 360, 360, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 55, 'عَنِ الْقَاسِمِ بْنِ مُحَمَّدِ بْنِ أَبِي بَكْرٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّهُمْ ذَكَرُوا غُسْلَ يَوْمِ الْجُمُعَةِ عِنْدَ عَائِشَةَ فَقَالَتْ: إِنَّمَا كَانَ النَّاسُ يَسْكُنُونَ الْعَالِيَةَ، فَيَحْضُرُونَ الْجُمُعَةَ وَبِهِمْ وَسَخٌ، فَإِذَا أَصَابَهُمُ الرَّوْحُ سَطَعَتْ أَرْوَاحُهُمْ، فَيَتَأَذَّى بِهَا النَّاسُ، فَذُكِرَ ذَلِكَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "أَوْ لَا يَغْتَسِلُونَ". (ن)', 'ഖാസിമുബ്നു മുഹമ്മദ്ബ്നു അബൂബക്കർ(റ): ജുമുഅഃ ദിവസത്തിലെ കുളിയെക്കുറിച്ച് അവർ (ജനങ്ങൾ) ആഇശ(റ)യോട് ചർച്ച ചെയ്തു. അവർ പറഞ്ഞു: നിശ്ചയം, ജനങ്ങൾ മദീനയുടെ പുറം ഭാഗങ്ങളിൽ താമസിക്കുന്നവരായിരുന്നു. അവർ ജുമുഅക്ക് അഴുക്കു പുരണ്ടവരായിക്കൊണ്ട് വരാറുണ്ടായിരുന്നു. അവർക്ക് മന്ദമാരുതൻ ഏശിയാൽ ചെളിയുടെ ഗന്ധം ബഹിർഗമിക്കും. അത് ജനങ്ങൾക്ക് ഉപദ്രവകരമാവുയും ചെയ്തു. ഇതേക്കുറിച്ച് പറയപ്പെട്ടപ്പോൾ നബി(സ) പറഞ്ഞു: "അവർക്ക് കുളിക്കാമായിരുന്നില്ലേ?" (ന)', 'الْقَاسِمِ بْنِ مُحَمَّدِ بْنِ أَبِي بَكْرٍ', 'ഖാസിമുബ്നു മുഹമ്മദ്ബ്നു അബൂബക്കർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 360, 360, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 56, 'عَنْ سَمُرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ تَوَضَّأَ يَوْمَ الْجُمُعَةِ فَبِهَا وَنِعْمَتْ، وَمَنِ اغْتَسَلَ فَالْغُسْلُ أَفْضَلُ". (ت,ن)', 'സമുറ(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും വെള്ളിയാഴ്ച ദിവസം വുദു ചെയ്താൽ നല്ലത്. (എന്നാൽ) കുളിക്കുന്നതാണ് ഏറ്റവും ശ്രേഷ്ഠം." (തു,ന)', 'سَمُرَةَ', 'സമുറ(റ)', null, null, array['ت','ن']::text[], array['തു','ന']::text[], null, null, 360, 360, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 57, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "غُسْلُ يَوْمِ الْجُمُعَةِ وَاجِبٌ عَلَى كُلِّ مُحْتَلِمٍ". (م,ن)', 'അബൂസഈദ്(റ): നബി(സ) പറഞ്ഞു: "പ്രായപൂർത്തിയായ എല്ലാവർക്കും വെള്ളിയാഴ്ച കുളിക്കൽ അനിവാര്യമാണ്." (മു,ന)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദ്(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 360, 360, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 58, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "عَلَى كُلِّ رَجُلٍ مُسْلِمٍ فِي كُلِّ سَبْعَةِ أَيَّامٍ غُسْلُ يَوْمٍ، وَهُوَ يَوْمُ الْجُمُعَةِ". (ن)', 'ജാബിർ(റ): നബി(സ) പറഞ്ഞു: "മുസ്ലിമായ ഏതൊരുവനും എല്ലാ ഏഴു ദിവസങ്ങളിൽ നിന്നും ഒരു ദിവസം കുളിക്കൽ നിർബന്ധമാണ്. അത് വെള്ളിയാഴ്ച ദിവസമാണ്." (ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 360, 361, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 59, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنِ اغْتَسَلَ يَوْمَ الْجُمُعَةِ غُسْلَ الْجَنَابَةِ ثُمَّ رَاحَ، فَكَأَنَّمَا قَرَّبَ بَدَنَةً، وَمَنْ رَاحَ فِي السَّاعَةِ الثَّانِيَةِ، فَكَأَنَّمَا قَرَّبَ بَقَرَةً، وَمَنْ رَاحَ فِي السَّاعَةِ الثَّالِثَةِ، فَكَأَنَّمَا قَرَّبَ كَبْشًا أَقْرَنَ، وَمَنْ رَاحَ فِي السَّاعَةِ الرَّابِعَةِ، فَكَأَنَّمَا قَرَّبَ دَجَاجَةً، وَمَنْ رَاحَ فِي السَّاعَةِ الْخَامِسَةِ، فَكَأَنَّمَا قَرَّبَ بَيْضَةً. فَإِذَا خَرَجَ الْإِمَامُ حَضَرَتِ الْمَلَائِكَةُ يَسْتَمِعُونَ الذِّكْرَ". (ق,د,ت,ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഒരാൾ വെള്ളിയാഴ്ച ദിവസം ജനാബത്ത് കുളിപോലെ കുളിക്കുകയും ശേഷം പള്ളിയിലേക്ക് പോവുകയും ചെയ്താൽ അയാൾ ഒരു ഒട്ടകം ബലി നൽകിയവനെപ്പോലെയാണ്. രണ്ടാം സമയത്ത് ഒരാൾ ജുമുഅക്ക് പോയാൽ അവൻ പശുവിനെ ബലി നൽകിയവനെപ്പോലെയാണ്. മൂന്നാമത്തെ സമയത്താണ് ഒരാൾ പോയതെങ്കിൽ അവൻ ഒരു മുട്ടനാടിനെ ബലി നൽകിയവനെപോലെയാണ്. ഒരാൾ നാലാമത്തെ സമയത്താണ് പോയതെങ്കിൽ ഒരു കോഴിയെ ബലി കൊടുത്തവനെപോലെയാണ്. അഞ്ചാമത്തെ സമയത്ത് പോയവൻ ഒരു കോഴിമുട്ട കൊടുത്തവനെപോലെയാണ്. അങ്ങനെ ഇമാം പള്ളിയിലേക്ക് പുറപ്പെട്ടു കഴിഞ്ഞാൽ മലക്കുകൾ ദിക്റുകൾ കേൾക്കാൻ അവിടെ ഹാജറാവും." (ബു,മു,ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 361, 361, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 60, 'عَنِ ابْنِ عُمَرَ قَالَ: خَطَبَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "إِذَا رَاحَ أَحَدُكُمْ إِلَى الْجُمُعَةِ فَلْيَغْتَسِلْ". (ن)', 'ഇബ്നുഉമർ(റ): നബി(സ) ഖുത്വുബ നിർവ്വഹിക്കുമ്പോൾ പറഞ്ഞു: "നിങ്ങളിലാരെങ്കിലും ജുമുഅക്ക് വരികയാണെങ്കിൽ അവൻ കുളിച്ചു കൊള്ളട്ടെ." (ന)', 'ابْنِ عُمَرَ قَالَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 361, 361, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 61, 'عَنِ ابْنِ شِهَابٍ، وَقَدْ سُئِلَ عَنِ الْغُسْلِ يَوْمَ الْجُمُعَةِ فَقَالَ: سُنَّةٌ ،وَقَدْ حَدَّثَنِي بِهِ سَالِمُ بْنُ عَبْدِ اللَّهِ، عَنْ أَبِيهِ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَكَلَّمَ بِهَا عَلَى الْمِنْبَرِ. (ن)', 'ഇബ്നുശിഹാബ്(റ): വെള്ളിയാഴ്ച ദിവസത്തെ കുളിയെ കുറിച്ച് അദ്ദേഹത്തോട് ചോദിക്കപ്പെട്ടപ്പോൾ അദ്ദേഹം പറഞ്ഞു: അത് സുന്നത്താണ്, അതിനെ സംബന്ധിച്ച് സാലിമുബ്നു അബ്ദുല്ലാഹിബ്നു ഉമർ(റ), അദ്ദേഹത്തിന്റെ പിതാവ് അദ്ദേഹത്തോട് ഇപ്രകാരം പറഞ്ഞതായി എന്നോട് പറഞ്ഞിട്ടുണ്ട്.: നബി(സ) അത് മിമ്പറിൽ വെച്ച് പറഞ്ഞിരുന്നു. (ന)', 'ابْنِ شِهَابٍ، وَقَدْ سُئِلَ عَنِ الْغُسْلِ يَوْمَ الْجُمُعَةِ فَقَالَ', 'ഇബ്നുശിഹാബ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 361, 361, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 62, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا يَقُولُ: عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ وَهُوَ قَائِمٌ عَلَى الْمِنْبَرِ: "مَنْ جَاءَ مِنْكُمُ الْجُمُعَةَ فَلْيَغْتَسِلْ". (ن)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): നബി(സ) മിമ്പറിലായിരിക്കെ പറഞ്ഞു: "ആരെങ്കിലും ജുമുഅക്ക് വരുന്നുണ്ടെങ്കിൽ അവൻ കുളിച്ചു കൊള്ളട്ടെ." (ന)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 361, 361, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 63, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَ النَّاسُ يَنْتَابُونَ يَوْمَ الْجُمُعَةِ مِنْ مَنَازِلِهِمْ وَالْعَوَالِي، فَيَأْتُونَ فِي الْغُبَارِ يُصِيبُهُمُ الْغُبَارُ وَالْعَرَقُ، فَيَخْرُجُ مِنْهُمُ الْعَرَقُ، فَأَتَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ سَلَّمَ إِنْسَانٌ مِنْهُمْ وَهُوَ عِنْدِي، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَوْ أَنَّكُمْ تَطَهَّرْتُمْ لِيَوْمِكُمْ هَذَا". (خ)', 'ആഇശ(റ): ആളുകൾ അകലെയുള്ള അവരുടെ ഗൃഹങ്ങളിൽ നിന്നും അവരുടെ പ്രദേശങ്ങളിൽ നിന്നും ഊഴമിട്ടാണ് ജുമുഅക്ക് വരാറ്. പൊടിമണ്ണിലൂടെയാണവർ വരാറുള്ളത്. അപ്പോൾ അവരുടെ ശരീരത്തിൽ പൊടി പറ്റുകയും അവർ വിയർക്കുകയും ചെയ്യും, വിയർപ്പിന്റെ ദുർഗന്ധം പുറത്തേക്കു വരും. നബി(സ) എന്റെ അടുത്തായിരിക്കെ, അവരിൽ നിന്നുള്ള ഒരു മനുഷ്യൻ തിരുമേനിയുടെ അടുക്കൽ വന്നു. അപ്പോൾ നബി(സ) ചോദിച്ചു: "ഈ ദിവസം നിങ്ങൾക്ക് ശുദ്ധി വരുത്താമായിരുന്നില്ലേ?" (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 361, 361, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 64, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: كَانَ النَّاسُ مَهَنَةَ أَنْفُسِهِمْ، وَكَانُوا إِذَا رَاحُوا إِلَى الْجُمُعَةِ رَاحُوا فِي هَيْئَتِهِمْ، فَقِيلَ لَهُمْ: "لَوِ اغْتَسَلْتُمْ". (خ)', 'ആഇശ(റ): ആളുകൾ തങ്ങളുടെ ജോലികൾ സ്വയം നിർവ്വഹിക്കുകയായിരുന്നു പതിവ്. അവർ ജുമുഅക്ക് പോവുന്നതും അതേനിലയിൽ തന്നെയായിരുന്നു. അപ്പോൾ നബി(സ) അവരോട് പറഞ്ഞു: "നിങ്ങൾ കുളിച്ചു വന്നെങ്കിൽ (എത്ര നന്നായിരുന്നു)." (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 362, 362, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 65, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا يَقُولُ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "كُلُّكُمْ رَاعٍ، وَكُلُّكُمْ مَسْئُولٌ عَنْ رَعِيَّتِهِ، الْإِمَامُ رَاعٍ،وَمَسْئُولٌ عَنْ رَعِيَّتِهِ، وَالرَّجُلُ رَاعٍ فِي أَهْلِهِ، وَهُوَ مَسْئُولٌ عَنْ رَعِيَّتِهِ، وَالْمَرْأَةُ رَاعِيَةٌ فِي بَيْتِ زَوْجِهَا، وَمَسْئُولَةٌ عَنْ رَعِيَّتِهَا، وَالْخَادِمُ رَاعٍ فِي مَالِ سَيِّدِهِ، وَمَسْئُولٌ عَنْ رَعِيَّتِهِ". قَالَ: وَحَسِبْتُ أَنْ قَدْ قَالَ: "وَالرَّجُلُ رَاعٍ فِي مَالِ أَبِيهِ وَمَسْئُولٌ عَنْ رَعِيَّتِهِ، وَكُلُّكُمْ رَاعٍ، وَمَسْئُولٌ عَنْ رَعِيَّتِهِ". (خ)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "ഓരോരുത്തരും അധികാരികളാണ്, എല്ലാവരും തന്റെ പ്രജകളെക്കുറിച്ച് ചോദ്യം ചെയ്യപ്പെടും. ഇമാം അധികാരിയാണ്. അവൻ തന്റെ പ്രജകളെകുറിച്ച് ചോദ്യം ചെയ്യപ്പെടും. ഒരാൾ തന്റെ കുടുംബത്തിലെ അധികാരിയാണ്, അവൻ തന്റെ പ്രജകളെ കുറിച്ച് ചോദ്യം ചെയ്യപ്പെടും. ഒരു സ്ത്രീ തന്റെ ഭർത്താവിന്റെ വീട്ടിലെ ഭരണാധികാരിയാണ്, അവൾ തന്റെ പ്രജകളെക്കുറിച്ച് ചോദ്യം ചെയ്യപ്പെടും. അടിമ തന്റെ ഉടമയുടെ മുതലിന്റെ അധികാരിയാണ്. അവൻ തന്റെ പ്രജകളെക്കുറിച്ച് ചോദ്യം ചെയ്യപ്പെടും." നബി(സ) ഇത്രത്തോളം പറയുമോ എന്ന് ഞാൻ കരുതി "ഒരാൾ തന്റെ പിതാവിന്റെ ധനത്തിന്റെ കാര്യത്തിൽ ഭരണാധികാരിയാണ്, അതിനെക്കുറിച്ചവൻ ചോദിക്കപ്പെടും. എല്ലാവരും ഭരണാധികാരികളാണ്, അവർ തങ്ങളുടെ പ്രജകളെ കുറിച്ച് ചോദ്യം ചെയ്യപ്പെടും." (ബു)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 362, 362, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 66, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْغُسْلُ يَوْمَ الْجُمُعَةِ وَاجِبٌ عَلَى كُلِّ مُحْتَلِمٍ، وَالسِّوَاكُ، وَيَمَسُّ مِنَ الطِّيبِ مَا قَدَرَ عَلَيْهِ وَلَوْ مِنْ طِيبِ الْمَرْأَةِ". (ن)', 'ഇബ്നുമസ്ഊദ്(റ): നബി(സ) പറഞ്ഞു: "പ്രായപൂർത്തിയായ ഓരോരുത്തർക്കും വെള്ളിയാഴ്ചദിവസം കുളിക്കലും, ദന്തശുദ്ധിവരുത്തലും നിർബന്ധമാണ്. കഴിവനുസരിച്ച് സുഗന്ധം പൂശുകയും ചെയ്യണം. സത്രകളുപയോഗിച്ചു വരാറുള്ള (ഗന്ധംകുറഞ്ഞ) സുഗന്ധമെങ്കിലും ഉപയോഗിക്കുക. (ന)', 'أَبِي سَعِيدٍ', 'ഇബ്നുമസ്ഊദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 362, 362, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 67, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ :أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "غُسْلُ يَوْمِ الْجُمُعَةِ عَلَى كُلِّ مُحْتَلِمٍ، وَسِوَاكٌ، وَيَمَسُّ مِنَ الطِّيبِ مَا قَدَرَ عَلَيْهِ". (م)', 'അബൂസഈദിൽ ഖുദ്രി(റ): നബി(സ) അരുളി: "പ്രായപൂർത്തിയായ എല്ലാവർക്കും വെള്ളിയാഴ്ച ദിവസം കുളിയും പല്ലുതേക്കലും അവന് സാധ്യമായ സുഗന്ധം പൂശലും നിർബന്ധമാകുന്നു." (മു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 362, 362, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 68, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ:أَشْهَدُ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ قَالَ: "الْغُسْلُ يَوْمَ الْجُمُعَةِ وَاجِبٌ عَلَى كُلِّ مُحْتَلِمٍ، وَأَنْ يَسْتَنَّ، وَأَنْ يَمُسَّ طِيبًا إِنْ وَجَدَ". (ق,د,ن,جه)', 'അബൂസഈദുൽ ഖുദ്രി(റ): ഞാൻ നബി(സ)യെക്കൊണ്ട് സാക്ഷ്യപ്പെടുത്തുന്നു; പ്രായപൂർത്തിയായ എല്ലാവർക്കും വെള്ളിയാഴ്ച കുളി നിർബന്ധമാണ്. പല്ലു തേക്കലും ഉണ്ടെങ്കിൽ സുഗന്ധമുപയോഗിക്കലും നിർബന്ധമാണ്." (ബു,മു,ദ,ന,ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദുൽ ഖുദ്രി(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 362, 362, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 69, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنِ اغْتَسَلَ يَوْمَ الْجُمُعَةِ فَأَحْسَنَ غُسْلَهُ، وَتَطَهَّرَ فَأَحْسَنَ طُهُورَهُ، وَلَبِسَ مِنْ أَحْسَنِ ثِيَابِهِ، وَمَسَّ مَا كَتَبَ اللَّهُ لَهُ مِنْ طِيبِ أَهْلِهِ، ثُمَّ أَتَى الْجُمُعَةَ، وَلَمْ يَلْغُ وَلَمْ يُفَرِّقْ بَيْنَ اثْنَيْنِ، غُفِرَ لَهُ مَا بَيْنَهُ وَبَيْنَ الْجُمُعَةِ الْأُخْرَى". (جه)', 'അബൂദർറ്(റ): നബി(സ) പറഞ്ഞു: “ആരെങ്കിലും വെള്ളിയാഴ്ച ദിവസം ഭംഗിയായി കുളിക്കുകയും കഴിയുന്നത്ര ശുദ്ധി വരുത്തുകയും ഏറ്റവും നല്ല വസ്ത്രം ധരിക്കുകയും തന്റെ കുടുംബത്തിലെ സുഗന്ധത്തിൽ നിന്ന് അല്ലാഹു വിധിച്ച ഒരളവ് പൂശുകയും, അനാവശ്യങ്ങളിലേർപ്പെടാതെയും രണ്ടുപേരുടെ ഇടയിൽ വേർതിരിവുണ്ടാക്കാതെ ജുമുഅക്ക് ചെന്ന് അത് (നിസ്കാരം) നിർവ്വഹിക്കുകയും ചെയ്താൽ ഒരു ജുമുഅഃ മുതൽ അടുത്ത ജുമുഅഃ വരെയുള്ള അവന്റെ പാപങ്ങൾ പൊറുക്കപ്പെടുന്നതാണ്.” (ജ)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 363, 363, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 70, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ هَذَا يَوْمُ عِيدٍ جَعَلَهُ اللَّهُ لِلْمُسْلِمِينَ، فَمَنْ جَاءَ إِلَى الْجُمُعَةِ فَلْيَغْتَسِلْ، وَإِنْ كَانَ طِيبٌ، فَلْيَمَسَّ مِنْهُ، وَعَلَيْكُمْ بِالسِّوَاكِ". (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) അരുളി: “മുസ്‌ലിംകൾക്ക് അല്ലാഹു നിശ്ചയിച്ച പെരുന്നാൾ ദിനമാണ് ഇന്ന്. അതിനാൽ ജുമുഅക്ക് വരാൻ ഉദ്ദേശിക്കുന്നവൻ കുളിക്കുകയും സുഗന്ധമുണ്ടെങ്കിൽ അത് പൂശുകയും ചെയ്യട്ടെ. പല്ലു തേക്കുകയും വേണം.” (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 363, 363, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 71, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي أَوْ عَلَى النَّاسِ، لَأَمَرْتُهُمْ بِالسِّوَاكِ مَعَ كُلِّ صَلَاةٍ". (خ)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: “എന്റെ സമുദായത്തെ (ജനതയെ) പ്രയാസപ്പെടുത്തലാകുമോ എന്ന് ഞാൻ ഭയപ്പെട്ടില്ലായിരുന്നുവെങ്കിൽ എല്ലാ നിസ്കാരത്തോടനുബന്ധിച്ചും പല്ലു തേക്കണമെന്ന് ഞാനവരോട് കൽപിക്കുമായിരുന്നു. (നിർബന്ധിക്കുമായിരുന്നു)” (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 363, 363, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 72, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "حَقٌّ عَلَى الْمُسْلِمِينَ، أَنْ يَغْتَسِلُوا يَوْمَ الْجُمُعَةِ، وَلْيَمَسَّ أَحَدُهُمْ مِنْ طِيبِ أَهْلِهِ، فَإِنْ لَمْ يَجِدْ فَالْمَاءُ لَهُ طِيبٌ". (ت)', 'ബറാഅബ്നു ആസിബ്(റ): നബി(സ) പറഞ്ഞു: “വെള്ളിയാഴ്ച ദിവസം കുളിക്കുന്നതും തന്റെ കുടുംബത്തിലുള്ള സുഗന്ധത്തിൽ നിന്ന് അൽപം പൂശലും മുസ്‌ലിംകൾക്ക് ബാധ്യതയാകുന്നു. സുഗന്ധം ലഭിച്ചില്ലെങ്കിൽ വെള്ളമാണ് അവന്റെ സുഗന്ധം.” (തു)', 'الْبَرَاءِ بْنِ عَازِبٍ', 'ബറാഅബ്നു ആസിബ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 363, 363, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 73, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْغُسْلُ يَوْمَ الْجُمُعَةِ وَاجِبٌ عَلَى كُلِّ مُحْتَلِمٍ، وَالسِّوَاكُ، وَيَمَسُّ مِنَ الطَّيِّبِ مَا قَدَرَ عَلَيْهِ وَلَوْ مِنْ طِيبِ الْمَرْأَةِ". (ن)', 'പ്രായപൂർത്തിയായ ഓരോരുത്തനും ജുമുഅഃ ദിനത്തിൽ കുളിക്കലും ദന്തശുദ്ധി വരുത്തലും സാധ്യമായത്ര സുഗന്ധം പൂശലും നിർബന്ധമാണ്. - സ്ത്രീകളുപയോഗിക്കുന്ന (നിറവും കുറഞ്ഞ തോതിൽ മണവുമുള്ള) സുഗന്ധമെങ്കിലും - . (ന)', 'أَبِي سَعِيدٍ', null, null, null, array['ن']::text[], array['ന']::text[], null, null, 363, 363, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 74, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَكْثَرْتُ عَلَيْكُمْ فِي السِّوَاكِ". (ن)', 'അനസ്(റ); നബി(സ) പറഞ്ഞു: “മിസ്‌വാക്ക് ചെയ്യൽ ഞാൻ നിങ്ങൾക്ക് അധികരിപ്പിച്ചിരിക്കുന്നു.” (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 363, 363, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 75, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ عُمَرَ بْنَ الْخَطَّابِ رَأَى حُلَّةَ سِيَرَاءَ - يَعْنِي تُبَاعُ عِنْدَ بَابِ الْمَسْجِدِ - فَقَالَ: يَا رَسُولَ اللَّهِ، لَوِ اشْتَرَيْتَ هَذِهِ فَلَبِسْتَهَا يَوْمَ الْجُمُعَةِ وَلِلْوَفْدِ إِذَا قَدِمُوا عَلَيْكَ. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّمَا يَلْبَسُ هَذِهِ مَنْ لَا خَلَاقَ لَهُ فِي الْآخِرَةِ". ثُمَّ جَاءَتْ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْهَا حُلَلٌ فَأَعْطَى عُمَرَ حُلَّةً، فَقَالَ عُمَرُ: كَسَوْتَنِيهَا يَا رَسُولَ اللهِ وَقَدْ قُلْتَ فِي حُلَّةِ عُطَارِدَ مَا قُلْتَ؟ فَقَالَ رَسُولُ اللهِ: "إِنِّي لَمْ أَكْسُكَهَا لِتَلْبَسَهَا". فَكَسَاهَا عُمَرُ أَخًا لَهُ مُشْرِكًا بِمَكَّةَ. وَفِي رِوَايَةٍ: وَجَدَ عُمَرُ بْنُ الْخَطَّابِ حُلَّةَ إِسْتَبْرَقٍ تُبَاعُ بِالسُّوقِ، فَأَخَذَهَا فَأَتَى بِهَا رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "ابْتَعْ هَذِهِ تَجَمَّلْ بِهَا لِلْعِيدِ وَلِلْوُفُودِ"، ثُمَّ سَاقَ الْحَدِيثَ، وَالْأَوَّلُ أَتَمُّ. (ق,د,ن)', 'അബ്ദുല്ലാഹിബ്‌നു ഉമർ(റ): പട്ടുനൂലിനാൽ നെയ്ത ഒരു വസ്ത്രം പള്ളിവാതിലിൽ വെച്ച് വില്പന നടത്തുന്നത് കണ്ടപ്പോൾ അദ്ദേഹം ചോദിച്ചു: പ്രവാചകരേ, താങ്കൾ ഇത് വാങ്ങി വെള്ളിയാഴ്ച ദിവസവും നിവേദക സംഘം വരുമ്പോഴും ധരിച്ചിരുന്നെങ്കിൽ നന്നായിരുന്നു. നബി(സ) പറഞ്ഞു: "പരലോകത്ത് ലവലേശം നന്മ ഇല്ലാത്തവൻ മാത്രമെ ഈ വസ്ത്രം ധരിക്കുകയുള്ളൂ." പിന്നീട് നബി(സ)ക്ക് അത്തരം കുറേ വസ്ത്രങ്ങൾ വന്നു. അപ്പോൾ നബി(സ) അതിലൊന്ന് ഉമർ(റ)ന് നൽകി. അപ്പോൾ ഉമർ(റ) പറഞ്ഞു: "ദൈവദൂതരേ, അവിടുന്ന് എനിക്കിത് ധരിക്കാൻ തരുന്നു. ഉതാരിദ് വസ്ത്രത്തെ കുറിച്ച് അവിടുന്ന് ചിലതെല്ലാം എന്നോട് അരുളിയിട്ടുണ്ടായിരുന്നല്ലോ? അപ്പോൾ നബി(സ) പറഞ്ഞു: "അത് ഞാൻ നിങ്ങൾക്ക് ധരിക്കാൻ വേണ്ടിയല്ല നൽകിയത്." അവസാനം മക്കാ നിവാസിയും ബഹുദൈവ വിശ്വാസിയുമായ തന്റെ ഒരു സഹോദരന് ഉമർ(റ) അത് ധരിക്കാൻ കൊടുത്തു.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=18 and h.hadith_no=75), 1, 'وَفِي رِوَايَةٍ: وَجَدَ عُمَرُ بْنُ الْخَطَّابِ حُلَّةَ إِسْتَبْرَقٍ تُبَاعُ بِالسُّوقِ، فَأَخَذَهَا فَأَتَى بِهَا رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "ابْتَعْ هَذِهِ تَجَمَّلْ بِهَا لِلْعِيدِ وَلِلْوُفُودِ"، ثُمَّ سَاقَ الْحَدِيثَ، وَالْأَوَّلُ أَتَمُّ. (ق,د,ن)', 'മറ്റൊരു നിവേദനം: ഒരു പട്ടുവസ്ത്രം അങ്ങാടിയൽ വിൽപനക്ക് വെച്ചതായി ഉമർ(റ) കണ്ടു. അപ്പോൾ അതെടുത്ത് അതുമായി പ്രവാചകസന്നിധിയിൽ ചെന്നു. അപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "നീ ഇത് വാങ്ങി പെരുന്നാളിനും യാത്രാവേളയിലും ഉപയോഗിക്കുക." ഹദീസ് തുടർന്നു. ഒന്നാമത്തേതാണ് പൂർണ്ണമായത്. (ബു,മു,ദ,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 76, 'عَنْ مُحَمَّدِ ابْنِ يَحْيَى بْنِ حَبَّانَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَا عَلَى أَحَدِكُمْ إِنْ وَجَدَ - أَوْ مَا عَلَى أَحَدِكُمْ إِنْ وَجَدْتُمْ - أَنْ يَتَّخِذَ ثَوْبَيْنِ لِيَوْمِ الْجُمُعَةِ، سِوَى ثَوْبَيْ مِهْنَتِهِ". (د,جه)', 'ഇബ്‌നുഹനാൻ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾക്ക് സാമ്പത്തിക വിശാലതയുണ്ടായാൽ തന്റെ ജോലിയുടെ (ജോലിയെടുക്കുമ്പോൾ ധരിക്കുന്ന) രണ്ടു വസ്ത്രങ്ങൾ കൂടാതെ തന്റെ ജുമുഅഃ നിസ്കാരത്തിന് വേണ്ടി മാത്രമായി രണ്ടു വസ്ത്രം ഉണ്ടാക്കൽ നിർബന്ധമില്ല." (ദ,ജ)', 'مُحَمَّدِ ابْنِ يَحْيَى بْنِ حَبَّانَ', 'ഇബ്‌നുഹനാൻ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 364, 364, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 77, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خَطَبَ النَّاسَ يَوْمَ الْجُمُعَةِ، فَرَأَى عَلَيْهِمْ ثِيَابَ النِّمَارِ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَا عَلَى أَحَدِكُمْ - إِنْ وَجَدَ سَعَةً - أَنْ يَتَّخِذَ ثَوْبَيْنِ لِجُمُعَتِهِ سِوَى ثَوْبَيْ مِهْنَتِهِ". (جه)', 'ആഇശ(റ): നബി(സ) ജുമുഅഃ ദിനം ജനങ്ങളോട് പ്രസംഗിക്കവെ അവരിൽ വരകളുള്ള (പുലിയുടെ നിറം പോലെയുള്ള) കമ്പിളി വസ്ത്രം കണ്ടു. നബി(സ) പറഞ്ഞു: "നിങ്ങൾക്ക് സാമ്പത്തിക വിശാലതയുണ്ടായാൽ തന്റെ ജോലിയുടെ രണ്ടു വസ്ത്രത്തെ കൂടാതെ തന്റെ ജുമുഅഃ നിസ്കാരത്തിന് വേണ്ടി രണ്ടു വസ്ത്രം ഉണ്ടാക്കേണ്ടതില്ല." (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 364, 364, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 78, 'عَنْ عَبْدِ اللهِ بْنِ سَلَامٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُ سَمِعَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ عَلَى الْمِنْبَرِ فِي يَوْمِ الْجُمُعَةِ: "مَا عَلَى أَحَدِكُمْ لَوِ اشْتَرَى ثَوْبَيْنِ لِيَوْمِ الْجُمُعَةِ سِوَى ثَوْبِ مِهْنَتِهِ". (د,جه)', 'അബ്ദുല്ലാഹിബ്‌നു സലാം(റ): നബി(സ) ജുമുഅഃ ദിവസം മിമ്പറിൽ വെച്ച് പറയുന്നതായി അദ്ദേഹം കേട്ടു: "ജോലിക്കു ധരിക്കുന്ന വസ്ത്രത്തിനു പുറമെ ജുമഅക്കുവേണ്ടി നിങ്ങൾക്ക് രണ്ട് വസ്ത്രം കൂടി അധികം വാങ്ങേണ്ടതില്ല." (ദ,ജ)', 'عَبْدِ اللهِ بْنِ سَلَامٍ', 'അബ്ദുല്ലാഹിബ്‌നു സലാം(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 364, 364, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 79, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا كَانَ يَوْمُ الْجُمُعَةِ كَانَ عَلَى كُلِّ بَابٍ مِنْ أَبْوَابِ الْمَسْجِدِ مَلَائِكَةٌ يَكْتُبُونَ الْأَوَّلَ فَالْأَوَّلَ، فَإِذَا جَلَسَ الْإِمَامُ طَوَوُا الصُّحُفَ، وَجَاءُوا يَسْتَمِعُونَ الذِّكْرَ وَمَثَلُ الْمُهَجِّرِ كَمَثَلِ الَّذِي يُهْدِي الْبَدَنَةَ، ثُمَّ كَالَّذِي يُهْدِي بَقَرَةً، ثُمَّ كَالَّذِي يُهْدِي الْكَبْشَ، ثُمَّ كَالَّذِي يُهْدِي الدَّجَاجَةَ، ثُمَّ كَالَّذِي يُهْدِي الْبَيْضَةَ". (م,ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "വെള്ളിയാഴ്ചയായാൽ പള്ളിയുടെ ഓരോ കവാടത്തിലും മലക്കുകൾ ആദ്യമാദ്യം കടന്നു വരുന്നവരുടെ പേരുകൾ രേഖപ്പെടുത്തും. അങ്ങനെ ഇമാം (മിമ്പറിൽ) ഇരുന്നു കഴിഞ്ഞാൽ അവർ ഏടുകൾ മടക്കിവെക്കും. അവരും ഖുത്വുബ കേൾക്കാൻ വരും. ഏറ്റവും നേരത്തെ എത്തിയ ആൾ ഒരു ഒട്ടകത്തെ ദാനം ചെയ്തവനും, രണ്ടാമതെത്തിയ ആൾ ഒരു പശുവിനെ ദാനം ചെയ്തവനും, പിന്നീടെത്തിയ ആൾ കോഴിയെ ദാനം ചെയ്തവനും തുല്യമാണ്. പിന്നീടെത്തുന്ന ആൾ കോഴിമുട്ട ദാനം ചെയ്തവന് തുല്യനാണ്." (മു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 365, 365, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 80, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا كَانَ يَوْمُ الْجُمُعَةِ، كَانَ عَلَى كُلِّ بَابٍ مِنْ أَبْوَابِ الْمَسْجِدِ مَلَائِكَةٌ، يَكْتُبُونَ النَّاسَ عَلَى قَدْرِ مَنَازِلِهِمْ: الْأَوَّلَ فَالْأَوَّلَ، فَإِذَا خَرَجَ الْإِمَامُ طَوَوُا الصُّحُفَ، وَاسْتَمَعُوا الْخُطْبَةَ، فَالْمُهَجِّرُ إِلَى الصَّلَاةِ كَالْمُهْدِي بَدَنَةً، ثُمَّ الَّذِي يَلِيهِ كَمُهْدِي بَقَرَةٍ، ثُمَّ الَّذِي يَلِيهِ كَمُهْدِي كَبْشٍ حَتَّى ذَكَرَ الدَّجَاجَةَ وَالْبَيْضَةَ. فَمَنْ جَاءَ بَعْدَ ذَلِكَ فَإِنَّمَا يَجِيءُ بِحَقٍّ إِلَى الصَّلَاةِ". (م,ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "വെള്ളിയാഴ്ച ദിവസമായാൽ പള്ളിയുടെ ഓരോ കവാടത്തിലും മലക്കുകൾ ഉണ്ടാവും. ജനങ്ങളുടെ ആദ്യാദ്യ (പള്ളിയിലേക്കു വന്നെത്തിയതിന്റെ ക്രമപ്രകാരമുള്ള) പദവികൾ അനുസരിച്ച് രേഖപ്പെടുത്തിക്കൊണ്ടിരിക്കും. അങ്ങനെ ഇമാം മിമ്പറിലേക്ക് പുറപ്പെട്ടാൽ അവരുടെ ഏടുകൾ മടക്കി വെക്കുകയും ഖുത്വുബ ശ്രവിക്കുകയും ചെയ്യും. നിസ്കാരത്തിന്നായി ഒന്നാമതായി പുറപ്പെട്ടയാൾ ഒരു ഒട്ടകം ദാനം ചെയ്തവനെപ്പോലെയും തുടർന്നു വരുന്ന ആൾ ഒരു പശുവിനെ ദാനം ചെയ്തവനെപ്പോലെയും, തുടർന്നു വരുന്നവർ ആടിനെ ദാനം ചെയ്തവനെപോലെയുമാകുന്നു." പ്രവാചകൻ(സ) അതിൽ കോഴിയെയും കോഴിമുട്ടയെയും (ദാനം ചെയ്തവനെപ്പോലെ എന്നു) പറയുന്നതുവരെ പ്രവാചകൻ(സ) തന്റെ സംസാരം തുടർന്നു. (എന്നിട്ടു പറഞ്ഞു:) അതിനുശേഷം വരുന്നയാൾ നിസ്കാരത്തിന്റെ ബാധ്യത നിർവ്വഹിച്ചവൻ മാത്രമായിരിക്കും (നിസ്കാരത്തിന്റെ പ്രതിഫലം മാത്രമേ അവന് ഉണ്ടാവുകയുള്ളൂ). (മു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','ن','جه']::text[], array['മു','ന','ജ']::text[], null, null, 365, 365, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 81, 'عَنْ عَلْقَمَةَ رَضِيَ اللهُ عَنْهُ قَالَ: خَرَجْتُ مَعَ عَبْدِ اللهِ بْنِ مَسْعُودٍ إِلَى الْجُمُعَةِ، فَوَجَدَ ثَلَاثَةً وَقَدْ سَبَقُوهُ. فَقَالَ: رَابِعُ أَرْبَعَةٍ، وَمَا رَابِعُ أَرْبَعَةٍ بِبَعِيدٍ. إِنِّي سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّ النَّاسَ يَجْلِسُونَ مِنَ اللهِ يَوْمَ الْقِيَامَةِ عَلَى قَدْرِ رَوَاحِهِمْ إِلَى الْجُمُعَاتِ: الْأَوَّلُ وَالثَّانِي وَالثَّالِثُ". ثُمَّ قَالَ: "رَابِعُ أَرْبَعَةٍ، وَمَا رَابِعُ أَرْبَعَةٍ بِبَعِيدٍ". (جه)', 'അൽഖമ(റ): ഞാൻ ഇബ്നുമസ്ഊദി(റ)നോടൊപ്പം ജുമുഅക്കു പുറപ്പെട്ടു. അദ്ദേഹത്തിനുമുമ്പേ വന്ന മൂന്നാളുകളെ അവിടെ കണ്ടു. അപ്പോൾ ഇബ്നുമസ്ഊദ്(റ) പറഞ്ഞു: (ഞാൻ) നാലിൽ ഒരാൾ. നാലിൽ ഒരാളാവുക (എന്ന പദവി) അതിവിദൂരമൊന്നുമല്ല. നബി(സ) ഇങ്ങനെ പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: "ജുമുഅക്കു പോകുന്ന(സമയ)തിന്റെ തോതനുസരിച്ചാണ് അന്ത്യനാളിൽ അല്ലാഹുവിന്റെ അടുക്കൽ ജനങ്ങളുടെ സ്ഥാനം. ആദ്യത്തെയാൾ, രണ്ടാമൻ, മൂന്നാമൻ (എന്നിങ്ങനെ)." തുടർന്ന് നബി(സ) പറഞ്ഞു: "നാലിൽ ഒരാൾ, നാലിൽ ഒരാളാവുക എന്നത് വിദൂരമൊന്നുമല്ല." (ജ)', 'عَلْقَمَةَ', 'അൽഖമ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 365, 365, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 82, 'عَنْ أَبِي حَازِمٍ رَضِيَ اللهُ عَنْهُ: أَنَّ نَفَرًا جَاءُوا إِلَى سَهْلِ بْنِ سَعْدٍ، قَدْ تَمَارَوْا فِي الْمِنْبَرِ مِنْ أَيِّ عُودٍ هُوَ؟ فَقَالَ: أَمَا وَاللهِ، إِنِّي لَأَعْرِفُ مِنْ أَيِّ عُودٍ هُوَ؟ وَمَنْ عَمِلَهُ؟ وَرَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَوَّلَ يَوْمٍ جَلَسَ عَلَيْهِ، قَالَ: فَقُلْتُ لَهُ: يَا أَبَا عَبَّاسٍ فَحَدِّثْنَا، قَالَ: أَرْسَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِلَى امْرَأَةٍ - قَالَ أَبُو حَازِمٍ إِنَّهُ لَيُسَمِّهَا يَوْمَئِذٍ -: "انْظُرِي غُلَامَكِ النَّجَّارَ يَعْمَلْ لِي أَعْوَادًا أُكَلِّمُ النَّاسَ عَلَيْهَا". فَعَمِلَ هَذِهِ الثَّلَاثَ دَرَجَاتٍ، ثُمَّ أَمَرَ بِهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَوُضِعَتْ هَذَا الْمَوْضِعَ، فَهِيَ مِنْ طَرْفَاءِ الْغَابَةِ، وَلَقَدْ رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَامَ عَلَيْهِ فَكَبَّرَ وَكَبَّرَ النَّاسُ وَرَاءَهُ، وَهُوَ عَلَى الْمِنْبَرِ، ثُمَّ رَفَعَ فَنَزَلَ الْقَهْقَرَى حَتَّى سَجَدَ فِي أَصْلِ الْمِنْبَرِ، ثُمَّ عَادَ حَتَّى فَرَغَ مِنْ آخِرِ صَلَاتِهِ. ثُمَّ أَقْبَلَ عَلَى النَّاسِ فَقَالَ: "يَا أَيُّهَا النَّاسُ [إِنِّي] صَنَعْتُ هَذَا لِتَأْتَمُّوا بِي، وَلِتَعَلَّمُوا صَلَاتِي". (ق, ن, جه)', 'അബൂഹാസിം(റ): നബി(സ)യുടെ മിമ്പർ ഏത് തടിയിൽ നിർമ്മിച്ചതാണ് എന്ന വിഷയത്തിൽ തർക്കിച്ചുകൊണ്ട് ഒരു സംഘം സഹ്ലുബ്നു സഅ്ദി(റ)ന്റെ അടുക്കൽ വന്നു. അദ്ദേഹം (സഅ്ദ്(റ)) പറഞ്ഞു: "അല്ലാഹുവാണെ! ഇത് ഏത് തടികൊണ്ട് ആര് നിർമ്മിച്ചു എന്ന് എനിക്കറിയാം. റസൂൽ(സ) ആദ്യമായി അതിന്മേൽ ഇരുന്ന ദിവസം ഞാൻ കണ്ടിട്ടുണ്ട്. അബൂഹാസിം പറയുന്നു: ഇത് പറഞ്ഞപ്പോൾ ഞാൻ അദ്ദേഹത്തോട് ചോദിച്ചു: ഓ അബൂഅബ്ബാസ്, താങ്കൾ അതൊന്ന് ഞങ്ങൾക്ക് വിവരിച്ചു തന്നാലും, അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: "എനിക്ക് ജനങ്ങളോട് സംസാരിക്കാൻ വേണ്ടി ഒരു മിമ്പർ ഉണ്ടാക്കിത്തരാൻ നിന്റെ ആശാരിയോട് പറയണം." എന്ന് കൽപിച്ചുകൊണ്ട് നബി(സ) ഒരു സ്ത്രീയുടെ (നബി(സ) ആ സ്ത്രീയുടെ പേര് പറഞ്ഞിരുന്നു.) അടുത്തേക്ക് ഒരാളെ പറഞ്ഞയച്ചു. അങ്ങനെ കാട്ടിലെ ഭാനുക മരം (മുന്തിയ ഒരു തരം മരം) കൊണ്ട് മൂന്ന് പടവുകളുള്ള ഒരു മിമ്പർ നിർമ്മിക്കപ്പെട്ടു. നബി(സ)യുടെ നിർദ്ദേശാനുസരണം ആ മിമ്പർ പള്ളിയിൽ സ്ഥാപിക്കപ്പെട്ടു. നിശ്ചയം നബി(സ) അതിന്മേൽ കയറി നിന്നുകൊണ്ട് (നിസ്കാരത്തിന്) തക്ബീർ ചൊല്ലിയതും പിന്നിൽ നിന്ന് ജനങ്ങൾ തക്ബീർ ചൊല്ലിയതും ഞാൻ കണ്ടിട്ടുണ്ട്. പിന്നെ (റുകൂഅ് ചെയ്തശേഷം) റുകൂഇൽനിന്ന് ഉയർന്ന് പിറകോട്ട് മാറി മിമ്പറിൽനിന്നിറങ്ങി. മിമ്പറിന്റെ താഴെ സുജൂദ് ചെയ്തു. പിന്നെ തത്സ്ഥാനത്തേക്ക് മടങ്ങി. നിസ്കാരം നിർവ്വഹിച്ചു കഴിഞ്ഞശേഷം ജനങ്ങളുടെ മുന്നിലേക്ക് തിരിഞ്ഞുകൊണ്ട് നബി(സ) പറഞ്ഞു: "ഹേ ജനങ്ങളേ ഞാൻ ഇങ്ങനെ ചെയ്തത് നിങ്ങൾ എന്നെ തുടർന്നു നിസ്കരിക്കുവാനും എന്റെ നമസ്കാരം കണ്ടു പഠിക്കുവാനും വേണ്ടിയാണ്." (ബു,മു,ന,ജ)', 'أَبِي حَازِمٍ', 'അബൂഹാസിം(റ)', null, null, array['ق','ن','جه']::text[], array['ബു','മു','ന','ജ']::text[], 'إِنِّي', null, 366, 366, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 83, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَخْطُبُ إِلَى جِذْعٍ، فَلَمَّا اتَّخَذَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْمِنْبَرَ حَنَّ الْجِذْعُ، حَتَّى أَتَاهُ فَالْتَزَمَهُ فَسَكَنَ. حَسَنٌ صَحِيحٌ (خ, ت)', 'ഇബ്‌നുഉമർ(റ): റസൂൽ(സ) ഈത്തപ്പനത്തടിയുടെ കഷ്ണത്തിന്മേൽ നിന്നായിരുന്നു ഖുത്വുബ നടത്തിയിരുന്നത്. നബി(സ)ക്ക് മിമ്പറുണ്ടാക്കിയപ്പോൾ ഈത്തപ്പനത്തചടിയുടെ കഷ്ണം കരഞ്ഞു. നബി(സ) അതിന്റെ നേരെ തിരിഞ്ഞ് അതിനെ ആശ്ലേഷിച്ചപ്പോൾ അത് നിശ്ശബ്ദമായി. ഹദീസ് ഹസനും സഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു. (ബു,തു)', 'ابْنِ عُمَرَ', 'ഇബ്‌നുഉമർ(റ)', null, null, array['خ','ت']::text[], array['ബു','തു']::text[], null, null, 366, 366, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 84, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَمَّا بَدُنَ قَالَ لَهُ تَمِيمُ الدَّارِيُّ: أَلَا أَتَّخِذُ لَكَ مِنْبَرًا يَا رَسُولَ اللهِ يَجْمَعُ - أَوْ يَحْمِلُ - عِظَامَكَ؟ قَالَ: "بَلَى". فَاتَّخَذَ لَهُ مِنْبَرًا مِرْقَاتَيْنِ. (د)', 'ഇബ്‌നുഉമർ(റ): നബി(സ)ക്ക് പ്രായമായപ്പോൾ തമീമുദ്ദാരി ചോദിച്ചു: താങ്കളുടെ ശരീരം ചുമക്കാവുന്ന ഒരു പീഠം ഞാനങ്ങേക്കുണ്ടാക്കിത്തരട്ടെയോ? നബി(സ) പറഞ്ഞു: "അതെ" അങ്ങനെ നബിക്ക് രണ്ട് പടികളുള്ള ഒരു പീഠം ഉണ്ടാക്കിക്കൊടുത്തു. (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്‌നുഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 366, 366, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 85, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا يَقُولُ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا خَطَبَ يَسْتَنِدُ إِلَى جِذْعِ نَخْلَةٍ مِنْ سَوَارِي الْمَسْجِدِ، فَلَمَّا صُنِعَ الْمِنْبَرُ وَاسْتَوَى عَلَيْهِ اضْطَرَبَتْ تِلْكَ السَّارِيَةُ كَحَنِينِ النَّاقَةِ، حَتَّى سَمِعَهَا أَهْلُ الْمَسْجِدِ، حَتَّى نَزَلَ إِلَيْهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَاعْتَنَقَهَا فَسَكَتَتْ. (ن)', 'ജാബിറുബ്നു അബ്ദുല്ല(റ): പള്ളിയുടെ തൂണുകളിൽ നിന്നുള്ള ഈത്തപ്പനത്തടിയുടെ കഷ്ണത്തിന്മേൽ ചാരി നിന്നായിരുന്നു നബി(സ) ഖുത്വുബ നിർവ്വഹിച്ചിരുന്നത്. മിമ്പർ നിർമ്മിച്ചപ്പോൾ അവിടുന്ന് അതിന്മേൽ നിന്നു. അപ്പോൾ ആ ഈത്തപ്പന മട്ടൽ ഒട്ടകങ്ങൾ കരയുന്ന പോലെ അസ്വസ്ഥമായി. പള്ളിയിലുള്ളവരെല്ലാം അതുകേട്ടു. റസൂൽ(സ) ഇറങ്ങിവന്ന് അതിനെ മാറോടണച്ചപ്പോൾ ശബ്ദം നിലക്കുകയും ചെയ്തു. (ന)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദുല്ല(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 367, 367, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 86, 'عَنْ سَلَمَةَ بْنِ الْأَكْوَعِ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ بَيْنَ مِنْبَرِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَبَيْنَ الْحَائِطِ كَقَدْرِ مَمَرِّ الشَّاةِ. (م,د)', 'സലമതുബ്നു അക്‌വഅ്(റ): നബി(സ)യുടെ മിമ്പറിന്റെയും ചുമരിന്റെയും ഇടയിൽ ഒരു ആടിന് നടക്കാവുന്നത്ര ഇടമുണ്ടായിരുന്നു. (മു,ദ)', 'سَلَمَةَ بْنِ الْأَكْوَعِ', 'സലമതുബ്നു അക്‌വഅ്(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 367, 367, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 87, 'عَنْ سَلَمَةَ بْنِ الْأَكْوَعِ رَضِيَ اللَّهُ عَنْهُ قَالَ: كُنَّا نُجَمِّعُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا زَالَتِ الشَّمْسُ، ثُمَّ نَرْجِعُ نَتَتَبَّعُ الْفَيْءَ. (م)', 'സലമത്ബ്നു അക്‌വഅ്(റ): സൂര്യൻ മദ്ധ്യത്തിൽ നിന്ന് തെറ്റിയാൽ ഞങ്ങൾ നബി(സ)യോടൊപ്പം ജുമുഅഃ നിസ്കരിക്കും. ശേഷം നിഴലുകളെ പിന്തുടരുന്നവരായി ഞങ്ങൾ മടങ്ങും. (മു)', 'سَلَمَةَ بْنِ الْأَكْوَعِ', 'സലമത്ബ്നു അക്‌വഅ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 367, 367, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 88, 'عَنْ أَبِي قَتَادَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُ كَرِهَ الصَّلَاةَ نِصْفَ النَّهَارِ، إِلَّا يَوْمَ الْجُمُعَةِ. وَقَالَ: "إِنَّ جَهَنَّمَ تُسَجَّرُ إِلَّا فِي يَوْمِ الْجُمُعَةِ". (د)', 'അബൂഖതാദ(റ): നബി(സ) പകലിന്റെ മദ്ധ്യത്തിലുള്ള നിസ്കാരം വെറുത്തിരുന്നു. ജുമുഅഃ ദിവസം ഒഴികെ, നബി(സ) പറഞ്ഞു: "ജുമുഅഃ ദിവസത്തിൽ ഒഴികെ (മറ്റെല്ലാ ദിവസങ്ങളിലും) നരകം കത്തിക്കപ്പെടും." (ദ)', 'أَبِي قَتَادَةَ', 'അബൂഖതാദ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 367, 367, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 89, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي الْجُمُعَةَ إِذَا مَالَتِ الشَّمْسُ. (خ,د,ت)', 'അനസുബ്നു മാലിക്(റ): സൂര്യൻ തെറ്റിയാൽ നബി(സ) ജുമുഅഃ നിസ്കരിക്കാറുണ്ടായിരുന്നു. (ബു,ദ,തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['خ','د','ت']::text[], array['ബു','ദ','തു']::text[], null, null, 367, 367, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 90, 'عَنْ سَلَمَةَ بْنِ الْأَكْوَعِ رَضِيَ اللَّهُ عَنْهُ قَالَ: كُنَّا نُصَلِّي مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْجُمُعَةَ ثُمَّ نَنْصَرِفُ وَلَيْسَ لِلْحِيطَانِ فَيْءٌ. (ق,د,ن,جه)', 'സലമതുബ്നു അക്‌വഅ്(റ): ഞങ്ങൾ നബി(സ)യോടൊപ്പം ജുമുഅഃ നിസ്കരിക്കാറുണ്ടായിരുന്നു. പിന്നെ പിരിഞ്ഞുപോവും. അപ്പോഴും ചുമരുകൾക്ക് നിഴൽ വന്നിട്ടുണ്ടാവുകയില്ല. (ബു,മു,ദ,ന,ജ)', 'سَلَمَةَ بْنِ الْأَكْوَعِ', 'സലമതുബ്നു അക്‌വഅ്(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 367, 367, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 91, 'عَنْ سَلَمَةَ بْنِ الْأَكْوَعِ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا نُصَلِّي مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْجُمُعَةَ، ثُمَّ نَرْجِعُ وَلَيْسَ لِلْحِيطَانِ فَيْءٌ يُسْتَظَلُّ بِهِ. (ن)', 'സലമതുബ്‌നുൽ അഖ്‌വഅ്(റ): ഞങ്ങൾ നബി(സ)യോടൊപ്പം ജുമുഅഃ നിസ്‌കരിക്കും, പിന്നെ മടങ്ങും. ആ സമയം തണൽ കൊള്ളാൻ പോലും നിഴലുണ്ടാവില്ല. (ന)', 'سَلَمَةَ بْنِ الْأَكْوَعِ', 'സലമതുബ്‌നുൽ അഖ്‌വഅ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 368, 368, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 92, 'عَنْ سَهْلِ بْنِ سَعْدٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا نَقِيلُ وَنَتَغَدَّى بَعْدَ الْجُمُعَةِ. (خ, د)', 'സഹ്‌ലുബ്‌നു സഅ്ദ്(റ): ഞങ്ങൾ ആഹാരം കഴിക്കുന്നതും ഉച്ചയുറക്കിലേർപ്പെടുന്നതുമൊക്കെ ജുമുഅക്ക് ശേഷമായിരുന്നു. (ബു,ദ)', 'سَهْلِ بْنِ سَعْدٍ', 'സഹ്‌ലുബ്‌നു സഅ്ദ്(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 368, 368, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 93, 'عَنْ سَعْدِ بْنِ عَائِدٍ رَضِيَ اللهُ عَنْهُ، مُؤَذِّنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُ كَانَ يُؤَذِّنُ يَوْمَ الْجُمُعَةِ عَلَى عَهْدِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا كَانَ الْفَيْءُ مِثْلَ الشِّرَاكِ. [ز: في إسناده راو مجمع على ضعفه] (جه)', 'നബിയുടെ ബാങ്കു വിളിക്കാരനായ സഅ്ദുബ്‌നു ആഇദ്(റ): നിഴൽ ചെരുപ്പിന്റെ വാറ് പോലെയാകുമ്പോൾ നബി(സ)യുടെ കാലത്ത് ജുമുഅഃ ദിവസം അദ്ദേഹം ബാങ്ക് വിളിക്കാറുണ്ടായിരുന്നു. [ദുബ്ബലനാണെന്ന് ഐക്യകണ്ഠേന പറയപ്പെട്ട വ്യക്തി ഇതിന്റെ പരമ്പരയിൽ ഉണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു] (ജ)', 'سَعْدِ بْنِ عَائِدٍ', 'നബിയുടെ ബാങ്കു വിളിക്കാരനായ സഅ്ദുബ്‌നു ആഇദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده راو مجمع على ضعفه', null, 368, 368, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 94, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا نُجَمِّعُ ثُمَّ نَرْجِعُ فَنَقِيلُ. (جه)', 'അനസ്(റ): ഞങ്ങൾ ജുമുഅഃ നിസ്‌കരിച്ച് മടങ്ങി ഉച്ചയുറക്കിലേർപ്പെടുമായിരുന്നു. (ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 368, 368, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 95, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا اشْتَدَّ الْبَرْدُ بَكَّرَ بِالصَّلَاةِ، وَإِذَا اشْتَدَّ الْحَرُّ أَبْرَدَ بِالصَّلَاةِ، يَعْنِي الْجُمُعَةَ. (خ)', 'അനസ്(റ): തണുപ്പ് കഠിനമായാൽ നബി(സ) നേരത്തെ നിസ്‌കരിക്കാറുണ്ടായിരുന്നു. ചൂട് കഠിനമായാൽ, അത് ശമിക്കുന്നതു വരെ നിസ്‌കാരം പിന്തിക്കുകയും ചെയ്തിരുന്നു. ജുമുഅഃ നിസ്‌കാരമാണ് ഇവിടെ ഉദ്ദേശ്യം. (ബു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 368, 368, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 96, 'عَنْ سَهْلِ بْنِ سَعْدٍ رَضِيَ اللهُ عَنْهُ قَالَ: مَا كُنَّا نَقِيلُ وَلَا نَتَغَدَّى إِلَّا بَعْدَ الْجُمُعَةِ. (ق, ت, جه)', 'സഹ്‌ലുബ്‌നു സഅ്ദ്(റ): ജുമുഅഃ നിസ്‌കരിച്ച ശേഷമല്ലാതെ ഞങ്ങൾ ഭക്ഷണം കഴിക്കുകയോ, ഉച്ചയുറക്കം നിർവ്വഹിക്കുകയോ ചെയ്തിരുന്നില്ല. (ബു,മു,തു,ജ)', 'سَهْلِ بْنِ سَعْدٍ', 'സഹ്‌ലുബ്‌നു സഅ്ദ്(റ)', null, null, array['ق','ت','جه']::text[], array['ബു','മു','തു','ജ']::text[], null, null, 368, 368, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 97, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: كُنَّا نُصَلِّي مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْجُمُعَةَ ثُمَّ نَرْجِعُ فَنُرِيحُ نَوَاضِحَنَا، قِيلَ: أَيَّةُ سَاعَةٍ؟ قَالَ: زَوَالَ الشَّمْسِ. (ن)', 'ജാബിറുബ്‌നു അബ്ദില്ല(റ): ഞങ്ങൾ നബി(സ)യോടൊത്ത് ജുമുഅഃ നിസ്‌കരിക്കും. പിന്നെ ഞങ്ങൾ മടങ്ങിച്ചെന്ന് വിശ്രമിക്കും, അദ്ദേഹത്തോട് ചോദിക്കപ്പെട്ടു: ഏതു സമയത്താണു (നിങ്ങൾ അതു) നിർവ്വഹിക്കാറുള്ളത്?. അദ്ദേഹം പറഞ്ഞു: സൂര്യൻ മദ്ധ്യത്തിൽ നിന്ന് തെറ്റിയ ശേഷമാണത്. (ന)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്‌നു അബ്ദില്ല(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 368, 368, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 98, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ الشِّرَاءِ وَالْبَيْعِ فِي الْمَسْجِدِ، وَأَنْ تُنْشَدَ فِيهِ ضَالَّةٌ، وَأَنْ يُنْشَدَ فِيهِ شِعْرٌ، وَنَهَى عَنِ التَّحَلُّقِ قَبْلَ الصَّلَاةِ يَوْمَ الْجُمُعَةِ. (د, ت, ن, جه)', 'അബ്ദുല്ലാഹിബ്‌നു അംറ്(റ): പള്ളിയിൽ വെച്ച് വിൽക്കുന്നതും വാങ്ങുന്നതും, നഷ്ടപ്പെട്ട വസ്തു അന്വേഷിക്കുന്നതും, കവിത ആലപിക്കുന്നതും നബി(സ) നിരോധിച്ചു. വെള്ളിയാഴ്ച നിസ്കാരത്തിനു മുമ്പ് (പള്ളിയിൽ) വട്ടംകൂടിയിരിക്കുന്നതും നിരോധിച്ചു. (ദ,തു,ന,ജ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്‌നു അംറ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 368, 368, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 99, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قَالَ: نَهَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ الاِحْتِبَاءِ يَوْمَ الْجُمُعَةِ، يَعْنِي وَالْإِمَامُ يَخْطُبُ. (جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): വെള്ളിയാഴ്ച (പള്ളിയിൽ) മുട്ടിൻകാലിൽ കോർത്ത് പിടിച്ച് ഇരിക്കൽ നബി(സ) നിരോധിച്ചു. ഇവിടെ ഉദ്ദേശിച്ചത് ഇമാം ഖുത്വുബ നടത്തിക്കൊണ്ടിരിക്കെ(അങ്ങനെ ഇരിക്കുന്നതിനെ)യാണ്. (ജ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 369, 369, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 100, 'عَنْ عَبْدِ اللهِ بْنِ بُسْرٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ جَالِسًا إِلَى جَانِبِهِ يَوْمَ الْجُمُعَةِ، فَجَاءَ رَجُلٌ يَتَخَطَّى رِقَابَ النَّاسِ، فَقَالَ لَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَي اجْلِسْ، فَقَدْ آذَيْتَ". (ن)', 'അബ്ദുല്ലാഹിബ്നു ബുസ്ർ(റ): ഞാൻ വെള്ളിയാഴ്ച ദിവസം നബി(സ)യുടെ ഒരു വശത്തായി ഇരിക്കുകയായിരുന്നു. അപ്പോൾ ഒരാൾ ജനങ്ങളുടെ പിടലി കവച്ചു വെച്ചു കടന്നു വന്നു. അപ്പോൾ നബി(സ) അയാളോട് പറഞ്ഞു: "നീ ഇരിക്കുക, നീ ജനങ്ങളെ ശല്യപ്പെടുത്തിയിരിക്കുന്നു." (ന)', 'عَبْدِ اللهِ بْنِ بُسْرٍ', 'അബ്ദുല്ലാഹിബ്നു ബുസ്ർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 369, 369, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 101, 'عَنْ مُعَاذِ بْنِ أَنَسٍ الْجُهَنِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ تَخَطَّى رِقَابَ النَّاسِ يَوْمَ الْجُمُعَةِ اتَّخَذَ جِسْرًا إِلَى جَهَنَّمَ". (ت,جه)', 'മുആദുബ്നു അനസുൽ ജുഹനിയ്യ്(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും വെള്ളിയാഴ്ച ദിവസം ജനങ്ങളുടെ പിടലികളിലൂടെ കാലെടുത്തുവെച്ചു കടന്നുപോയാൽ അവൻ നരകത്തിലേക്ക് ഒരു പാലം കെട്ടിയിരിക്കുന്നു." (തു,ജ)', 'مُعَاذِ بْنِ أَنَسٍ الْجُهَنِيِّ', 'മുആദുബ്നു അനസുൽ ജുഹനിയ്യ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 369, 369, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 102, 'عَنْ أَبِي الزَّاهِرِيَّةِ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا مَعَ عَبْدِ اللهِ بْنِ بُسْرٍ، صَاحِبِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَوْمَ الْجُمُعَةِ، فَجَاءَ رَجُلٌ يَتَخَطَّى رِقَابَ النَّاسِ، فَقَالَ عَبْدُ اللهِ بْنُ بُسْرٍ: جَاءَ رَجُلٌ يَتَخَطَّى رِقَابَ النَّاسِ يَوْمَ الْجُمُعَةِ وَالنَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ، فَقَالَ لَهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اجْلِسْ، فَقَدْ آذَيْتَ". (د)', 'അബൂസാഹിരിയ്യ(റ): ഞങ്ങൾ വെള്ളിയാഴ്ച ദിവസം നബി(സ)യുടെ കൂട്ടുകാരനായ അബ്ദുല്ലാഹിബ്നു ബുസ്ർ(റ)നോടൊപ്പമായിരുന്നു. അപ്പോൾ ഒരാൾ ജനങ്ങളുടെ പിടലിയിലൂടെ കാലെടുത്തുവെച്ച് കടന്നു വന്നു. അപ്പോൾ അബ്ദുല്ലാഹിബ്നു ബുസ്ർ പറഞ്ഞു: നബി(സ) വെള്ളിയാഴ്ച ദിവസം ഖുതുബ നിർവ്വഹിച്ചു കൊണ്ടിരിക്കെ ഒരാൾ ജനങ്ങളുടെ പിടലിയിലൂടെ കാലെടുത്തുവെച്ച് മുന്നോട്ട് വന്നു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നീ ഇരിക്കുക, നീ ജനങ്ങളെ ശല്യം ചെയ്തിരിക്കുന്നു." (ദ)', 'أَبِي الزَّاهِرِيَّةِ', 'അബൂസാഹിരിയ്യ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 369, 369, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 103, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَجُلًا دَخَلَ الْمَسْجِدَ يَوْمَ الْجُمُعَةِ، وَرَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ، فَجَعَلَ يَتَخَطَّى النَّاسَ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اجْلِسْ، فَقَدْ آذَيْتَ وَآنَيْتَ". (جه)', 'ജാബിറുബ്നു അബ്ദുല്ല(റ): നബി(സ) വെള്ളിയാഴ്ച ഖുത്വുബ നിർവ്വഹിച്ചു കൊണ്ടിരിക്കെ ഒരാൾ പള്ളിയിൽ പ്രവേശിച്ചു. ജനങ്ങളെ ചാടിക്കടന്ന് വരാൻ തുടങ്ങി. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ഇരിക്കുക, നീ ജനങ്ങളെ ബുദ്ധിമുട്ടിക്കുകയും വൈകി വരികയും ചെയ്തിരിക്കുന്നു." (ജ)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദുല്ല(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 369, 369, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 104, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا أَحْدَثَ أَحَدُكُمْ فِي صَلَاتِهِ فَلْيَأْخُذْ بِأَنْفِهِ ثُمَّ لِيَنْصَرِفْ". (د,جه)', 'ആഇശ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾക്കാർക്കെങ്കിലും നിസ്കാരത്തിൽ അശുദ്ധിയുണ്ടായാൽ അവൻ മൂക്കു പിടിച്ച് പിരിഞ്ഞു പോവട്ടെ." (ദ,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 370, 370, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 105, 'عَنِ السَّائِبِ بْنِ يَزِيدَ رَضِيَ اللهُ عَنْهُ: أَنَّ الْأَذَانَ كَانَ أَوَّلَ حِينَ يَجْلِسُ الْإِمَامُ عَلَى الْمِنْبَرِ يَوْمَ الْجُمُعَةِ، فِي عَهْدِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَبِي بَكْرٍ وَعُمَرَ، فَلَمَّا كَانَ فِي خِلَافَةِ عُثْمَانَ وَكَثُرَ النَّاسُ أَمَرَ عُثْمَانُ يَوْمَ الْجُمُعَةِ بِالْأَذَانِ الثَّالِثِ، فَأُذِّنَ بِهِ عَلَى الزَّوْرَاءِ فَثَبَتَ الْأَمْرُ عَلَى ذَلِكَ. (خ,د,ت,ن,جه)', 'സാഇബുബ്നു യസീദ്(റ): നബി(സ)യുടെയും അബൂബക്കറിന്റെയും ഉമറിന്റെയും കാലഘട്ടത്തിൽ വെള്ളിയാഴ്ച ദിവസം ഇമാം മിമ്പറിൽ കയറിയ ഉടനെയായിരുന്നു ആദ്യത്തെ ബാങ്ക് വിളിച്ചിരുന്നത്. ഉസ്മാനി(റ)ന്റെ കാലമായപ്പോൾ ജനങ്ങളുടെ ആധിക്യത്താൽ വെള്ളിയാഴ്ച ദിവസം മൂന്നാമതൊരു ബാങ്ക് വിളിക്കാൻ അദ്ദേഹം കൽപിച്ചു. അത് സൗറാഇന്റെ മുകളിൽ വെച്ചായിരുന്നു. പിന്നീട് അക്കാര്യം അതേ നിലയിൽ തന്നെ തുടർന്നു പോന്നു. (ബു,ദ,തു,ന,ജ)', 'السَّائِبِ بْنِ يَزِيدَ', 'സാഇബുബ്നു യസീദ്(റ)', null, null, array['خ','د','ت','ن','جه']::text[], array['ബു','ദ','തു','ന','ജ']::text[], null, null, 370, 370, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 106, 'عَنِ السَّائِبِ بْنِ يَزِيدَ رَضِيَ اللهُ عَنْهُ قَالَ: إِنَّمَا أَمَرَ بِالتَّأْذِينِ الثَّالِثِ عُثْمَانُ حِينَ كَثُرَ أَهْلُ الْمَدِينَةِ، وَلَمْ يَكُنْ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ غَيْرَ مُؤَذِّنٍ وَاحِدٍ، وَكَانَ التَّأْذِينُ يَوْمَ الْجُمُعَةِ حِينَ يَجْلِسُ الْإِمَامُ. (خ,ن)', 'സാഇബുബ്നു യസീദ്(റ): മദീനക്കാർ വർദ്ധിച്ചപ്പോൾ മൂന്നാമതൊരു ബാങ്കു വിളിക്കാൻ ഉസ്മാൻ(റ) മാത്രമാണ് കൽപിച്ചത്. നബി(സ)യുടെ കാലത്ത് ഒരു ബാങ്കു വിളിക്കാരൻ മാത്രമെ ഉണ്ടായിരുന്നുള്ളൂ. ഇമാം മിമ്പറിൽ ഇരുന്ന ഉടനെയായിരുന്നു വെള്ളിയാഴ്ച ദിവസം ബാങ്കു വിളിച്ചിരുന്നത്. (ബു,ന)', 'السَّائِبِ بْنِ يَزِيدَ', 'സാഇബുബ്നു യസീദ്(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 370, 370, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 107, 'عَنِ السَّائِبِ بْنِ يَزِيدَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ بِلَالٌ يُؤَذِّنُ إِذَا جَلَسَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى الْمِنْبَرِ يَوْمَ الْجُمُعَةِ، فَإِذَا نَزَلَ أَقَامَ. ثُمَّ كَانَ كَذَلِكَ فِي زَمَنِ أَبِي بَكْرٍ وَعُمَرَ رَضِيَ اللهُ عَنْهُمَا. (ن)', 'സാഇബുബ്നു യസീദ്(റ): വെള്ളിയാഴ്ച ദിവസം നബി(സ) മിമ്പറിൽ ഇരുന്ന ഉടനെയായിരുന്നു ബിലാൽ ബാങ്കു വിളിച്ചിരുന്നത്. നബി(സ) മിമ്പറിൽ നിന്ന് ഇറങ്ങിയാൽ അദ്ദേഹം (ബിലാൽ) ഇഖാമത്ത് വിളിക്കും. ഇപ്രകാരം തന്നെ അബൂബക്കറി(റ)ന്റെയും ഉമറി(റ)ന്റെയും കാലഘട്ടത്തിലും തുടർന്നു. (ന)', 'السَّائِبِ بْنِ يَزِيدَ', 'സാഇബുബ്നു യസീദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 370, 370, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 108, 'عَنْ مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ رَضِيَ اللهُ عَنْهُ:أَنَّهُ جَالِسٌ عَلَى الْمِنْبَرِ يَوْمَ الْجُمُعَةِ، فَلَمَّا أَذَّنَ الْمُؤَذِّنُ،قَالَ: اللهُ أَكْبَرُ اللهُ أَكْبَرُ قَالَ مُعَاوِيَةُ: اللهُ أَكْبَرُ اللهُ أَكْبَرُ قَالَ: أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ. فَقَالَ مُعَاوِيَةُ: وَأَنَا، فَقَالَ: أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللهِ. فَقَالَ مُعَاوِيَةُ: وَأَنَا، فَلَمَّا أَنْ قَضَى التَّأْذِينَ، قَالَ: يَا أَيُّهَا النَّاسُ ،إِنِّي سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى هَذَا الْمَجْلِسِ، حِينَ أَذَّنَ الْمُؤَذِّنُ، يَقُولُ مَا سَمِعْتُمْ مِنِّي مِنْ مَقَالَتِي. (خ)', 'മുആവിയതുബ്നു അബൂസുഫ്യാൻ(റ): അദ്ദേഹം ഒരു വെള്ളിയാഴ്ച ദിവസം മിമ്പറിൽ കയറിയിരിക്കെ ബാങ്കു വിളിക്കുന്നവൻ ബാങ്കു വിളിക്കാൻ തുടങ്ങി. അവൻ ''അല്ലാഹു അക്ബർ..'' എന്നു പറഞ്ഞു. മുആവിയ(റ)യും ''അല്ലാഹു അക്ബർ.'' എന്ന് പറഞ്ഞു. മുഅദ്ദിൻ ''അശ്ഹദു അൻ ലാഇലാഹ ഇല്ലല്ലാഹു..'' എന്നു പറഞ്ഞപ്പോൾ മുആവിയ(റ) ''ഞാനും'' എന്നും, ബാങ്കുവിളിക്കുന്നവൻ ''അശ്ഹദു അന്ന മുഹമ്മദൻ റസൂലുല്ലാഹി'' എന്നു പറഞ്ഞപ്പോൾ മുആവിയ(റ) ''ഞാനും'' എന്നും, പറഞ്ഞു. ബാങ്ക് വിളിച്ചു കഴിഞ്ഞപ്പോൾ അദ്ദേഹം പറഞ്ഞു: ജനങ്ങളെ, റസൂൽ(സ) ഇതേ സ്ഥാനത്തിരിക്കുമ്പോൾ ബാങ്കു വിളിച്ച സന്ദർഭത്തിൽ ഞാൻ പറയുന്നതായി (എന്നിൽ നിന്ന്) നിങ്ങൾ കേട്ട പ്രകാരം (നബി) പറയുന്നത് ഞാൻ കേട്ടു. (ബു)', 'مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ', 'മുആവിയതുബ്നു അബൂസുഫ്യാൻ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 370, 370, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 109, 'عَنِ السَّائِبِ بْنِ يَزِيدَ رَضِيَ اللهُ عَنْهُ قَالَ: مَا كَانَ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِلَّا مُؤَذِّنٌ وَاحِدٌ، إِذَا خَرَجَ أَذَّنَ، وَإِذَا نَزَلَ أَقَامَ. وَأَبُو بَكْرٍ وَعُمَرُ كَذَلِكَ، فَلَمَّا كَانَ عُثْمَانُ، وَكَثُرَ النَّاسُ، زَادَ النِّدَاءَ الثَّالِثَ عَلَى دَارٍ فِي السُّوقِ يُقَالُ لَهَا:''الزَّوْرَاءُ'' فَإِذَا خَرَجَ أَذَّنَ، وَإِذَا نَزَلَ أَقَامَ. (جه)', 'സാഇബുബ്നു യസീദ്(റ): നബി(സ)ക്ക് ഒരു ബാങ്കുവിളിക്കാരൻ മാത്രമേ ഉണ്ടായിരുന്നുള്ളൂ. റസൂൽ(സ) മിമ്പറിലേക്ക് പുറപ്പെട്ടാൽ അയാൾ ബാങ്കു വിളിക്കും. നബി(സ) ഇറങ്ങിയാൽ നിസ്കാരത്തിന് നിൽക്കും. അബൂബക്കർ, ഉമർ(റ) എന്നിവരുടെ കാലത്തും ഇപ്രകാരം തന്നെയായിരുന്നു. ഉസ്മാൻ(റ) കാലഘട്ടത്തിൽ ജനങ്ങൾ അധികരിച്ചപ്പോൾ ''സൗറാഅ്'' എന്ന് വിളിക്കുന്ന അങ്ങാടിയിലെ ഒരു വീട്ടിൽ വെച്ച് മൂന്നാമതൊരു ബാങ്ക് അധികരിപ്പിച്ചു. ഇമാം മിമ്പറിലേക്ക് പുറപ്പെടുമ്പോൾ ബാങ്ക് വിളിക്കും. മിമ്പറിൽ നിന്ന് അദ്ദേഹം ഇറങ്ങിയാൽ ഇഖാമത്തും. (ജ)', 'السَّائِبِ بْنِ يَزِيدَ', 'സാഇബുബ്നു യസീദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 371, 371, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 110, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: بَيْنَا النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ يَوْمَ الْجُمُعَةِ إِذْ جَاءَ رَجُلٌ، فَقَالَ لَهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "صَلَّيْتَ". قَالَ: لَا. قَالَ: "قُمْ فَارْكَعْ". (ت,ن,جه)', 'ജാബിറുബ്നു അബ്ദുല്ല(റ): നബി(സ) വെള്ളിയാഴ്ച ദിവസം ഖുത്വുബ നിർവ്വഹിച്ചു കൊണ്ടിരിക്കെ ഒരാൾ കടന്നുവന്നു. അപ്പോൾ നബി(സ) ചോദിച്ചു: "നീ (തഹിയ്യത്ത്) നിസ്കരിച്ചുവോ?" അദ്ദേഹം പറഞ്ഞു: ഇല്ല, നബി(സ) പറഞ്ഞു: "എഴുന്നേറ്റ് നിസ്കരിക്കുക." (തു,ന,ജ)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദുല്ല(റ)', null, null, array['ت','ن','جه']::text[], array['തു','ന','ജ']::text[], null, null, 371, 371, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 111, 'عَنْ أَبِي بَكْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: لَقَدْ رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى الْمِنْبَرِ، وَالْحَسَنُ مَعَهُ، وَهُوَ يُقْبِلُ عَلَى النَّاسِ مَرَّةً وَعَلَيْهِ مَرَّةً، وَيَقُولُ: "إِنَّ ابْنِي هَذَا سَيِّدٌ، وَلَعَلَّ اللهَ أَنْ يُصْلِحَ بِهِ بَيْنَ فِئَتَيْنِ مِنَ الْمُسْلِمِينَ عَظِيمَتَيْنِ". (ن)', 'അബൂബക്റ(റ): ഞാൻ റസൂൽ(സ) മിമ്പറിൽ നിൽക്കുന്നതായി കണ്ടു. ഹസൻ(റ)വും അവിടത്തോടൊപ്പമുണ്ട്. അവിടുന്ന് ഒരിക്കൽ ജനങ്ങളുടെ നേരെയും മറ്റൊരിക്കൽ ഹസൻ(റ)വിന്റെ നേരെയും തിരിഞ്ഞുകൊണ്ട് പറഞ്ഞു: "എന്റെ മകൻ (നിങ്ങളുടെ) നേതാവാണ്. അവൻ മുഖേന മുസ്ലിംകളുടെ വലിയ രണ്ടു വിഭാഗത്തിനിടയിൽ അല്ലാഹു യോജിപ്പുണ്ടാക്കിയേക്കാം." (ന)', 'أَبِي بَكْرَةَ', 'അബൂബക്റ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 371, 371, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 112, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُ قَالَ: جَاءَ سُلَيْكٌ الْغَطَفَانِيُّ يَوْمَ الْجُمُعَةِ، وَرَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَاعِدٌ عَلَى الْمِنْبَرِ، فَقَعَدَ سُلَيْكٌ قَبْلَ أَنْ يُصَلِّيَ، فَقَالَ لَهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَرَكَعْتَ رَكْعَتَيْنِ". قَالَ:لَا، قَالَ: "قُمْ فَارْكَعْهُمَا". (م,جه)', 'ജാബിറുബ്നു അബ്ദുല്ല(റ): വെള്ളിയാഴ്ച ദിവസം നബി(സ) മിമ്പറിലിരിക്കുമ്പോൾ സുലൈഖുൽ ഗത്വഫാനീ വന്ന് നിസ്കരിക്കുന്നതിനു മുമ്പു തന്നെ ഇരുന്നു. അപ്പോൾ റസൂൽ(സ) ചോദിച്ചു: "നീ രണ്ട് റക്അത്ത് നിസ്കരിച്ചോ?" അദ്ദേഹം പറഞ്ഞു: ഇല്ല, നബി(സ) പറഞ്ഞു: "എഴുന്നേറ്റ് അവ രണ്ടും നിർവ്വഹിക്കുക." (മു,ജ)', 'جَابِرٍ', 'ജാബിറുബ്നു അബ്ദുല്ല(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 371, 371, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 113, 'عَنْ أَبِي هُرَيْرَةَ وَجَابِرٍ رَضِيَ اللهُ عَنْهُمَا قَالَا: جَاءَ سُلَيْكٌ الْغَطَفَانِيُّ وَرَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ، فَقَالَ لَهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَصَلَّيْتَ رَكْعَتَيْنِ قَبْلَ أَنْ تَجِيءَ؟" قَالَ: لَا، قَالَ: "فَصَلِّ رَكْعَتَيْنِ وَتَجَوَّزْ فِيهِمَا". (م,د,جه)', 'അബൂഹുറൈറ, ജാബിർ(റ): നബി(സ) ഖുത്വുബ നടത്തികൊണ്ടിരിക്കെ സുലൈഖുൽ ഗത്വഫാനി വന്നു. അദ്ദേഹത്തോട് നബി(സ) ചോദിച്ചു: "നീ വരുന്നതിനു മുമ്പ് രണ്ട് റക്അത്ത് നിസ്കരിച്ചോ?" അദ്ദേഹം പറഞ്ഞു: ഇല്ല, റസൂൽ(സ) പറഞ്ഞു: "രണ്ട് റക്ത്തുകൾ നിസ്കരിക്കുക, അവ രണ്ടും ലഘുവായി നിർവ്വഹിക്കുകയും ചെയ്യുക." (മു,ദ,ജ)', 'أَبِي هُرَيْرَةَ وَجَابِرٍ', 'അബൂഹുറൈറ, ജാബിർ(റ)', null, null, array['م','د','جه']::text[], array['മു','ദ','ജ']::text[], null, null, 371, 372, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 114, 'عَنْ عِيَاضِ بْنِ عَبْدِ اللهِ بْنِ أَبِي سَرْحٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ أَبَا سَعِيدٍ الْخُدْرِيَّ دَخَلَ يَوْمَ الْجُمُعَةِ وَمَرْوَانُ يَخْطُبُ، فَقَامَ يُصَلِّي فَجَاءَ الْحَرَسُ لِيُجْلِسُوهُ، فَأَبَى حَتَّى صَلَّى، فَلَمَّا انْصَرَفَ أَتَيْنَاهُ فَقُلْنَا: رَحِمَكَ اللهُ، إِنْ كَادُوا لَيَقَعُوا بِكَ! فَقَالَ:مَا كُنْتُ لِأَتْرُكَهُمَا بَعْدَ شَيْءٍ رَأَيْتُهُ مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ،ثُمَّ ذَكَرَ أَنَّ رَجُلًا جَاءَ يَوْمَ الْجُمُعَةِ فِي هَيْئَةٍ بَذَّةٍ، وَالنَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ يَوْمَ الْجُمُعَةِ،فَأَمَرَهُ فَصَلَّى رَكْعَتَيْنِ ،وَالنَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ.حَسن صحيح. (ت)', 'ഇയാദിബ്നു അബ്ദുല്ലാഹിബ്നു അബൂസർഹ്(റ): അബൂസഈദിൽ ഖുദ്രി(റ) വെള്ളിയാഴ്ച ദിവസം മർവാൻ ഖുതുബ നടത്തി കൊണ്ടിരിക്കെ കടന്നുവന്നു. എന്നിട്ട് എഴുന്നേറ്റു നിന്ന് നിസ്കരിച്ചു. അപ്പോൾ അംഗരക്ഷകർ അദ്ദേഹത്തെ ഇരുത്താൻ വന്നു. ഇരിക്കാൻ വിസമ്മതിച്ച അദ്ദേഹം നിസ്കരിച്ചു. ജുമുഅഃ പിരിഞ്ഞശേഷം ഞങ്ങൾ അദ്ദേഹത്തിനടുത്ത് ചെന്ന് പറഞ്ഞു: അല്ലാഹു നിങ്ങളെ അനുഗ്രഹിക്കട്ടെ, അവർക്ക് ന്യായമെങ്കിൽ നിങ്ങളെ കുറ്റപ്പെടുത്തുമായിരുന്നു. അദ്ദേഹം പറഞ്ഞു: നബി(സ)യിൽ നിന്ന് കണ്ട ശേഷം ഞാൻ അവ (രണ്ട് റക്അത്ത്) ഉപേക്ഷിക്കാറില്ല. പിന്നെ പറഞ്ഞു: ജുമുഅഃ ദിവസം നബി(സ) ഖുത്വുബ നടത്തിക്കൊണ്ടിരിക്കെ ഒരാൾ വന്നു. അദ്ദേഹത്തോട് റസൂൽ (നിസ്കരിക്കാൻ) കൽപിച്ചു. നബി(സ) ഖുത്വുബ നടത്തിക്കൊണ്ടിരിക്കെത്തന്നെ അദ്ദേഹം രണ്ട് റക്അത്ത് നിസ്ക്കരിച്ചു. [ഹദീസ് ഹസനും സഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു] (തു)', 'عِيَاضِ بْنِ عَبْدِ اللهِ بْنِ أَبِي سَرْحٍ', 'ഇയാദിബ്നു അബ്ദുല്ലാഹിബ്നു അബൂസർഹ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 372, 372, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 115, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا يَقُولُ: إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا جَاءَ أَحَدُكُمْ وَقَدْ خَرَجَ الْإِمَامُ فَلْيُصَلِّ رَكْعَتَيْنِ". قَالَ شُعْبَةُ: يَوْمَ الْجُمُعَةِ. (ن)', 'ജാബിറുബ്നു അബ്ദുല്ല(റ): നബി(സ) പറഞ്ഞു: "ഇമാം (ജുമുഅ ദിവസത്തിൽ) മിമ്പറിൽ കയറിയിരിക്കെ, നിങ്ങളിലാരെങ്കിലും വന്നാൽ, അവൻ രണ്ട് റക്അത്ത് നിസ്കരിക്കട്ടെ." ശുഅ്ബ പറഞ്ഞു: ഇവിടെ ജുമുഅഃ ദിവസമാണുദ്ദേശ്യം. (ന)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദുല്ല(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 372, 372, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 116, 'عَنْ جَابِرِ بْنِ عَبْدِاللهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: جَاءَ رَجُلٌ وَالنَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ النَّاسَ يَوْمَ الْجُمُعَةِ، فَقَالَ: "أَصَلَّيْتَ يَا فُلَانُ؟" قَالَ: لَا، قَالَ: "قُمْ فَارْكَعْ رَكْعَتَيْنِ". (خ)', 'ജാബിറുബ്നു അബ്ദുല്ല(റ): നബി(സ) ജുമുഅഃ ദിവസം ജനങ്ങളോട് ഖുത്വുബ നടത്തിക്കൊണ്ടിരിക്കെ ഒരാൾ വന്നു. അപ്പോൾ നബി(സ) ചോദിച്ചു; "ഹേ മനുഷ്യാ! നീ നിസ്കരിച്ചുവോ?" അയാൾ പറഞ്ഞു: ഇല്ല, നബി(സ) പറഞ്ഞു: "എഴുന്നേറ്റ് രണ്ട് റക്അത്ത് നിസ്കരിക്കുക." (ബു)', 'جَابِرِ بْنِ عَبْدِاللهِ', 'ജാബിറുബ്നു അബ്ദുല്ല(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 372, 372, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 117, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَرْكَعُ قَبْلَ الْجُمُعَةِ أَرْبَعًا، لَا يَفْصِلُ فِي شَيْءٍ مِنْهُنَّ .[ز: في إسناده مسلسل بالضعفاء] (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) ജുമുഅക്കു മുൻപ് നാലു റക്അത്ത് നിസ്കരിക്കാറുണ്ടായിരുന്നു. അവക്കിടയിൽ വേർതിരിക്കാറില്ല. [ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലരായ റപ്പോർട്ടർമാരുണ്ടെന്ന് ഇബ്നുമാജ] (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده مسلسل بالضعفاء', null, 372, 372, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 118, 'عَنْ سَمُرَةَ بْنِ جُنْدُبٍ رَضِيَ اللهُ عَنْهُ: أَنَّ نَبِيَّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "احْضُرُوا الذِّكْرَ وَادْنُوا مِنَ الْإِمَامِ، فَإِنَّ الرَّجُلَ لَا يَزَالُ يَتَبَاعَدُ حَتَّى يُؤَخَّرَ فِي الْجَنَّةِ وَإِنْ دَخَلَهَا". (د)', 'സമുറ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ ദിക്റുകളിൽ പങ്കെടുക്കുക, ഇമാമിനോടടുത്ത് നിൽക്കുക. കാരണം പിന്നിലാകുന്നവൻ സ്വർഗ്ഗത്തിലും പിന്തിക്കപ്പെടും. അവൻ അതിൽ പ്രവേശിച്ചാലും." (ദ)', 'سَمُرَةَ بْنِ جُنْدُبٍ', 'സമുറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 372, 373, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 119, 'عَنْ أَوْسِ بْنِ أَوْسٍ الثَّقَفِيِّ رَضِيَ اللهُ عَنْهُمَا قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ غَسَّلَ يَوْمَ الْجُمُعَةِ وَاغْتَسَلَ، وَبَكَّرَ وَابْتَكَرَ، وَمَشَى وَلَمْ يَرْكَبْ، وَدَنَا مِنَ الْإِمَامِ، فَاسْتَمَعَ وَلَمْ يَلْغُ، كَانَ لَهُ بِكُلِّ خَطْوَةٍ عَمَلُ سَنَةٍ، أَجْرُ صِيَامِهَا وَقِيَامِهَا". (د,ت,ن,جه)', 'ഔസുബ്നു ഔസ്(റ): നബി(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "ഒരാൾ വെള്ളിയാഴ്ച നന്നായി കുളിക്കുകയും വളരെ നേരത്തെ വാഹനത്തിൽ യാത്ര ചെയ്യാതെ നടന്നുകൊണ്ടു തന്നെ ജുമുഅക്ക് പോവുകയും ഇമാമിനടുത്ത് ചെന്നിരുന്ന് ഖുത്വുബ ശ്രദ്ധിക്കുകയും വ്യർത്ഥവാക്കുകൾ പറയാതെ മൗനം ദീക്ഷിക്കുകയും ചെയ്താൽ അവന്റെ ഓരോ കാലടികൾക്കും പകരമായി ഒരു വർഷത്തെ സൽകർമ്മം രേഖപ്പെടുത്തപ്പെടും. അഥവാ, അതിലെ നിസ്കാരത്തിന്റെയും നോമ്പിന്റെയും പ്രതിഫലം." (ദ,തു,ന,ജ)', 'أَوْسِ بْنِ أَوْسٍ الثَّقَفِيِّ', 'ഔസുബ്നു ഔസ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 373, 373, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 120, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا قُلْتَ لِصَاحِبِكَ أَنْصِتْ يَوْمَ الْجُمُعَةِ، وَالْإِمَامُ يَخْطُبُ، فَقَدْ لَغَوْتَ". (م,د,ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "വെള്ളിയാഴ്ച ദിവസം ഇമാം ഖുത്വുബ നടത്തിക്കൊണ്ടിരിക്കെ നീ നിന്റെ കൂട്ടുകാരനോട് മിണ്ടാതിരിക്ക് എന്ന് പറഞ്ഞാൽ നീ (ഖുതുബയിൽ) അനാവശ്യം പ്രവർത്തിച്ചു." (മു,ദ,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 373, 373, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 121, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنِ اغْتَسَلَ ثُمَّ أَتَى الْجُمُعَةَ، فَصَلَّى مَا قُدِّرَ لَهُ، ثُمَّ أَنْصَتَ حَتَّى يَفْرُغَ مِنْ خُطْبَتِهِ، ثُمَّ يُصَلِّي مَعَهُ، غُفِرَ لَهُ مَا بَيْنَهُ وَبَيْنَ الْجُمُعَةِ الْأُخْرَى، وَفَضْلُ ثَلَاثَةِ أَيَّامٍ". (م,ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും കുളിക്കുകയും പിന്നെ ജുമുഅക്ക് വരികയും അവനോട് കൽപിക്കപ്പെട്ടത് നിസ്കരിക്കുകയും, പിന്നെ ഖുത്വുബ തീരുന്നതുവരെ വിട്ടുപോവാതെ നിശ്ശബ്ദത പാലിക്കുകയും പിന്നെ അവനോടൊപ്പം (ഇമാമിനോടൊപ്പം) നിസ്കരിക്കുകയും ചെയ്താൽ അവന് ഒരു ജുമുഅഃ മുതൽ അടുത്ത ജുമുഅഃ വരെയും തുടർന്നുള്ള മൂന്നു ദിവസത്തെയും പാപങ്ങൾ പൊറുക്കപ്പെടുന്നതാണ്." (മു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 373, 373, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 122, 'عَنْ أُبَيِّ بْنِ كَعْبٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَرَأَ يَوْمَ الْجُمُعَةِ: {تَبَارَكَ} وَهُوَ قَائِمٌ، فَذَكَّرَنَا بِأَيَّامِ اللهِ، وَأَبُو الدَّرْدَاءِ أَوْ أَبُو ذَرٍّ يَغْمِزُنِي، فَقَالَ: مَتَى أُنْزِلَتْ هَذِهِ السُّورَةُ؟ إِنِّي لَمْ أَسْمَعْهَا إِلَّا الْآنَ، فَأَشَارَ إِلَيْهِ: أَنِ اسْكُتْ، فَلَمَّا انْصَرَفُوا قَالَ: سَأَلْتُكَ مَتَى أُنْزِلَتْ هَذِهِ السُّورَةُ، فَلَمْ تُخْبِرْنِي؟ فَقَالَ أُبَيٌّ: لَيْسَ لَكَ مِنْ صَلَاتِكَ الْيَوْمَ إِلَّا مَا لَغَوْتَ. فَذَهَبَ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَذَكَرَ ذَلِكَ لَهُ، وَأَخْبَرَهُ بِالَّذِي قَالَ أُبَيٌّ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "صَدَقَ أُبَيٌّ". (جه)', 'ഉബയ്യുബ്നു കഅ്ബ്(റ): നബി(സ) ജുമുഅഃ ദിവസം നിർത്തത്തിൽ ''തബാറക......'' എന്ന സൂറത്ത് ഓതി. അല്ലാഹുവിന്റെ ദിവസങ്ങളെ ഓർമ്മിപ്പിച്ചു. അപ്പോൾ അബൂദർദാഅ് - അല്ലെങ്കിൽ അബൂദർറ് - എന്നെ പിച്ചി എന്നിട്ടു ചോദിച്ചു: ഈ സൂറത്ത് എപ്പോഴാണ് ഇറങ്ങിയത്? ഞാൻ ആദ്യമായി ഇപ്പോഴാണിത് കേൾക്കുന്നത്. അപ്പോൾ അദ്ദേഹത്തോട് മിണ്ടാതിരിക്കാൻ ആംഗ്യം കാണിച്ചു. അതിൽനിന്ന് (ജുമുഅഃ) പിരിഞ്ഞപ്പോൾ അദ്ദേഹം എന്നോട് പറഞ്ഞു: ഞാൻ നിന്നോട് ''ഈ സൂറത്തിറങ്ങിയത് എപ്പോഴാണ്?'' എന്ന് ചോദിച്ചപ്പോൾ എന്തുകൊണ്ട് നീയത് അറിയിച്ചില്ല? അപ്പോൾ ഉബയ്യ് പറഞ്ഞു: ഇന്നത്തെ നിസ്കാരത്തിൽ നീ ചെയ്ത അനാവശ്യ പ്രവർത്തികളല്ലാതെ മറ്റൊന്നും നിനക്കില്ല. അദ്ദേഹം നബി(സ)യുടെ അടുത്തുചെന്ന് ഈ സംഭവം പറയുകയും, ഉബയ്യ് ഇപ്രകാരം പറഞ്ഞു എന്ന് പറയുകയും ചെയ്തു. നബി(സ) പറഞ്ഞു: "ഉബയ്യ് സത്യം പറഞ്ഞിരിക്കുന്നു." (ജ)', 'أُبَيِّ بْنِ كَعْبٍ', 'ഉബയ്യുബ്നു കഅ്ബ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 373, 374, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 123, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا نَعَسَ أَحَدُكُمْ يَوْمَ الْجُمُعَةِ، فَلْيَتَحَوَّلْ مِنْ مَجْلِسِهِ ذَلِكَ" حَسن صحيح. (د,ت)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിലാർക്കെങ്കിലും വെള്ളിയാഴ്ച ദിവസം മയക്കം വന്നാൽ അവൻ തന്റെ ഇരിപ്പിടം മാറിയിരിക്കട്ടെ." (ഹദീസ് ഹസനും സഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു) (ദ,തു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 374, 374, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 124, 'عَنْ عَدِيِّ بْنِ ثَابِتٍ، عَنْ أَبِيهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ- إِذَا قَامَ عَلَى الْمِنْبَرِ - اسْتَقْبَلَهُ أَصْحَابُهُ بِوُجُوهِهِمْ. (جه)', 'അദിയ്യ്ബ്നു സാബിത്(റ) അദ്ദേഹം തന്റെ പിതാവിൽ നിന്ന്: നബി(സ) മിമ്പറിൽ നിൽക്കുമ്പോൾ സ്വഹാബികൾ അവിടുത്തേക്കഭിമുഖമായി നിൽക്കാറുണ്ടായിരുന്നു. (ജ)', 'عَدِيِّ بْنِ ثَابِتٍ، عَنْ أَبِيهِ', 'അദിയ്യ്ബ്നു സാബിത്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 374, 374, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 125, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا اسْتَوَى عَلَى الْمِنْبَرِ اسْتَقْبَلْنَاهُ بِوُجُوهِنَا. (ت)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): നബി(സ) മിമ്പറിൽ നിൽക്കുമ്പോൾ ഞങ്ങൾ അവിടുത്തേക്കഭിമുഖമായി ഇരിക്കാറുണ്ടായിരുന്നു. (തു)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 374, 374, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 126, 'عَنْ مُعَاذِ بْنِ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ الْحُبْوَةِ يَوْمَ الْجُمُعَةِ وَالْإِمَامُ يَخْطُبُ. (د,ت)', 'മുആദുബ്നു അനസ്(റ): വെള്ളിയാഴ്ച ഇമാം പ്രസംഗിച്ചു കൊണ്ടിരിക്കെ മുട്ട് കെട്ടിയിരിക്കുന്നത് നബി(സ) വിലക്കിയിരിക്കുന്നു. (ദ,തു)', 'مُعَاذِ بْنِ أَنَسٍ', 'മുആദുബ്നു അനസ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 374, 374, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 127, 'عَنْ يَعْلَى بْنِ شَدَّادِ بْنِ أَوْسٍ رَضِيَ اللهُ عَنْهُ قَالَ: شَهِدْتُ مَعَ مُعَاوِيَةَ بَيْتَ الْمَقْدِسِ، فَجَمَّعَ بِنَا، فَنَظَرْتُ فَإِذَا جُلُّ مَنْ فِي الْمَسْجِدِ أَصْحَابُ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَرَأَيْتُهُمْ مُحْتَبِينَ وَالْإِمَامُ يَخْطُبُ. (د)', 'യഅ്ലബ്നു ശദാദുബ്നു ഔസ്(റ): ഞാൻ മുആവിയ(റ)യോടൊപ്പം ബൈതുൽ മുഖദ്ദിസിൽ പോയി. അദ്ദേഹം ഞങ്ങൾക്കിമാമായി. ഞാൻ നോക്കിയപ്പോൾ പള്ളിയിലുള്ളവരിലധികവും നബി(സ)യുടെ സ്വഹാബികളായിരുന്നു. അവർ ഇമാം പ്രസംഗിച്ചു കൊണ്ടിരിക്കെ മുട്ട് കെട്ടിയിരിക്കുന്നത് ഞാൻ കണ്ടു. (ദ)', 'يَعْلَى بْنِ شَدَّادِ بْنِ أَوْسٍ', 'യഅ്ലബ്നു ശദാദുബ്നു ഔസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 374, 374, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 128, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَخْطُبُ قَائِمًا يَوْمَ الْجُمُعَةِ، فَجَاءَتْ عِيرٌ مِنَ الشَّامِ، فَانْفَتَلَ النَّاسُ إِلَيْهَا، حَتَّى لَمْ يَبْقَ إِلَّا اثْنَا عَشَرَ رَجُلًا، فَأُنْزِلَتْ هَذِهِ الْآيَةُ الَّتِي فِي الْجُمُعَةِ:{وَإِذَا رَأَوْا تِجَارَةً أَوْ لَهْوًا انْفَضُّوا إِلَيْهَا وَتَرَكُوكَ قَائِمًا} الْآيَةَ. (ق)', 'ജാബിറുബ്നു അബ്ദുല്ല(റ): വെള്ളിയാഴ്ച ദിവസം നബി(സ) നിന്നു കൊണ്ട് ഖുത്വുബ നിർവ്വഹിച്ചു കൊണ്ടിരിക്കെ ശാമിൽ നിന്നും ഒരു കച്ചവട സംഘം വന്നപ്പോൾ ജനങ്ങളെല്ലാം അതിലേക്ക് ഇറങ്ങിപ്പോയി. പന്ത്രണ്ടു പേർ മാത്രമേ ബാക്കിയുണ്ടായിരുന്നുള്ളൂ. അപ്പോൾ സൂറത്തുജുമുഅയിലെ ഈ ആയത്തിറങ്ങി: ''അവർ കച്ചവടമോ വിനോദമോ കണ്ടാൽ അവയുടെ അടുത്തേക്ക് പിരിഞ്ഞു പോകുകയും നിന്ന നിൽപിൽ നിന്നെ വിട്ടേക്കുകയും ചെയ്യുന്നതാണ്.'' (ബു,മു)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദുല്ല(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 375, 375, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 129, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: صَعِدَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْمِنْبَرَ، وَكَانَ آخِرَ مَجْلِسٍ جَلَسَهُ، مُتَعَطِّفًا مِلْحَفَةً عَلَى مَنْكِبَيْهِ، قَدْ عَصَبَ رَأْسَهُ بِعِصَابَةٍ دَسِمَةٍ، فَحَمِدَ اللهَ وَأَثْنَى عَلَيْهِ، ثُمَّ قَالَ: "أَيُّهَا النَّاسُ إِلَيَّ". فَثَابُوا إِلَيْهِ، ثُمَّ قَالَ: "أَمَّا بَعْدُ، فَإِنَّ هَذَا الْحَيَّ مِنَ الْأَنْصَارِ، يَقِلُّونَ وَيَكْثُرُ النَّاسُ، فَمَنْ وَلِيَ شَيْئًا مِنْ أُمَّةِ مُحَمَّدٍ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَاسْتَطَاعَ أَنْ يَضُرَّ فِيهِ أَحَدًا أَوْ يَنْفَعَ فِيهِ أَحَدًا، فَلْيَقْبَلْ مِنْ مُحْسِنِهِمْ وَيَتَجَاوَزْ عَنْ مُسِيِّهِمْ". (خ)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) മിമ്പറിൽ കയറി. തിരുമേനി(സ) മിമ്പറിൽ ഇരുന്ന അവസാനത്തെ ഇരുത്തമായിരുന്നു അത്. രണ്ടു ചുമലുകളും ഒരു പുതപ്പുകൊണ്ട് മൂടിപ്പുതച്ചു കൊണ്ടാണ് നബി(സ) മിമ്പറിൽ കയറിയത്. കറുത്ത തുണിക്കഷ്ണം തലക്ക് കെട്ടിയിട്ടുണ്ടായിരുന്നു. നബി(സ) അല്ലാഹുവിനെ സ്തുതിക്കുകയും അവന്റെ മഹത്വത്തെ പ്രകീർത്തിക്കുകയും ചെയ്തു. അനന്തരം നബി(സ) പറഞ്ഞു: "ജനങ്ങളേ, എന്നിലേക്ക് അടുത്തിരിക്കുക." അപ്പോൾ അവരെല്ലാം നബി(സ)യുടെ അടുത്തേക്കിരുന്നു. നബി(സ) പറഞ്ഞു: "അൻസാരികളായ ഈ ഗോത്രക്കാർ ഭാവിയിൽ ന്യൂനപക്ഷമായിക്കൊണ്ടാണ് വരിക, മറ്റുള്ളവർ വർദ്ധിച്ചു കൊണ്ടുമിരിക്കും. അതുകൊണ്ട് മുഹമ്മദിന്റെ സമുദായത്തിന്റെ ഭരണകാര്യങ്ങൾ വല്ലവനും ഏറ്റെടുത്തു, എന്നിട്ട് ആ സ്ഥാനത്തിരുന്നുകൊണ്ട് വല്ലവനും ഉപകാരം ചെയ്യാനോ ഉപദ്രവിക്കാനോ അവന് അവസരം ലഭിച്ചുവെങ്കിൽ (അവൻ കൈക്കൊള്ളേണ്ട നയം ഇതായിരിക്കണം) നന്മ ചെയ്യുന്നവന്റെ നന്മയെ അവൻ സ്വീകരിക്കട്ടെ, തിന്മ ചെയ്യുന്നവരുടെ തിന്മ മാപ്പു ചെയ്ത് വിടുകയും ചെയ്യട്ടെ." (ബു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 375, 375, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 130, 'عَنْ كَعْبِ بْنِ عُجْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: دَخَلَ الْمَسْجِدَ وَعَبْدُ الرَّحْمَنِ ابْنُ أُمِّ الْحَكَمِ يَخْطُبُ قَاعِدًا، فَقَالَ: انْظُرُوا إِلَى هَذَا يَخْطُبُ قَاعِدًا، وَقَدْ قَالَ اللهُ عَزَّ وَجَلَّ:{وَإِذَا رَأَوْا تِجَارَةً أَوْ لَهْوًا انْفَضُّوا إِلَيْهَا وَتَرَكُوكَ قَائِمًا} [الجمعة:١١] (ن)', 'കഅ്ബ്ബ്നു ഉജ്റത്(റ): അബ്ദുറഹ്മാനുബ്നുൽ ഉമ്മുൽ ഹകമ് ഇരുന്ന് ഖുത്വുബ നിർവ്വഹിച്ചു ക്കൊണ്ടിരിക്കെ അദ്ദേഹം (കഅ്ബ്) പള്ളിയിൽ പ്രവേശിച്ചു. ഉടൻ ഇങ്ങനെ പറഞ്ഞു: നോക്കൂ, ഇയാൾ ഇരുന്ന് ഖുത്വുബ നിർവ്വഹിക്കുന്നു. അല്ലാഹു പറഞ്ഞിരിക്കുന്നു: "അവർ ഒരു കച്ചവടമോ വിനോദമോ കണ്ടാൽ അവയുടെ അടുത്തേക്ക് പിരിഞ്ഞു പോവുകയും നിന്ന നിൽപിൽ നിങ്ങളെ വിട്ടേച്ച് പോവുകയും ചെയ്യുന്നു." (സൂറ:ജുമുഅ: 11) (ന)', 'كَعْبِ بْنِ عُجْرَةَ', 'കഅ്ബ്ബ്നു ഉജ്റത്(റ)', null, null, array['ن']::text[], array['ന']::text[], 'الجمعة:١١', null, 375, 375, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 131, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ ضِمَادًا قَدِمَ مَكَّةَ، وَكَانَ مِنْ أَزْدِ شَنُوءَةَ، وَكَانَ يَرْقِي مِنْ هَذِهِ الرِّيحِ، فَسَمِعَ سُفَهَاءَ مِنْ أَهْلِ مَكَّةَ يَقُولُونَ: إِنَّ مُحَمَّدًا مَجْنُونٌ، فَقَالَ: لَوْ أَنِّي رَأَيْتُ هَذَا الرَّجُلَ، لَعَلَّ اللهَ يَشْفِيهِ عَلَى يَدَيَّ. قَالَ: فَلَقِيَهُ، فَقَالَ: يَا مُحَمَّدُ، إِنِّي أَرْقِي مِنْ هَذِهِ الرِّيحِ، وَإِنَّ اللهَ يَشْفِي عَلَى يَدِي مَنْ شَاءَ، فَهَلْ لَكَ؟ فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ الْحَمْدَ لله، نَحْمَدُهُ وَنَسْتَعِينُهُ، مَنْ يَهْدِهِ اللهُ فَلَا مُضلَّ لَهُ، وَمَنْ يُضْلِلْ فَلَا هَادِيَ لَهُ، وَأَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ، أَمَّا بَعْدُ". قَالَ: فَقَالَ: أعد علي كَلِمَاتِكَ هَؤُلَاءِ. فَأَعَادَهُنَّ عَلَيْهِ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ثَلَاثَ مَرَّاتٍ، قَالَ: فَقَالَ: لَقَدْ سَمِعْتُ قَوْلَ الْكَهَنَةِ، وَقَوْلَ السَّحَرَةِ، وَقَوْلَ الشُّعَرَاءِ، فَمَا سَمِعْتُ مثل كَلِمَاتِكَ هَؤُلَاءِ، وَلَقَدْ بَلَغْنَ قَاعُوسَ الْبَحْرِ. قَالَ: فَقَالَ: هَاتِ يَدَكَ أُبَايِعْكَ عَلَى الْإِسْلَامِ. قَالَ: فَبَايَعَهُ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "وَعَلَى قَوْمِكَ". قَالَ: وَعَلَى قَوْمِي، قَالَ: فَبَعَثَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سَرِيَّةً فَمَرُّوا بِقَوْمِهِ. فَقَالَ صَاحِبُ السَّرِيَّةِ لِلْجَيْشِ:هَلْ أَصَبْتُمْ مِنْ هَؤُلَاءِ شَيْئًا؟ فَقَالَ رَجُلٌ مِنَ الْقَوْمِ:أَصَبْتُ مِنْهُمْ مِطْهَرَةً.فَقَالَ:رُدُّوهَا فَإِنَّ هَؤُلَاءِ قَوْمُ ضِمَادٍ. (م)', 'ഇബ്നുഅബ്ബാസ്(റ): അസ്ദ് ശനൂഅഃ ഗോത്രക്കാരനായ ''ളിമാദ്'' എന്നയാൾ മക്കയിൽ വന്നു. അദ്ദേഹത്തിന് മന്ത്രം പ്രയോഗിക്കാറുണ്ടായിരുന്നു. മുഹമ്മദ് ഭ്രാന്തനാണെന്ന് മക്കാ നിവാസികളിലെ പമ്പര വിഡ്ഢികൾ പറയുന്നത് അയാൾ കേട്ടു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: ഈ മനുഷ്യനെ എനിക്ക് കാണാൻ സാധിച്ചിരുന്നുവെങ്കിൽ ഞാൻ മുഖേന അല്ലാഹു അയാളെ സുഖപ്പെടുത്തിയേക്കാം. അദ്ദേഹം നബി(സ)യെ കണ്ടു. അപ്പോൾ ചോദിച്ചു: മുഹമ്മദേ, ഞാൻ ഭ്രാന്തിന് മന്ത്രം ജപിക്കാറുണ്ട്. അല്ലാഹു ഉദ്ദേശിക്കുന്നവർക്ക് ഞാൻ മുഖാന്തിരം അവൻ ശമനം നല്കുന്നതാണ്. അതിനാൽ ഞാൻ നിനക്ക് മന്ത്രിച്ചു തരട്ടെയോ? നബി(സ) പറഞ്ഞു: "നിശ്ചയം, സർവ്വ സ്തുതിയും അല്ലാഹുവിനാകുന്നു. ഞങ്ങൾ അവനെ സ്തുതിക്കുകയും സഹായാഭ്യർത്ഥന നടത്തുകയും ചെയ്യുന്നു. അല്ലാഹു സന്മാർഗ്ഗത്തിലാക്കിയവനെ വഴി തെറ്റിക്കുന്നവനാരുമില്ല. അല്ലാഹു വഴിപിഴപ്പിച്ചവനെ സന്മാർഗ്ഗത്തിലാക്കാനും ആരുമില്ല. ആരാധ്യനായി അല്ലാഹു ഒഴികെ മറ്റാരുമില്ലെന്നും അവന് പങ്കാളികളില്ലെന്നും അവൻ ഏകനാണെന്നും, മുഹമ്മദ് നബി(സ) അവന്റെ ദൂതനും ദാസനുമാണന്നും ഞാൻ സാക്ഷി നിൽക്കുന്നു." അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: നീ ഈ വചനങ്ങൾ എനിക്ക് വേണ്ടി ആവർത്തിച്ചാലും! അങ്ങനെ മൂന്ന് പ്രാവശ്യം അദ്ദേഹത്തിന് ആവർത്തിച്ചു കൊടുത്തു. നിവേദകൻ പറയുന്നു: അദ്ദേഹം പറഞ്ഞു: ജ്യോത്സ്യന്മാരുടേയും ആഭിചാരകന്മാരുടേയും കവികളുടെയുമൊക്കെ വചനങ്ങൾ ഞാൻ കേട്ടിട്ടുണ്ട്. പക്ഷെ ഇത് പോലുള്ള വചനങ്ങൾ ഞാൻ ഇതുവരെ ശ്രവിച്ചിട്ടില്ല. നിശ്ചയം അവ സമുദ്രത്തിന്റെ അടിത്തട്ടിൽ എത്തിയിരിക്കുന്നു. (മഹത്തായ പരിവർത്തനം സൃഷ്ടിച്ചിരിക്കുന്നു) അനന്തരം അദ്ദേഹം പറഞ്ഞു: അങ്ങ് കൈ നീട്ടുക, ഇസ്ലാം സ്വീകരിക്കുന്നുവെന്ന് ഞാൻ അങ്ങയോട് ഉടമ്പടി ചെയ്യട്ടെയോ? അങ്ങനെ അദ്ദേഹം നബി(സ)യുമായി ഉടമ്പടി ചെയ്തു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "താങ്കളുടെ ജനതക്കു വേണ്ടിയും ഉടമ്പടി ചെയ്യണം". അദ്ദേഹം പറഞ്ഞു: എന്റെ ജനതക്കു വേണ്ടിയും ഞാൻ ഉടമ്പടി ചെയ്യുന്നു. നിവേദകൻ പറയുന്നു: നബി(സ) അയച്ച ഒരു സൈന്യം അദ്ദേഹത്തിന്റെ ജനതയുടെ അടുക്കലൂടെ നടന്നുപോയി. അപ്പോൾ സൈന്യാധിപൻ സൈന്യത്തോട് ചോദിച്ചു: ഈ ജനതയിൽ നിന്നും നിങ്ങൾ വല്ലതും പിടിച്ചെടുത്തിട്ടുണ്ടോ? ആ കൂട്ടത്തിൽ ഒരാൾ പറഞ്ഞു: ഞാൻ അവരിൽ നിന്നും ഒരു പാത്രം എടുത്തിരുന്നു. അപ്പോൾ സൈന്യാധിപൻ പറഞ്ഞു: നിങ്ങൾ അത് മടക്കിക്കൊടുക്കുക. കാരണം ഇവർ ളിമാദിന്റെ ജനതയാണ്. (മു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 375, 376, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 132, 'عَنْ أُمِّ هِشَامٍ بِنْتِ حَارِثَةَ بْنِ النُّعْمَانِ رَضِيَ اللهُ عَنْهَا قَالَتْ: لَقَدْ كَانَ تَنُّورُنَا وَتَنُّورُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَاحِدًا سَنَتَيْنِ أَوْ سَنَةً وَبَعْضَ سَنَةٍ، وَمَا أَخَذْتُ {ق وَالْقُرْآنِ الْمَجِيدِ} إِلَّا عَنْ لِسَانِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، يَقْرَؤُهَا كُلَّ يَوْمِ جُمُعَةٍ عَلَى الْمِنْبَرِ إِذَا خَطَبَ النَّاسَ. (م,ن)', 'ഉമ്മുഹിശാം ബിൻത് ഹാരിസുബ്നു നുഅ്മാൻ(റ): രണ്ട് വർഷമോ ഒരു വർഷവും ചില്ലറ മാസങ്ങളോ ഞങ്ങളുടെയും നബി(സ)യുടെയും അടുപ്പ് ഒന്നായിരുന്നു. ''ഖാഫ് വൽഖുർആൻ......'' മുഹമ്മദ് നബി(സ)യുടെ നാവിലൂടെ കേട്ടിട്ടല്ലാതെ ഞാൻ പഠിച്ചിട്ടില്ല. ജനങ്ങളോട് പ്രസംഗിക്കുമ്പോൾ എല്ലാ വെള്ളിയാഴ്ചയും മിമ്പറിൽ വെച്ച് റസൂൽ(സ) അത് ഓതാറുണ്ടായിരുന്നു. (മു,ന)', 'أُمِّ هِشَامٍ بِنْتِ حَارِثَةَ بْنِ النُّعْمَانِ', 'ഉമ്മുഹിശാം ബിൻത് ഹാരിസുബ്നു നുഅ്മാൻ(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 376, 377, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 133, 'عَنْ يَعْلَى بْنِ أُمَيْضَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقْرَأُ عَلَى الْمِنْبَرِ: {وَنَادَوْا يَا مَالِكُ} [الزخرف:٧٧] حسن صحيح غريب. (ق,د,ت,ن)', 'യഅ്ലാബ്നു ഉമയ്യള(റ): മിമ്പറിൽ വെച്ച് റസൂൽ(സ) ''വനാദൗ യാ മാലിക്...'' എന്നു തുടങ്ങുന്ന ആയത്ത് (സുഖ്റുഫ്: 77) ഓതുന്നത് ഞാൻ കേട്ടു. [ഹദീസ് ഹസനും ഗരീബമാണെന്ന് തുർമുദി] (ബു,മു,ദ,തു,ന)', 'يَعْلَى بْنِ أُمَيْضَةَ', 'യഅ്ലാബ്നു ഉമയ്യള(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], 'الزخرف:٧٧', null, 377, 377, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 134, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُمَا: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: عَلَّمَنَا خُطْبَةَ الْحَاجَةِ: "الْحَمْدُ لِلَّهِ، نَسْتَعِينُهُ وَنَسْتَغْفِرُهُ، وَنَعُوذُ بِاللهِ مِنْ شُرُورِ أَنْفُسِنَا وَسَيِّئَاتِ أَعْمَالِنَا، مَنْ يَهْدِهِ اللهُ فَلَا مُضِلَّ لَهُ، وَمَنْ يُضْلِلْ فَلَا هَادِيَ لَهُ. وَأَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ، ثُمَّ يَقْرَأُ ثَلَاثَ آيَاتٍ: {يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللهَ حَقَّ تُقَاتِهِ وَلَا تَمُوتُنَّ إِلَّا وَأَنْتُمْ مُسْلِمُونَ} [آل عمران:١٠٢]، {يَا أَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمُ الَّذِي خَلَقَكُمْ مِنْ نَفْسٍ وَاحِدَةٍ وَخَلَقَ مِنْهَا زَوْجَهَا وَبَثَّ مِنْهُمَا رِجَالًا كَثِيرًا وَنِسَاءً وَاتَّقُوا اللهَ الَّذِي تَسَاءَلُونَ بِهِ وَالْأَرْحَامَ إِنَّ اللهَ كَانَ عَلَيْكُمْ رَقِيبًا} [النساء:١]، {يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللهَ وَقُولُوا قَوْلًا سَدِيدًا}". [الأحزاب:٧٠]. (ن)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): ആവശ്യം നേരിടുമ്പോഴുള്ള ഖുത്വുബ നബി(സ) ഞങ്ങളെ പഠിപ്പിച്ചു: "അല്ലാഹുവിനു സ്തുതി, അവനോട് ഞങ്ങൾ സഹായവും പാപമോചനവും തേടുന്നു. ഞങ്ങളുടെ മനസ്സുകളുടെ ദൂഷ്യങ്ങളിൽ നിന്നും ചീത്ത പ്രവൃത്തികളിൽ നിന്നും അല്ലാഹുവിൽ ഞങ്ങൾ അഭയം തേടുന്നു. അല്ലാഹു ആരെയെങ്കിലും സന്മാർഗ്ഗത്തിലാക്കിയാൽ അവനെ വഴികേടിലാക്കുന്നവനില്ല. ആരെയെങ്കിലും ദുർമാർഗ്ഗത്തിലാക്കിയാൽ അവനെ നേർമാർഗ്ഗത്തിലേക്ക് നയിക്കുന്നവനുമില്ല. അല്ലാഹു ഒഴികെ മറ്റൊരു ആരാധ്യനില്ലെന്നും മുഹമ്മദ് നബി(സ) അല്ലാഹുവിന്റെ ദൂതനാണെന്നും ഞാനിതാ സാക്ഷ്യം വഹിക്കുന്നു." പിന്നെ സൂറത്തു ആലു ഇംറാനിലെ നൂറ്റിരണ്ടാം ആയത്തായ ''യാഅയ്യുഹല്ലദീന ആമനൂ..........'' (സത്യവിശ്വാസികളേ, നിങ്ങൾ അല്ലാഹുവിനെ സൂക്ഷിക്കേണ്ട മുറ പ്രകാരം സൂക്ഷിക്കുക. നിങ്ങൾ മുസ്ലിംകളായി ക്കൊണ്ടല്ലാതെ മരണപ്പെടാൻ ഇടവരരുത്), സൂറത്തുനിസാഇലെ ആദ്യ ആയത്തായ ''യാഅയ്യുഹന്നാസുത്തഖൂ.........'' (മനുഷ്യരെ, നിങ്ങളെ ഒരേ ആത്മാവിൽ നിന്ന് സൃഷ്ടിക്കുകയും, അതിൽ നിന്നു തന്നെ അതിന്റെ ഇണയെയും സൃഷ്ടിക്കുകയും അവർ ഇരുവിൽനിന്നുമായി ധാരാളം പുരുഷന്മാരെയും സ്ത്രീകളെയും സൃഷ്ടിക്കുകയും ചെയ്തവനായ നിങ്ങളുടെ രക്ഷിതാവിനെ നിങ്ങൾ സൂക്ഷിക്കുവീൻ. ഏതൊരു അല്ലാഹുവിന്റെ പേരിൽ പരസ്പരം ചോദിച്ചുകൊണ്ടിരിക്കുന്നുവോ അവനെ നിങ്ങൾ സൂക്ഷിക്കുക. കുടുംബ ബന്ധങ്ങളെയും (നിങ്ങൾ സൂക്ഷിക്കുക). നിശ്ചയം അല്ലാഹു നിങ്ങളെ നിരീക്ഷിച്ചു കൊണ്ടിരിക്കുന്നു.), സൂറത്തുഅഹ്സാബിലെ ഏഴാം ആയത്തായ ''യാഅയ്യുഹല്ലദീന ആമനൂത്തഖൂല്ലാഹ........'' (സത്യവിശ്വാകളേ, നിങ്ങൾ അല്ലാഹുവിനെ സൂക്ഷിക്കുകയും നേരായ വാക്ക് പറയുകയും ചെയ്യുക.) എന്നീ മൂന്ന് ആയത്തുകൾ ഓതി. (ന)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], 'الأحزاب:٧٠', null, 377, 377, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 135, 'عَنْ حُصَيْنٍ عَنْ عُمَارَةَ بْنِ رُؤَيْبَةَ رَضِيَ اللهُ عَنْهُمَا قَالَ: رَأَى بِشْرُ بْنُ مَرْوَانَ عَلَى الْمِنْبَرِ رَافِعًا يَدَيْهِ، فَقَالَ: قَبَّحَ اللهُ هَاتَيْنِ الْيَدَيْنِ، لَقَدْ رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مَا يَزِيدُ عَلَى أَنْ يَقُولَ بِيَدِهِ هَكَذَا. وَأَشَارَ بِإِصْبَعِهِ الْمُسَبِّحَةِ. (م)', 'ഹുസൈൻ, ഉമാറതുബ്നു റുഐബ(റ): ബിശ്റുബ്നു മർവാൻ കൈ ഉയർത്തിക്കൊണ്ട് മിമ്പറിൽ നിൽക്കുന്നത് കണ്ടപ്പോൾ ഉമാറ പറഞ്ഞു: ഈ രണ്ട് കരങ്ങളെ അല്ലാഹൂ മോശമാക്കട്ടെ. റസൂൽ(സ) ഇതിൽ കൂടുതലായി ഉയർത്തിയതായി ഞാൻ കണ്ടിട്ടില്ല. തുടർന്ന് ഉമാറ തന്റെ ചൂണ്ടുവിരൽ കൊണ്ട് ആംഗ്യം കാണിച്ചു കൊണ്ടാണ് ഇതു പറഞ്ഞത്. (മു)', 'حُصَيْنٍ عَنْ عُمَارَةَ بْنِ رُؤَيْبَةَ', 'ഹുസൈൻ, ഉമാറതുബ്നു റുഐബ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 377, 378, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 136, 'عَنْ عُمَارَةَ بْنِ رُوَيْبَةَ الثَّقَفِيِّ رَضِيَ اللهُ عَنْهُ، وَرَأَى بِشْرُ بْنُ مَرْوَانَ يَخْطُبُ، فَرَفَعَ يَدَيْهِ فِي الدُّعَاءِ،فَقَالَ عُمَارَةُ: قَبَّحَ اللهُ هَاتَيْنِ الْيُدَيَّتَيْنِ الْقُصَيِّرَتَيْنِ، لَقَدْ رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَمَا يَزِيدُ عَلَى أَنْ يَقُولَ هَكَذَا. وَأَشَارَ بِالسَّبَّابَةِ .حَسَنٌ صَحِيحٌ. (م,ت,ن)', 'ഉമാറതുബ്നു റുഐബ(റ): ബിശ്റുബ്നു മർവാൻ ഖുതുബ നടത്തിക്കൊണ്ടിരിക്കെ പ്രാർത്ഥിക്കാനായി കൈ ഉയർത്തുന്നത് ഉമാറ കണ്ടു. അപ്പോൾ ഉമാറ പറഞ്ഞു: ഈ രണ്ട് കുറിയ കരങ്ങളെ അല്ലാഹൂ മോശമാക്കട്ടെ. റസൂൽ(സ) ഇതിൽ കൂടുതലായി ഉയർത്തിയത് ഞാൻ കണ്ടിട്ടില്ല എന്ന് പറഞ്ഞ്, ഉമാറ തന്റെ ചൂണ്ടുവിരൽ കൊണ്ട് ആംഗ്യം കാണിച്ചു. ഹദീസ് ഹസനും സഹീഹുമാണെന്ന് തുർമുദി. (മു,തു,ന)', 'عُمَارَةَ بْنِ رُوَيْبَةَ الثَّقَفِيِّ', 'ഉമാറതുബ്നു റുഐബ(റ)', null, null, array['م','ت','ن']::text[], array['മു','തു','ന']::text[], null, null, 378, 378, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 137, 'عَنْ حُصَيْنِ بْنِ عَبْدِ الرَّحْمَنِ قَالَ: رَأَى عُمَارَةُ بْنُ رُوَيْبَةَ بِشْرَ بْنَ مَرْوَانَ وَهُوَ يَدْعُو فِي يَوْمِ الْجُمُعَةِ، فَقَالَ عُمَارَةُ: قَبَّحَ اللهُ هَاتَيْنِ الْيَدَيْنِ، لَقَدْ رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ عَلَى الْمِنْبَرِ مَا يَزِيدُ عَلَى هَذِهِ. يَعْنِي السَّبَّابَةَ الَّتِي تَلِي الْإِبْهَامَ. (م,د,ت,ن)', 'ഹുസൈനുബ്നു അബ്ദുറഹ്മാൻ(റ): വെള്ളിയാഴ്ച ദിവസം ബിശ്റുബ്നു മർവാൻ കൈ ഉയർത്തി പ്രാർത്ഥിക്കുന്നതായി ഉമാറ കണ്ടു. അപ്പോൾ ഉമാറത്ത് പറഞ്ഞു: ഈ രണ്ടു കരങ്ങളും അല്ലാഹു മോശമാക്കട്ടെ!, നിശ്ചയം, നബി(സ)യെ മിമ്പറിൽ വെച്ച് ഞാൻ കണ്ടിട്ടുണ്ട്, തിരുമേനി തന്റെ തള്ള വിരലിനടുത്തുള്ള ചൂണ്ടു വിരലിൽ ഉപരി ഒന്നും വർദ്ധിപ്പിക്കാറില്ല. (മു,ദ,തു,ന)', 'حُصَيْنِ بْنِ عَبْدِ الرَّحْمَنِ قَالَ', 'ഹുസൈനുബ്നു അബ്ദുറഹ്മാൻ(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], null, null, 378, 378, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 138, 'عَنْ سَهْلِ بْنِ سَعْدٍ قَالَ: مَا رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ شَاهِرًا يَدَيْهِ قَطُّ، يَدْعُو عَلَى مِنْبَرِهِ، وَلَا عَلَى غَيْرِهِ، وَلَكِنْ يَقُولُ هَكَذَا. وَأَشَارَ بِالسَّبَّابَةِ، وَعَقَدَ الْوُسْطَى بِالْإِبْهَامِ. (د)', 'സഹ്ലുബ്നു സഅ്ദ്(റ): നബി(സ) മിമ്പറിൽ വെച്ചോ മറ്റെവിടെങ്കിലും വെച്ചോ പ്രാർത്ഥിക്കുമ്പോൾ കൈ ഉയർത്തുന്നത് ഞാൻ കണ്ടിട്ടില്ല. പക്ഷെ, അദ്ദേഹം ഇപ്രകാരം ചൂണ്ടാറുണ്ടായിരുന്നു. തുടർന്ന് അദ്ദേഹം തള്ളവിരൽ കൊണ്ട് മധ്യവിരൽ പിടിച്ച് ചൂണ്ടു വിരൽ കൊണ്ട് ആംഗ്യം കാണിച്ചു. (ദ)', 'سَهْلِ بْنِ سَعْدٍ قَالَ', 'സഹ്ലുബ്നു സഅ്ദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 378, 378, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 139, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ خُطْبَتَيْنِ: كَانَ يَجْلِسُ إِذَا صَعِدَ الْمِنْبَرَ حَتَّى يَفْرُغَ – أُرَاهُ قَالَ: الْمُؤَذِّنُ – ثُمَّ يَقُومُ فَيَخْطُبُ، ثُمَّ يَجْلِسُ فَلَا يَتَكَلَّمُ، ثُمَّ يَقُومُ فَيَخْطُبُ. (د)', 'ഇബ്നുഉമർ(റ): നബി(സ) രണ്ട് ഖുത്വുബ നടത്തിയിരുന്നു. മിമ്പറിൽ കയറിയ ഉടൻ നബി(സ) അതിൽ ഇരിക്കാറുണ്ടായിരുന്നു. വിരമിക്കുന്നതു വരെ - മുഅദ്ദിൻ വിരമിക്കുന്നതു വരെ - പിന്നീട് തിരുമേനി(സ) എഴുന്നേറ്റു നിന്ന് ഖുത്വുബ നിർവ്വഹിക്കും. പിന്നെ ഇരിക്കും. അപ്പോൾ സംസാരിക്കുകയില്ല. പിന്നെ എഴുന്നേറ്റു നിന്ന് ഖുത്വുബ നിർവ്വഹിക്കും. (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 378, 378, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 140, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَخْطُبُ قَائِمًا ثُمَّ يَجْلِسُ، ثُمَّ يَقُومُ فَيَخْطُبُ قَائِمًا. فَمَنْ نَبَّأَكَ أَنَّهُ كَانَ يَخْطُبُ جَالِسًا، فَقَدْ كَذَبَ فَقَدْ وَاللهِ صَلَّيْتُ مَعَهُ أَكْثَرَ مِنْ أَلْفَيْ صَلَاةٍ. (م,د,ن,جه)', 'ജാബിറുബ്നു സമുറ(റ): നബി(സ) നിന്നുകൊണ്ട് ഖുത്വുബ നിർവ്വഹിക്കും. പിന്നെ ഇരിക്കും, പിന്നെ എഴുന്നേറ്റ് നിൽക്കുകയും നിന്നുകൊണ്ട് ഖുത്വുബ നിർവ്വഹിക്കുകയും ചെയ്യും. നബി(സ) ഇരുന്ന് ഖുത്വുബ നിർവ്വഹിച്ചിരുന്നുവെന്ന് ആരാണ് നിങ്ങളോട് പറഞ്ഞത്? അവൻ പറഞ്ഞത് കളവാണ്. അല്ലാഹുവാണെ, ഞാൻ നബിയോടൊപ്പം രണ്ടായിരത്തിൽ പരം പ്രാവശ്യം നിസ്കരിച്ചിട്ടുണ്ട്. (മു,ദ,ന,ജ)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 379, 379, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 141, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَخْطُبُ يَوْمَ الْجُمُعَةِ ثُمَّ يَجْلِسُ، ثُمَّ يَقُومُ فَيَخْطُبُ، قَالَ:مثل مَا تَفْعَلُونَ الْيَوْمَ. حسن صحيح. (د,ت)', 'ഇബ്നുഉമർ(റ): നബി(സ) വെള്ളിയാഴ്ച ദിവസം ഖുത്വുബ നിർവ്വഹിച്ചിരുന്നു. പിന്നെ ഇരിക്കും. പിന്നെ എഴുന്നേറ്റുനിന്ന് ഖുത്വുബ നിർവ്വഹിക്കും പിന്നെ പറഞ്ഞു: ഇന്ന് നിങ്ങൾ ചെയ്യുന്നതുപോലെ തന്നെ. (ഹദീസ് ഹസനും സഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു) (ദ,തു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 379, 379, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 142, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَخْطُبُ الْخُطْبَتَيْنِ وَهُوَ قَائِمٌ، وَكَانَ يَفْصِلُ بَيْنَهُمَا بِجُلُوسٍ. (ن)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): നബി(സ) രണ്ട് ഖുത്വുബയും നിന്നുകൊണ്ടായിരുന്നു നിർവ്വഹിച്ചിരുന്നത്. അവയ്ക്കിടയിൽ ഒരു പ്രാവശ്യം ഇരിക്കും. (ന)', 'ابْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 379, 379, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 143, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ يَوْمَ الْجُمُعَةِ قَائِمًا، ثُمَّ يَقْعُدُ قَعْدَةً لَا يَتَكَلَّمُ، ثُمَّ يَقُومُ فَيَخْطُبُ خُطْبَةً أُخْرَى، فَمَنْ حَدَّثَكُمْ أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَخْطُبُ قَاعِدًا فَقَدْ كَذَبَ. (ن)', 'ജാബിറുബ്നു സമുറ(റ): നബി(സ) വെള്ളിയാഴ്ച ദിവസം നിന്നുകൊണ്ട് ഖുത്വുബ നിർവ്വഹിക്കുന്നത് ഞാൻ കണ്ടു. പിന്നെ അവിടുന്ന് ഒരിക്കൽ ഇരിക്കും, സംസാരിക്കുകയില്ല. പിന്നെ അവിടുന്ന് എഴുന്നേറ്റ് നിന്ന് മറ്റൊരു ഖുത്വുബ നിർവ്വഹിക്കും. അല്ലാഹുവിന്റെ ദൂതൻ ഇരുന്നുകൊണ്ട് ഖുതുബ നിർവ്വഹിച്ചിരുന്നു എന്ന് നിങ്ങളാരെങ്കിലും പറഞ്ഞാൽ അവൻ കളവു പറഞ്ഞു. (ന)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 379, 379, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 144, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: جَالَسْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَمَا رَأَيْتُهُ يَخْطُبُ إِلَّا قَائِمًا، وَيَجْلِسُ ثُمَّ يَقُومُ، فَيَخْطُبُ الْخُطْبَةَ الْآخِرَةَ. (ن)', 'ജാബിറുബ്നു സമുറ(റ): ഞാൻ നബി(സ)യോടൊപ്പമിരുന്നിട്ടുണ്ട് (സഹവസിച്ചിട്ടുണ്ട്.). നബി(സ) നിന്നു കൊണ്ടല്ലാതെ ഖുത്വുബ നിർവ്വഹിക്കുന്ന് ഞാൻ കണ്ടിട്ടില്ല. പിന്നെ തിരുമേനി(സ) ഇരിക്കുകയും ഉടനെ എഴുന്നേൽക്കുകയും, എന്നിട്ട് മറ്റൊരു ഖുത്വുബ നിർവ്വഹിക്കും. (ന)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 379, 379, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 145, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ قَائِمًا، ثُمَّ يَقْعُدُ، ثُمَّ يَقُومُ، كَمَا تَفْعَلُونَ الْآنَ. (خ)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): നബി(സ) നിന്ന് ഖുത്വുബ നടത്താറുണ്ടായിരുന്നു. പിന്നെ ഇരിക്കും, വീണ്ടും എഴുന്നേറ്റു നിൽക്കും. ഇപ്പോൾ നിങ്ങൾ ചെയ്യുന്നതു പോലെ. (ബു)', 'ابْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 379, 379, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 146, 'عَنْ عَمْرِو بْنِ تَغْلِبَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أُتِيَ بِمَالٍ، أَوْ سَبْيٍ، فَقَسَمَهُ، فَأَعْطَى رِجَالًا وَتَرَكَ رِجَالًا، فَبَلَغَهُ أَنَّ الَّذِينَ تَرَكَ عَتَبُوا، فَحَمِدَ اللهَ ثُمَّ أَثْنَى عَلَيْهِ ثُمَّ قَالَ: (أَمَّا بَعْدُ، فَوَاللهِ، إِنِّي لَأُعْطِي الرَّجُلَ وَأَدَعُ الرَّجُلَ، وَالَّذِي أَدَعُ أَحَبُّ إِلَيَّ مِنَ الَّذِي أُعْطِي، وَلَكِنْ أُعْطِي أَقْوَامًا لِمَا أَرَى فِي قُلُوبِهِمْ مِنَ الْجَزَعِ وَالْهَلَعِ، وَأَكِلُ أَقْوَامًا إِلَى مَا جَعَلَ اللهُ فِي قُلُوبِهِمْ مِنَ الْغِنَى وَالْخَيْرِ، فِيهِمْ عَمْرُو بْنُ تَغْلِبَ، فَوَاللهِ مَا أُحِبُّ أَنَّ لِي بِكَلِمَةِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حُمْرَ النَّعَمِ. (خ)', 'അംറുബ്നു തഗ്ലിബ്(റ): നബി(സ)ക്ക് കുറച്ച് ധനം കൊണ്ടുവരപ്പെട്ടു. അതല്ലെങ്കിൽ ബന്ധനസ്ഥരെ അപ്പോൾ നബി(സ) അത് വീതിച്ചു. ചിലർക്ക് നൽകുകയും ചിലരെ ഉപേക്ഷിക്കുകയും ചെയ്തു. പിന്നെ നബി(സ) ഉപേക്ഷിച്ചവർ ആക്ഷേപിക്കുന്നു എന്ന് നബി(സ)യുടെ അടുക്കൽ എത്തി. അപ്പോൾ നബി(സ) അല്ലാഹുവിനെ സ്തുതിക്കുകയും പ്രകീർത്തിക്കുകയും ചെയ്തു. പിന്നെ പറഞ്ഞു: "അല്ലാഹുവാണെ, ഞാൻ ചിലർക്ക് നൽകുകയും ചിലരെ വിട്ടേക്കുകയും ചെയ്യും. ഞാൻ വിട്ടേച്ചവരെയായിരിക്കും ഞാൻ നൽകിയവരെക്കാൾ എനിക്ക് കൂടുതൽ ഇഷ്ടം, പക്ഷേ, ചിലരുടെ ഹൃദയത്തിൽ വല്ലതും കിട്ടാത്തതിനാൽ അസ്വസ്ഥതയുള്ളതായി ഞാൻ കാണും. അതിനാൽ അവർക്ക് നൽകും. ചിലരുടെ ഹൃദയത്തിൽ ആത്മസംതൃപ്തിയും ഐശ്വര്യവും അല്ലാഹു നൽകിയതായി എനിക്ക് തോന്നും. അതിനാൽ (അവരെ വിട്ടേക്കും) അവരിൽപെട്ട ഒരാളാണ് അംറുബ്നു തഗ്ലിബ്." അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവാണെ, തിരുമേനിയുടെ ആ വാക്കുകളെക്കാൾ ചുവന്ന ഒട്ടകങ്ങൾ പോലും എനിക്ക് വിലമതിക്കുന്നതല്ല. (ബു)', 'عَمْرِو بْنِ تَغْلِبَ', 'അംറുബ്നു തഗ്ലിബ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 379, 380, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 147, 'عَنْ أَبِي حُمَيْدٍ السَّاعِدِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَامَ عَشِيَّةً بَعْدَ الصَّلَاةِ، فَتَشَهَّدَ وَأَثْنَى عَلَى اللهِ بِمَا هُوَ أَهْلُهُ، ثُمَّ قَالَ: "أَمَّا بَعْدُ". (خ)', 'അബൂഹുമൈദുസ്സാഇദി(റ): നബി(സ) ഇശാ നിസ്കാര ശേഷം എഴുന്നേറ്റുനിന്ന് അല്ലാഹുവിനെ സ്തുതിക്കുകയും ശഹാദത്ത് ചൊല്ലുകയും ചെയ്തു. പിന്നെ ''അമ്മാ ബഅ്ദ്....'' എന്ന് പറഞ്ഞു. (ബു)', 'أَبِي حُمَيْدٍ السَّاعِدِيِّ', 'അബൂഹുമൈദുസ്സാഇദി(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 380, 380, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 148, 'عَنْ عَمْرِو بْنِ حُرَيْثٍ عَنْ أَبِيهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: رَأَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ عَلَى الْمِنْبَرِ، وَعَلَيْهِ عِمَامَةٌ سَوْدَاءُ. (م,د,جه)', 'അംറുബ്നു ഹുരിയത്ത്(റ): നബി(സ) കറുത്ത തലപ്പാവ് ധരിച്ച് മിമ്പറിൽ നിന്ന് ഖുത്വുബ നിർവ്വഹിക്കുന്നത് ഞാൻ കണ്ടു. (മു,ദ,ജ)', 'عَمْرِو بْنِ حُرَيْثٍ عَنْ أَبِيهِ', 'അംറുബ്നു ഹുരിയത്ത്(റ)', null, null, array['م','د','جه']::text[], array['മു','ദ','ജ']::text[], null, null, 380, 380, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 149, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ قَائِمًا، ثُمَّ يَقْعُدُ قَعْدَةً لَا يَتَكَلَّمُ فِيهَا، ثُمَّ قَامَ فَخَطَبَ خُطْبَةً أُخْرَى، فَمَنْ خَبَّرَكَ أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خَطَبَ قَاعِدًا فَلَا تُصَدِّقْهُ. (ن)', 'ജാബിറുബ്നു സമുറ(റ): നബി(സ) നിന്നു ഖുതുബ നിർവ്വഹിക്കുകയും തുടർന്ന് കുറച്ചുസമയം മൗനമവലംബിച്ച് ഇരിക്കുകയും ചെയ്തു. പിന്നീട് എഴുന്നേറ്റ് മറ്റൊരു ഖുതുബ നടത്തുകയും ചെയ്യുന്നത് ഞാൻ കണ്ടിട്ടുണ്ട്. നബി(സ) ഇരുന്നാണ് ഖുതുബ നിർവ്വഹിച്ചതെന്ന് ആരെങ്കിലും നിന്നോട് പറഞ്ഞാൽ അത് വിശ്വസിക്കരുത്. (ന)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 380, 380, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 150, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ قَائِمًا، ثُمَّ يَجْلِسُ، ثُمَّ يَقُومُ، وَيَقْرَأُ آيَاتٍ، وَيَذْكُرُ اللهَ، وَكَانَتْ خُطْبَتُهُ قَصْدًا وَصَلَاتُهُ قَصْدًا. (ن)', 'ജാബിറുബ്നു സമുറ(റ): നബി(സ) നിന്ന് ഖുതുബ നിർവ്വഹിക്കും, പിന്നെ ഇരിക്കും. തുടർന്ന് എഴുന്നേറ്റ് ഖുർആൻ വചനങ്ങൾ ഓതുകയും അല്ലാഹുവിനെ സ്മരിക്കുകയും ചെയ്യും. തിരുമേനി(സ)യുടെ ഖുതുബയും, നിസ്കാരവും മിതമായിരുന്നു. (ന)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 380, 380, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 151, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَنْزِلُ عَنِ الْمِنْبَرِ فَيَعْرِضُ لَهُ الرَّجُلُ فَيُكَلِّمُهُ، فَيَقُومُ مَعَهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَتَّى يَقْضِيَ حَاجَتَهُ، ثُمَّ يَتَقَدَّمُ إِلَى مُصَلَّاهُ فَيُصَلِّي. (د,ت,ن,جه)', 'അനസ്(റ): നബി(സ) മിമ്പറിൽ നിന്നും ഇറങ്ങിയപ്പോൾ ഒരാൾ പ്രവാചകന്റെ മുന്നിൽ വന്ന് സംസാരിച്ചു. അയാളുടെ ആവശ്യം പൂർണ്ണമായി കേൾക്കുന്നതുവരെ നബി(സ) അവിടെ നിന്നു. ശേഷം മുസല്ലയിൽ വന്ന് നിസ്കരിച്ചു. (ദ,തു,ന,ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 381, 381, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 152, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُكَلَّمُ بِالْحَاجَةِ إِذَا نَزَلَ عَنِ الْمِنْبَرِ. (د,ت,ن,جه)', 'അനസ്(റ): നബി(സ) മിമ്പറിൽ നിന്നിറങ്ങിയാൽ ആവശ്യമായ കാര്യങ്ങളെക്കുറിച്ച് സംസാരിക്കാറുണ്ടായിരുന്നു. (ദ,തു,ന,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 381, 381, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 153, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: لَقَدْ رَأَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَعْدَ مَا تُقَامُ الصَّلَاةُ يُكَلِّمُهُ الرَّجُلُ، يَقُومُ بَيْنَهُ وَبَيْنَ الْقِبْلَةِ فَمَا يَزَالُ يُكَلِّمُهُ الرَّجُلُ، فَلَقَدْ رَأَيْتُ بَعْضَنَا يَنْعَسُ مِنْ طُولِ قِيَامِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَهُ. حَسَنٌ صَحِيحٌ (ق,د,ت)', 'അനസ്(റ): നിസ്കാരത്തിനു വേണ്ടി ഇഖാമത്ത് കൊടുത്തശേഷം ഒരാൾ നബി(സ)യോട് സംസാരിക്കുന്നത് ഞാൻ കണ്ടു. നബി(സ) അയാളുടെയും ഖിബ്‌ലയുടെയും ഇടയിലാണ് നിന്നിരുന്നത്. അയാൾ ദീർഘമായി പ്രവാചകനോട് സംസാരിക്കുന്നതിൽ ഞങ്ങളിൽ ചിലർക്ക് പ്രയാസം തോന്നിക്കും വിധം ദീർഘസമയം നബി(സ) അയാളോട് സംസാരിച്ചു കൊണ്ടേയിരുന്നു. (ഹദീസ് ഹസനും സഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു) (ബു,മു,ദ,തു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 381, 381, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 154, 'عَنْ بُرَيْدَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ، فَجَاءَ الْحَسَنُ وَالْحُسَيْنُ رَضِيَ اللهُ عَنْهُمَا وَعَلَيْهِمَا قَمِيصَانِ أَحْمَرَانِ يَعْثُرَانِ فِيهِمَا، فَنَزَلَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَطَعَ كَلَامَهُ، فَحَمَلَهُمَا ثُمَّ عَادَ إِلَى الْمِنْبَرِ، ثُمَّ: "قَالَ صَدَقَ اللهُ: {إِنَّمَا أَمْوَالُكُمْ وَأَوْلَادُكُمْ فِتْنَةٌ} رَأَيْتُ هَذَيْنِ يَعْثُرَانِ فِي قَمِيصَيْهِمَا، فَلَمْ أَصْبِرْ حَتَّى قَطَعْتُ كَلَامِي فَحَمَلْتُهُمَا". (د,ت,ن,جه)', 'ബുറൈദ(റ): നബി(സ) ഖുത്വുബ നടത്തുമ്പോൾ ഹസനും ഹുസൈനും(റ) വന്നു. അവർ ചുവന്ന വസ്ത്രം ധരിച്ച് നടക്കുമ്പോൾ വീഴുന്നുണ്ടായിരുന്നു. നബി(സ) സംസാരം നിർത്തി ഇറങ്ങിവന്നു. അവരെയുമെടുത്ത് മിമ്പറിലേക്ക് തിരിച്ചു ചെന്നിട്ട് പറഞ്ഞു: "അല്ലാഹു പറഞ്ഞതെത്ര ശരി, "നിശ്ചയം, നിങ്ങളുടെ സമ്പത്തും സന്താനങ്ങളും പരീക്ഷണമാണ്." ഞാനിവരെ ഖമീസ് ധരിച്ച് നടക്കുന്നതായി കണ്ടു. എനിക്ക് ക്ഷമിക്കാൻ സാധിച്ചില്ല. സംസാരം നിർത്തി ഞാൻ അവരെ എടുത്തു." (ദ,തു,ന,ജ)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 381, 381, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 155, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ قَائِمًا، ثُمَّ يَجْلِسُ ثُمَّ يَقُومُ. وَفِي رِوَيَةٍ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ قَائِمًا ثُمَّ يَجْلِسُ، وَيَقْرَأُ آيَاتٍ وَيَذْكُرُ اللهَ عَزَّ وَجَلَّ، وَكَانَتْ خُطْبَتُهُ قَصْدًا وَصَلَاتُهُ قَصْدًا. (م,د,ن,جه)', 'ജാബിറുബ്നു സമുറ(റ): നബി(സ) നിന്നുകൊണ്ട് ഖുത്വുബ നിർവ്വഹിച്ചിരുന്നു. പിന്നെ ഒരിക്കൽ ഇരിക്കും, വീണ്ടും എഴുന്നേറ്റ് നിൽക്കും. മറ്റൊരു റിപ്പോർട്ടിൽ: നബി(സ) നിന്ന് ഖുത്വുബ നിർവ്വഹിക്കും. പിന്നെ ഇരിക്കും. വീണ്ടും എഴുന്നേറ്റുനിന്ന് ആയത്തുകൾ ഓതുകയും അല്ലാഹുവിനെ സ്മരിക്കുകയും ചെയ്യും. നബി(സ)യുടെ ഖുതുബയും നിസ്കാരവും മിതമായിരുന്നു. (മു,ദ,ന,ജ)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 381, 382, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=18 and h.hadith_no=155), 1, null, 'മറ്റൊരു നിവേദനിൽ: നബി(സ) നിന്ന് ഖുത്വുബ നിർവ്വഹിക്കും. പിന്നെ ഇരിക്കും. വീണ്ടും എഴുന്നേറ്റുനിന്ന് ആയത്തുകൾ ഓതുകയും അല്ലാഹുവിനെ സ്മരിക്കുകയും ചെയ്യും. നബി(സ)യുടെ ഖുതുബയും നിസ്കാരവും മിതമായിരുന്നു. (മു,ദ,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 156, 'عَنْ سَعْدٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا خَطَبَ فِي الْحَرْبِ خَطَبَ عَلَى قَوْسٍ، وَإِذَا خَطَبَ فِي الْجُمُعَةِ خَطَبَ عَلَى عَصًا. [ز: في إسناده ضعيف] (جه)', 'സഅദ്(റ): നബി(സ) യുദ്ധത്തിലായിരിക്കെ ഖുത്വുബ നടത്തിയിരുന്നത് അമ്പിന്മേൽ ഊന്നി നിന്നായിരുന്നു. ജുമുഅയിൽ ഖുത്വുബ നടത്തിയിരുന്നത് വടിയുടെ മേൽ ഊന്നികൊണ്ടായിരുന്നു. [ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു] (ജ)', 'سَعْدٍ', 'സഅദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', null, 382, 382, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 157, 'عَنْ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُ أَنَّهُ سُئِلَ: أَكَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ قَائِمًا أَوْ قَاعِدًا؟ قَالَ: أَوَمَا تَقْرَأُ: {وَتَرَكُوكَ قَائِمًا}. [الجمعة:١١] (جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): അദ്ദേഹത്തോട് ചോദിക്കപ്പെട്ടു: നബി(സ) നിന്നു കൊണ്ടായിരുന്നോ ഇരുന്നു കൊണ്ടായിരുന്നോ ഖുത്വുബ നിർവ്വഹിച്ചിരുന്നത്? അദ്ദേഹം പറഞ്ഞു: "നിൽക്കുന്നവനെ ഉപേക്ഷിച്ചു കൊണ്ട്...." എന്ന സൂറ:ജുമുഅയിലെ ആയത്ത് നീ ഓതിയിട്ടില്ലേ? (ജ)', 'عَبْدِ اللهِ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'الجمعة:١١', null, 382, 382, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 158, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا صَعِدَ الْمِنْبَرَ سَلَّمَ. [ز: في إسناده ضعيف] (جه)', 'ജാബിറുബ്നു അബ്ദുല്ല(റ): നബി(സ) മിമ്പറിൻന്മേൽ കയറിയാൽ സലാം ചൊല്ലാറുണ്ടായിരുന്നു. [ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു] (ജ)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദുല്ല(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', null, 382, 382, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 159, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خُطْبَتَانِ كَانَ يَجْلِسُ بَيْنَهُمَا، يَقْرَأُ الْقُرْآنَ، وَيُذَكِّرُ النَّاسَ. وَفِي رِوَيَةٍ: رَأَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ قَائِمًا، ثُمَّ يَقْعُدُ قَعْدَةً لَا يَتَكَلَّمُ،.... وَسَاقَ الْحَدِيثَ. (م,د,ن,جه)', 'ജാബിറുബ്നു സമുറ(റ): നബി(സ) രണ്ട് ഖുത്വുബ നടത്തുകയും അവക്കിടയിൽ ഇരിക്കുകയും ചെയ്യാറുണ്ടായിരുന്നു. പിന്നെ ഖുർആൻ ഓതുകയും ജനങ്ങളെ ഓർമ്മിപ്പിക്കുകയും ചെയ്തിരുന്നു. മറ്റൊരു റിപ്പോർട്ടിൽ: നബി(സ) നിന്ന് ഖുത്വുബ നടത്തുന്നത് ഞാൻ കണ്ടിട്ടുണ്ട്. പിന്നെ ഇരിക്കും. അതിൽ സംസാരിക്കുകയില്ല....... ഹദീസ് തുടർന്നു പറഞ്ഞു. (മു,ദ,ന,ജ)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 382, 382, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=18 and h.hadith_no=159), 1, null, 'മറ്റൊരു നിവേദനിൽ: നബി(സ) നിന്ന് ഖുത്വുബ നടത്തുന്നത് ഞാൻ കണ്ടിട്ടുണ്ട്. പിന്നെ ഇരിക്കും. അതിൽ സംസാരിക്കുകയില്ല....... ഹദീസ് തുടർന്നു പറഞ്ഞു. (മു,ദ,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 160, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَخْطُبُ خُطْبَتَيْنِ، يَجْلِسُ بَيْنَهُمَا جِلْسَةً. زَادَ بِشْرٌ: وَهُوَ قَائِمٌ. (خ,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): നബി(സ) രണ്ട് ഖുത്വുബ നിർവ്വഹിക്കാറുണ്ടായിരുന്നു. അവക്കിടയിൽ ഇരിക്കുകയും ചെയ്യും. ബിശ്റ് പറഞ്ഞു: നബി(സ) നിന്നായിരുന്നു ഖുത്വുബ നിർവ്വഹിച്ചിരുന്നത്. (ബു,ന,ജ)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['خ','ن','جه']::text[], array['ബു','ന','ജ']::text[], null, null, 382, 382, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 161, 'عَنْ سِمَاكٍ قَالَ: سَأَلْتُ جَابِرًا رَضِيَ اللهُ عَنْهُ: أَكَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ قَائِمًا؟ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ قَائِمًا، ثُمَّ يَقْعُدُ قَعْدَةً، ثُمَّ يَقُومُ. (ن)', 'സിമാക്(റ): ഞാൻ ജാബിറി(റ)നോട് ചോദിച്ചു: നബി(സ) നിന്നു കൊണ്ടായിരുന്നോ ഖുതുബ നിർവ്വഹിച്ചിരുന്നത്? അദ്ദേഹം പറഞ്ഞു: നിന്നുകൊണ്ടായിരുന്നു നബി(സ) ഖുതുബ നിർവഹിച്ചിരുന്നത്. (രണ്ട് ഖുതുബകൾക്കിടയിൽ) കുറച്ചുസമയം ഇരിക്കും. പിന്നെ എഴുന്നേൽക്കും. (ന)', 'سِمَاكٍ قَالَ', 'സിമാക്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 382, 382, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 162, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ يَوْمَ الْجُمُعَةِ وَالنَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ بِهَيْئَةٍ بَذَّةٍ، فَقَالَ لَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَصَلَّيْتَ؟". قَالَ: لَا، قَالَ: "صَلِّ رَكْعَتَيْنِ". وَحَثَّ النَّاسَ عَلَى الصَّدَقَةِ، فَأَلْقَوْا ثِيَابًا فَأَعْطَاهُ مِنْهَا ثَوْبَيْنِ، فَلَمَّا كَانَتِ الْجُمُعَةُ الثَّانِيَةُ جَاءَ وَرَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ، فَحَثَّ النَّاسَ عَلَى الصَّدَقَةِ، قَالَ: فَأَلْقَى أَحَدُ ثَوْبَيْهِ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "جَاءَ هَذَا يَوْمَ الْجُمُعَةِ بِهَيْئَةٍ بَذَّةٍ، فَأَمَرْتُ النَّاسَ بِالصَّدَقَةِ فَأَلْقَوْا ثِيَابًا، فَأَمَرْتُ لَهُ مِنْهَا بِثَوْبَيْنِ، ثُمَّ جَاءَ الْآنَ فَأَمَرْتُ النَّاسَ بِالصَّدَقَةِ، فَأَلْقَى أَحَدَهُمَا". فَانْتَهَرَهُ، وَقَالَ: "خُذْ ثَوْبَكَ". (ن)', 'അബൂസഈദിൽ ഖുദ്രി(റ): നബി(സ) വെള്ളിയാഴ്ച ഖുത്വുബ നിർവ്വഹിച്ചു കൊണ്ടിരിക്കെ മുഷിഞ്ഞ വേഷത്തിൽ ഒരാൾ വന്നു. നബി(സ) അയാളോട് ചോദിച്ചു: "നീ നിസ്കരിച്ചുവോ?" അയാൾ പറഞ്ഞു: ഇല്ല, നബി(സ) പറഞ്ഞു: "നീ രണ്ട് റക്അത്ത് നിസ്കരിക്കുക." നബി(സ) ജനങ്ങളെ സ്വദഖ ചെയ്യാൻ പ്രോത്സാഹിപ്പിച്ചു. ജനങ്ങളെല്ലാം വസ്ത്രങ്ങൾ ദാനമായി വെച്ചു. നബി(സ) അതിൽ നിന്ന് രണ്ടെണ്ണം അയാൾക്ക് നൽകി. രണ്ടാമത്തെ വെള്ളിയാഴ്ചയായപ്പോൾ നബി(സ) ഖുത്വുബ നിർവ്വഹിച്ചു കൊണ്ടിരിക്കെ അയാൾ വന്നു. നബി ജനങ്ങളെ സ്വദഖ നൽകാൻ പ്രേരിപ്പിച്ചു. അബൂസഈദ്(റ) പറയുന്നു: അയാൾ തന്റെ രണ്ട് വസ്ത്രത്തിൽ നിന്ന് ഒന്ന് ദാനമായി വെച്ചു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "കഴിഞ്ഞ വെള്ളിയാഴ്ച ഇയാൾ മുഷിഞ്ഞ വേഷത്തിൽ വന്നു. അപ്പോൾ ഞാൻ ജനങ്ങളോട് സ്വദഖ ചെയ്യാൻ കൽപിച്ചു. അവർ വസ്ത്രങ്ങൾ ദാനമായി വെച്ചു. അതിൽ നിന്ന് രണ്ടെണ്ണം അയാൾക്ക് നൽകാൻ ഞാൻ കൽപിച്ചു. പിന്നെ ഇയാൾ ഇപ്പോഴും വന്നിരിക്കുന്നു. ഞാൻ ജനങ്ങളോട് സ്വദഖ ചെയ്യാൻ കൽപിച്ചു. തന്റെ രണ്ടു വസ്ത്രങ്ങളിൽ ഒരെണ്ണം അദ്ദേഹമിതാ ദാനമായി വെച്ചിരിക്കുന്നു. ശേഷം റസൂൽ(സ) അയാളെ വിലക്കിക്കൊണ്ട് പറഞ്ഞു: "നീ നിന്റെ വസ്ത്രമെടുക്കുക." (ന)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 383, 383, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 163, 'عَنْ عَمَّارِ بْنِ يَاسِرٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: أَمَرَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِإِقْصَارِ الْخُطَبِ. (د)', 'അമ്മാറുബ്നു യാസിർ(റ): ഖുത്വുബ ചുരുക്കാൻ വേണ്ടി നബി(സ) ഞങ്ങളോട് കൽപിച്ചു. (ദ)', 'عَمَّارِ بْنِ يَاسِرٍ', 'അമ്മാറുബ്നു യാസിർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 383, 383, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 164, 'عَنْ جَابِرِ بْنِ سَمُرَةَ السُّوَائِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَا يُطِيلُ الْمَوْعِظَةَ يَوْمَ الْجُمُعَةِ، إِنَّمَا هُنَّ كَلِمَاتٌ يَسِيرَاتٌ. (د)', 'ജാബിറുബ്നു സമുറതുസ്സുവാഈ(റ): നബി(സ) വെള്ളിയാഴ്ച ദിവസം പ്രസംഗം നീട്ടികൊണ്ടു പോയിരുന്നില്ല. അതിലെ വാചകങ്ങൾ (ലളിതമായ) ചുരുങ്ങിയ വാക്കുകളായിരുന്നു. (ദ)', 'جَابِرِ بْنِ سَمُرَةَ السُّوَائِيِّ', 'ജാബിറുബ്നു സമുറതുസ്സുവാഈ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 383, 383, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 165, 'عَنْ عَبْدِ اللهِ بْنِ أَبِي أَوْفَى رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُكْثِرُ الذِّكْرَ وَيُقِلُّ اللَّغْوَ، وَيُطِيلُ الصَّلَاةَ وَيُقَصِّرُ الْخُطْبَةَ، وَلَا يَأْنَفُ أَنْ يَمْشِيَ مَعَ الْأَرْمَلَةِ وَالْمِسْكِينِ فَيَقْضِيَ لَهُ الْحَاجَةَ. (ن)', 'അബ്ദുല്ലാഹിബ്നു അബൂഔഫാ(റ): നബി(സ) ദിക്റുകൾ വർദ്ധിപ്പിക്കുകയും അനാവശ്യമായവ കുറക്കുകയും ചെയ്തിരുന്നു. നിസ്കാരം ദീർഘമായി നിർവ്വഹിക്കുകയും ഖുത്വുബ ചുരുക്കുകയും ചെയ്തിരുന്നു. വിധവകളോടും പാവങ്ങളോടുമൊപ്പം നടന്ന് അവർ നബി(സ)യുടെ ആവശ്യം നിർവ്വഹിച്ചു കൊടുക്കുന്നതും നബി(സ) ഇഷ്ടപ്പെട്ടിരുന്നില്ല. (ന)', 'عَبْدِ اللهِ بْنِ أَبِي أَوْفَى', 'അബ്ദുല്ലാഹിബ്നു അബൂഔഫാ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 383, 383, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 166, 'عَنْ أبِي وَائِلٍ رَضِيَ اللهُ عَنْهُ قَالَ: خَطَبَنَا عَمَّارٌ فَأَوْجَزَ وَأَبْلَغَ، فَلَمَّا نَزَلَ قُلْنَا: يَا أَبَا الْيَقْظَانِ، لَقَدْ أَبْلَغْتَ وَأَوْجَزْتَ، فَلَوْ كُنْتَ تَنَفَّسْتَ. فَقَالَ: إِنِّي سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّ طُولَ صَلَاةِ الرَّجُلِ وَقِصَرَ خُطْبَتِهِ مَئِنَّةٌ مِنْ فِقْهِهِ، فَأَطِيلُوا الصَّلَاةَ وَاقْصُرُوا الْخُطْبَةَ، وَإِنَّ مِنَ الْبَيَانِ سِحْرًا". (م)', 'അബീ വാഇൽ(റ): അമ്മാർ(റ) ഞങ്ങൾക്ക് സംക്ഷിപ്തമായി നല്ല വിധത്തിലും ഖുത്വുബ നിർവ്വഹിച്ചു. അദ്ദേഹം മിമ്പറിൽ നിന്നിറങ്ങിയപ്പോൾ ഞങ്ങളദ്ദേഹത്തോട് ചോദിച്ചു: ഹേ! അബുൽ യഖ്ദാൻ, നിങ്ങൾ സംക്ഷിപ്തമാക്കിയല്ലോ, നിങ്ങൾ വിശദമായി നിർവ്വഹിച്ചിരുന്നെങ്കിൽ, അദ്ദേഹം പറഞ്ഞു: നബി(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "ഒരാളുടെ ദീർഘിച്ച നിസ്കാരവും ചുരുങ്ങിയ ഉപദേശവും അവന്റെ പാണ്ഢിത്യത്തിന്റെ അടയാളമാണ്. നിങ്ങൾ നിസ്കാരം ദീർഘിപ്പിക്കുകയും ഖുത്വുബ ചുരുക്കുകയും ചെയ്യുക, കാരണം വാചാലതയിൽ മാരണമുണ്ട്." (മു)', 'أبِي وَائِلٍ', 'അബീ വാഇൽ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 384, 384, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 167, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا اسْتَوَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَوْمَ الْجُمُعَةِ قَالَ: "اجْلِسُوا". فَسَمِعَ ذَلِكَ ابْنُ مَسْعُودٍ، فَجَلَسَ عَلَى بَابِ الْمَسْجِدِ، فَرَآهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "تَعَالَ يَا عَبْدَ اللهِ بْنَ مَسْعُودٍ". (د)', 'ജാബിർ(റ): വെള്ളിയാഴ്ച ദിവസം ഞങ്ങളിലേക്ക് തിരിഞ്ഞുനിന്ന് നബി(സ) പറഞ്ഞു: "നിങ്ങൾ ഇരിക്കുക." ഇബ്നുമസ്ഊദും ഇത് കേട്ടു. അപ്പോൾ അദ്ദേഹം പള്ളിയുടെ വാതിലിൽ ഇരുന്നു. അതു കണ്ടപ്പോൾ നബി(സ) പറഞ്ഞു: "അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്, ഇങ്ങോട്ട് വരൂ." (ദ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 384, 384, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 168, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا خَطَبَ احْمَرَّتْ عَيْنَاهُ وَعَلَا صَوْتُهُ، وَاشْتَدَّ غَضَبُهُ، حَتَّى كَأَنَّهُ مُنْذِرُ جَيْشٍ، يَقُولُ: صَبَّحَكُمْ وَمَسَّاكُمْ، وَيَقُولُ: "بُعِثْتُ أَنَا وَالسَّاعَةُ كَهَاتَيْنِ". وَيَقْرُنُ بَيْنَ إِصْبَعَيْهِ: السَّبَّابَةِ وَالْوُسْطَى، وَيَقُولُ: "أَمَّا بَعْدُ، فَإِنَّ خَيْرَ الْحَدِيثِ كِتَابُ اللهِ، وَخَيْرُ الْهُدَى هُدَى مُحَمَّدٍ، وَشَرُّ الْأُمُورِ مُحْدَثَاتُهَا، وَكُلُّ بِدْعَةٍ ضَلَالَةٌ". ثُمَّ يَقُولُ: "أَنَا أَوْلَى بِكُلِّ مُؤْمِنٍ مِنْ نَفْسِهِ، مَنْ تَرَكَ مَالًا فَلِأَهْلِهِ، وَمَنْ تَرَكَ دَيْنًا أَوْ ضِيَاعًا فَإِلَيَّ وَعَلَيَّ". (م)', 'ജാബിറുബ്നു അബ്ദുല്ല(റ): റസൂൽ(സ) ഖുത്വുബ നിർവ്വഹിക്കുമ്പോൾ ഒരു സൈന്യത്തിന്റെ മുന്നറിയിപ്പുകാരനെപ്പോലെ തങ്ങളുടെ കണ്ണുകൾ ചുവക്കും, ശബ്ദം ഉയരും, കോപം കഠിനമാകും, പിന്നെ പറയും: "ഞാനും അന്ത്യനാളും ഇതുപോലെ നിയോഗിതമായിരിക്കുന്നു." (രണ്ട് വിരലുകൾ അടുപ്പിച്ച് വെക്കും. - ചൂണ്ടുവിരലും നടുവിരലും - എന്നിട്ട് പറയും: "ആമുഖത്തിന് ശേഷം പറയട്ടെ; നിശ്ചയം, ഏറ്റവും ഉത്തമമായ വചനം അല്ലാഹുവിന്റെ ഗ്രന്ഥമാകുന്നു, ഏറ്റവും ഉത്തമമായ മാർഗ്ഗം മുഹമ്മദ്(സ)യുടെ മാർഗ്ഗമാകുന്നു. ഏറ്റവും ചീത്ത കാര്യങ്ങൾ (മതത്തിന്റെ പിന്തുണയില്ലാത്ത) നൂതന സംഗതികളത്രെ. (ഇത്തരം) എല്ലാ നൂതന വാദങ്ങളും വഴി കേടാകുന്നു." പിന്നീടവിടുന്ന് ഇപ്രകാരം പറയും: "ഓരോ വിശ്വാസിക്കും അവന്റെ സ്വന്തത്തേക്കാൾ ഞാൻ ബന്ധപ്പെട്ടവനത്രെ, ആരെങ്കിലും സമ്പത്ത് ഉപേക്ഷിച്ചാൽ അതവന്റെ കുടുംബത്തിനാണ്, ആരെങ്കിലും കടമോ നഷ്ടമോ വിട്ടേച്ച് പോയാൽ അത് (വീട്ടൽ) എന്റെ ബാധ്യതയാണ്." (മു)', 'جَابِرِ بْنِ عَبْدِ اللهِ قَالَ', 'ജാബിറുബ്നു അബ്ദുല്ല(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 384, 384, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 169, 'عَنْ عَدِيِّ بْنِ حَاتِمٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَجُلًا خَطَبَ عِنْدَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: مَنْ يُطِعِ اللهَ وَرَسُولَهُ فَقَدْ رَشَدَ، وَمَنْ يَعْصِهِمَا فَقَدْ غَوَى. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "بِئْسَ الْخَطِيبُ أَنْتَ قُلْ وَمَنْ يَعْصِ اللهَ وَرَسُولَهُ" قَالَ ابْنُ نُمَيْرٍ: فَقَدْ غَوِيَ. (م)', 'അദിയ്യുബ്നു ഹാതിം(റ): ഒരാൾ നബി(സ)യുടെ അടുത്തുനിന്ന് പ്രസംഗിച്ചു: ആർ അല്ലാഹുവിനെയും അവന്റെ ദൂതനേയും അനുസരിക്കുന്നുവോ അവൻ നേർമാർഗ്ഗത്തിലായി, ആർ അവരെ രണ്ടു പേരെയും തള്ളിക്കളയുന്നുവോ അവൻ വഴികേടിലായി. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നീ എത്ര മോശമായ പ്രാസംഗികനാണ്. നീ ഇപ്രകാരം പറയുക: ''ആർ അല്ലാഹുവിനേയും അവന്റെ ദൂതനെയും ധിക്കരിച്ചുവോ...'' ഇബ്നുനുമൈർ പറഞ്ഞു: അവൻ വഴികേടിലായി. (മു)', 'عَدِيِّ بْنِ حَاتِمٍ', 'അദിയ്യുബ്നു ഹാതിം(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 385, 385, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 170, 'عَنْ شُعَيْبِ بْنِ زُرَيْقٍ الطَّائِفِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: جَلَسْتُ إِلَى رَجُلٍ لَهُ صُحْبَةٌ مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُقَالُ لَهُ: الْحَكَمُ بْنُ حَزْنٍ الْكُلَفِيُّ، فَأَنْشَأَ يُحَدِّثُنَا قَالَ: وَفَدْتُ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سَابِعَ سَبْعَةٍ، أَوْ تَاسِعَ تِسْعَةٍ، فَدَخَلْنَا عَلَيْهِ فَقُلْنَا: يَا رَسُولَ اللهِ، زُرْنَاكَ فَادْعُ اللهَ لَنَا بِخَيْرٍ. فَأَمَرَ بِنَا - أَوْ أَمَرَ لَنَا - بِشَيْءٍ مِنَ التَّمْرِ، وَالشَّأْنُ إِذْ ذَاكَ دُونٌ، فَأَقَمْنَا بِهَا أَيَّامًا شَهِدْنَا فِيهَا الْجُمُعَةَ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَامَ مُتَوَكِّئًا عَلَى عَصًا أَوْ قَوْسٍ، فَحَمِدَ اللهَ وَأَثْنَى عَلَيْهِ كَلِمَاتٍ خَفِيفَاتٍ طَيِّبَاتٍ مُبَارَكَاتٍ. ثُمَّ قَالَ: "أَيُّهَا النَّاسُ، إِنَّكُمْ لَنْ تُطِيقُوا - أَوْ لَنْ تَفْعَلُوا - كُلَّ مَا أُمِرْتُمْ بِهِ، وَلَكِنْ سَدِّدُوا وَأَبْشِرُوا". (د)', 'ശുഐബുബ്നു സുറൈഖിത്താഇഫീ(റ): ഞാൻ നബി(സ)യോടൊപ്പം സഹവസിച്ച അൽഹകമുബ്നു ഹസ്നിൽ കുലഫി(റ)ന്റെ അടുത്ത് ഇരിക്കുകയായിരുന്നു. അദ്ദേഹം ഞങ്ങളോട് സംസാരിക്കാൻ തുടങ്ങി. എന്നിട്ട് പറഞ്ഞു: നബി(സ)യുടെ അടുക്കലേക്കുള്ള വിവേദക സംഘത്തിൽ ഏഴിൽ ഒരുവനായി എന്നേയും അയച്ചു. അല്ലെങ്കിൽ അമ്പതിൽ ഒരുവനായി. അങ്ങനെ ഞങ്ങൾ പ്രവാചക സന്നിധിയിൽ പ്രവേശിച്ചു. ഞങ്ങൾ പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരെ, ഞങ്ങൾ താങ്കളെ സന്ദർശിച്ചിരിക്കുന്നു. ഞങ്ങൾക്ക് നന്മക്കായി പ്രാർത്ഥിച്ചാലും, അപ്പോൾ ഞങ്ങളോട് അൽപം കാരക്ക കഴിക്കാൻ പറഞ്ഞു. ഞങ്ങൾ വളരെ ക്ഷീണിതരായിരുന്നു. ഞങ്ങൾ പ്രവാചകന്റെ അടുക്കൽ ദിവസങ്ങളോളം കഴിച്ചുകൂട്ടി. അതിൽ റസൂലിനോടൊപ്പം ജുമുഅയിൽ പങ്കെടുക്കുവാനും ഞങ്ങൾക്ക് കഴിഞ്ഞു. (ഖുത്വുബയിൽ) പ്രവാചകൻ(സ) ഒരു വടിയുടെമേലോ വില്ലിനുമേലോ ഊന്നി എഴുന്നേറ്റുനിന്നു. ശേഷം അല്ലാഹുവിനെ സ്തുതിക്കുകയും പ്രകീർത്തിക്കുകയും ചെയ്തു. ലഘുവായതും ഉൽകൃഷ്ടവും, പരിശുദ്ധവുമായിരുന്നു ആ വാക്കുകൾ. ശേഷം പറഞ്ഞു: "ജനങ്ങളെ, നിങ്ങൾ കൽപിക്കപ്പെട്ടത് മുഴുവൻ ചെയ്യുന്നതിന് കഴിവുള്ളവരല്ല. എങ്കിലും, നിങ്ങൾ കഴിയുന്നത്ര നന്മ ചെയ്യുകയും സന്തോഷ വാർത്ത അറിയിക്കുകയും ചെയ്യുക." (ദ)', 'شُعَيْبِ بْنِ زُرَيْقٍ الطَّائِفِيِّ', 'ശുഐബുബ്നു സുറൈഖിത്താഇഫീ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 385, 385, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 171, 'عَنِ ابْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا تَشَهَّدَ قَالَ: "الْحَمْدُ للهِ، نَسْتَعِينُهُ وَنَسْتَغْفِرُهُ، وَنَعُوذُ بِاللهِ مِنْ شُرُورِ أَنْفُسِنَا، مَنْ يَهْدِهِ اللهُ فَلَا مُضِلَّ لَهُ، وَمَنْ يُضْلِلْ فَلَا هَادِيَ لَهُ، وَأَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ، أَرْسَلَهُ بِالْحَقِّ بَشِيرًا وَنَذِيرًا بَيْنَ يَدَيِ السَّاعَةِ، مَنْ يُطِعِ اللهَ وَرَسُولَهُ فَقَدْ رَشَدَ، وَمَنْ يَعْصِهِمَا فَإِنَّهُ لَا يَضُرُّ إِلَّا نَفْسَهُ، وَلَا يَضُرُّ اللهَ شَيْئًا". وَفِي رِوَيَةٍ قَالَ: "وَمَنْ يَعْصِهِمَا فَقَدْ غَوَى". (د)', 'ഇബ്നുമസ്ഊദ്(റ): നബി(സ) (ഖുത്വുബയിൽ) തശഹ്ഹുദിന്ശേഷം ഇപ്രകാരം പറയുമായിരുന്നു: "അല്ലാഹുവിന് സ്തുതി, അവനോട് സഹായം തേടുന്നു. അവനോട് പാപമോചനം അർത്ഥിക്കുന്നു. നമ്മുടെ മനസ്സുകളുടെ തിന്മകളിൽ നിന്ന് അല്ലാഹുവിൽ ശരണം തേടുന്നു. ആരെ അല്ലാഹു നേർമാർഗ്ഗത്തിലാക്കുന്നുവോ അയാളെ പിഴപ്പിക്കുന്ന ആരുമില്ല. ആരെ അല്ലാഹു വഴികേടിലാക്കുന്നുവോ അയാളെ മാർഗ്ഗദർശനം ചെയ്യുന്ന ഒരുത്തനുമില്ല. അല്ലാഹു അല്ലാതെ യാതൊരു ആരാധ്യനുമില്ലെന്ന് ഞാൻ സാക്ഷ്യം വഹിക്കുന്നു. മുഹമ്മദ്(സ) അവന്റെ അടിമയും ദൂതനുമാണെന്നും ഞാൻ സാക്ഷ്യം വഹിക്കുന്നു. അവനെ സത്യവുമായി നിയോഗിച്ചിരിക്കുന്നു. അന്ത്യനാൾ വരെയുള്ള ജനതക്ക് സന്തോഷ വാർത്ത അറിയിക്കുന്നവനും മുന്നറിയിപ്പ് നൽകുന്നവനുമായും. ആർ അല്ലാഹുവിനേയും അവന്റെ ദൂതനെയും അനുസരിക്കുന്നുവോ അവൻ സന്മാർഗ്ഗത്തിലായി, ആർ അവരെ രണ്ടുപേരെയും നിരസിക്കുന്നുവോ അവൻ സ്വന്തത്തിന് തന്നെ ഉപദ്രവം ചെയ്തു. അതുമൂലം അവൻ അല്ലാഹുവിന് ഒരു ഉപദ്രവവും ഏൽപിക്കുന്നില്ല." മറ്റൊരു റിപ്പോർട്ടിൽ: "ആർ അവർ രണ്ടുപേരെയും നിരസിച്ചുവോ അവൻ വഴികേടിലായി." (ദ)', 'ابْنِ مَسْعُودٍ', 'ഇബ്നുമസ്ഊദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 385, 386, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=18 and h.hadith_no=171), 1, null, 'മറ്റൊരു നിവേദനിൽ: "ആർ അവർ രണ്ടുപേരെയും നിരസിച്ചുവോ അവൻ വഴികേടിലായി." (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 172, 'عَنْ عَدِيِّ بْنِ حَاتِمٍ رَضِيَ اللهُ عَنْهُ: أَنَّ خَطِيبًا خَطَبَ عِنْدَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ يُطِعِ اللهَ وَرَسُولَهُ فَقَدْ رَشَدَ ، وَمَنْ يَعْصِهِمَا... فَقَالَ: "قُمْ، أَوِ اذْهَبْ، بِئْسَ الْخَطِيبُ أَنْتَ". (د)', 'അദിയ്യുബ്നു ഹാതിം(റ): ഒരു ഖത്തീബ് നബി(സ)യുടെ അടുത്തുനിന്ന് പ്രസംഗിച്ചു: ആർ അല്ലാഹുവിനെയും അവന്റെ ദൂതനേയും അനുസരിക്കുന്നുവോ അവൻ നേർമാർഗ്ഗത്തിലായി, ആർ അവരെ രണ്ടുപേരെയും തള്ളിക്കളയുന്നുവോ ........... ഇത്രയും പറഞ്ഞപ്പോൾ നബി(സ) പറഞ്ഞു: "എഴുന്നേൽക്കൂ, - പോകൂ - എത്ര മോശയായ ഖതീബാണ് നീ." (ദ)', 'عَدِيِّ بْنِ حَاتِمٍ', 'അദിയ്യുബ്നു ഹാതിം(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 386, 386, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 173, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَتْ صَلَاةُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَصْدًا، وَخُطْبَتُهُ قَصْدًا، يَقْرَأُ آيَاتٍ مِنَ الْقُرْآنِ، وَيُذَكِّرُ النَّاسَ. (م,د,ت)', 'ജാബിറുബ്നു സമുറ(റ): നബി(സ)യുടെ നിസ്കാരം മിതമായ രീതിയിലായിരുന്നു. ഖുത്വുബയും മിതമായിരുന്നു. അതിൽ ഖുർആനിലെ ആയത്തുകൾ പാരായണം ചെയ്യും, ജനങ്ങളെ ഉത്ബോധിപ്പിക്കും. (മു,ദ,തു)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 386, 386, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 174, 'عَنْ أَبِي رِفَاعَةَ رَضِيَ اللهُ عَنْهُ: انْتَهَيْتُ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَخْطُبُ قَالَ: فَقُلْتُ: يَا رَسُولَ اللهِ، رَجُلٌ غَرِيبٌ جَاءَ يَسْأَلُ عَنْ دِينِهِ، لَا يَدْرِي مَا دِينُهُ؟ قَالَ: فَأَقْبَلَ عَلَيَّ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَتَرَكَ خُطْبَتَهُ حَتَّى انْتَهَى إِلَيَّ، فَأُتِيَ بِكُرْسِيٍّ حَسِبْتُ قَوَائِمَهُ حَدِيدًا، قَالَ: فَقَعَدَ عَلَيْهِ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَجَعَلَ يُعَلِّمُنِي مِمَّا عَلَّمَهُ اللهُ، ثُمَّ أَتَى خُطْبَتَهُ فَأَتَمَّ آخِرَهَا. (م)', 'അബൂരിഫാഅ(റ): നബി(സ) ഖുത്വുബ നിർവ്വഹിക്കുമ്പോൾ ഞാനങ്ങോട്ട് ചെന്ന് ചോദിച്ചു: പ്രവാചകരേ, മതം എന്താണെന്ന് ചോദിച്ചറിയാൻവേണ്ടി വന്ന ഒരു പരദേശിയാണ് ഞാൻ, ഒരുത്തനു മേൽ ബാദ്ധ്യതയുള്ള മതാനുഷ്ടാനങ്ങൾ എന്തെല്ലാമാണ്?. അപ്പോൾ നബി(സ) എന്നിലേക്ക് തിരിഞ്ഞ് ഖുത്വുബ നിറുത്തി എന്റ അടുത്ത് വന്നു. ഇരുമ്പിന്റെ കാലുള്ള ഒരു കസേര നബിക്ക് ഇട്ടുകൊടുത്തു. അതിലിരുന്ന് പ്രവാചകൻ അല്ലാഹു അദ്ദേഹത്തെ പഠിപ്പിച്ചതിൽ നിന്ന് പഠിപ്പിക്കാൻ തുടങ്ങി. തിരിച്ചുവന്ന് ഖുത്വുബ പൂർത്തിയാക്കി. (മു)', 'أَبِي رِفَاعَةَ', 'അബൂരിഫാഅ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 386, 386, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 175, 'عَنِ النُّعْمَانِ بْنِ بَشِيرٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقْرَأُ فِي الْعِيدَيْنِ وَفِي الْجُمُعَةِ بِ{سَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى} وَ{هَلْ أَتَاكَ حَدِيثُ الْغَاشِيَةِ}. قَالَ: وَإِذَا اجْتَمَعَ الْعِيدُ وَالْجُمُعَةُ فِي يَوْمٍ وَاحِدٍ يَقْرَأُ بِهِمَا أَيْضًا فِي الصَّلَاتَيْنِ. (ق,د,ت,ن,جه)', 'നുഅ്മാനുബ്നു ബശീർ(റ): നബി(സ) രണ്ടു പെരുന്നാൾ നിസ്കാരങ്ങളിലും ജുമുഅയിലും ''സബ്ബിഹിസ്മ റബ്ബികൽ അഅ്ല......''യും ''ഹൽ അതാക്ക ഹദീസുൽ ഗാശിയഃ.......''യും ഓതാറുണ്ടായിരുന്നു. പെരുന്നാളും ജുമുഅയും ഒന്നിച്ചു വരുന്ന ദിവസവും രണ്ടു നിസ്കാരങ്ങളിലും ഇത് ആവർത്തിക്കുമായിരുന്നു. (ബു,മു,ദ,തു,ന,ജ)', 'النُّعْمَانِ بْنِ بَشِيرٍ', 'നുഅ്മാനുബ്നു ബശീർ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 387, 387, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 176, 'عَنْ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقْرَأُ فِي صَلَاةِ الْجُمُعَةِ بِ{سَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى} وَ{هَلْ أَتَاكَ حَدِيثُ الْغَاشِيَةِ}. (ن)', 'സമുറ(റ): നബി(സ) ജുമുഅഃ നിസ്കാരത്തിൽ ''സബ്ബിഹിസ്മ റബ്ബിക....''യും ''ഹൽ അതാക്ക....''യും ഓതാറുണ്ടായിരുന്നു. (ന)', 'سَمُرَةَ', 'സമുറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 387, 387, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 177, 'عَنْ عُبَيْدِ اللهِ بْنِ أَبِي رَافِعٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: اسْتَخْلَفَ مَرْوَانُ أَبَا هُرَيْرَةَ عَلَى الْمَدِينَةِ، فَخَرَجَ إِلَى مَكَّةَ، فَصَلَّى بِنَا أَبُو هُرَيْرَةَ يَوْمَ الْجُمُعَةِ، فَقَرَأَ بِسُورَةِ الْجُمُعَةِ فِي السَّجْدَةِ الْأُولَى، وَفِي الْآخِرَةِ: {إِذَا جَاءَكَ الْمُنَافِقُونَ} قَالَ عُبَيْدُ اللهِ: فَأَدْرَكْتُ أَبَا هُرَيْرَةَ حِينَ انْصَرَفَ، فَقُلْتُ لَهُ: إِنَّكَ قَرَأْتَ بِسُورَتَيْنِ كَانَ عَلِيٌّ يَقْرَأُ بِهِمَا بِالْكُوفَةِ. فَقَالَ أَبُو هُرَيْرَةَ: إِنِّي سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقْرَأُ بِهِمَا. (م,د,ت,ن,جه)', 'ഉബൈദില്ലാഹിബ്നു അബൂറാഫിഅ്(റ): അബൂഹുറൈറ(റ)യെ മർവാൻ മദീനയിലേക്ക് പ്രതിനിധിയായയച്ചു. അപ്പോൾ അദ്ദേഹം മക്കയിലേക്ക് പുറപ്പെടുകയും ഞങ്ങളോടൊപ്പം വെള്ളിയാഴ്ച ദിവസം നിസ്കരിക്കുകയും ചെയ്തു. ഒന്നാമത്തെ റക്അത്തിൽ സൂറത്തുജുമുഅയും അവസാനത്തിൽ ''ഇദാ ജാഅകൽ മുനാഫിക്കൂന''യും ഓതി. ഉബൈദുല്ല പറഞ്ഞു: അദ്ദേഹം പിരിഞ്ഞപ്പോൾ (വിരമിച്ചപ്പോൾ) ഞാൻ അദ്ദേഹത്തെ കണ്ടുമുട്ടി. അതോടൊപ്പം പറയുകയും ചെയ്തു: അലി(റ) കൂഫയിൽ ഈ സൂറത്തുകൾ ഓതാറുണ്ടായിരുന്നു. അപ്പോൾ അബൂഹുറൈറ(റ) പറഞ്ഞു: റസൂൽ(സ) ഇവ ഓതാറുണ്ടായിരുന്നു. (മു,ദ,തു,ന,ജ)', 'عُبَيْدِ اللهِ بْنِ أَبِي رَافِعٍ', 'ഉബൈദില്ലാഹിബ്നു അബൂറാഫിഅ്(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 387, 387, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 178, 'عَنْ عُبَيْدِ اللهِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَتَبَ الضَّحَّاكُ بْنُ قَيْسٍ إِلَى النُّعْمَانِ بْنِ بَشِيرٍ: أَخْبِرْنَا بِأَيِّ شَيْءٍ كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقْرَأُ يَوْمَ الْجُمُعَةِ، مَعَ سُورَةِ الْجُمُعَةِ؟ قَالَ: كَانَ يَقْرَأُ فِيهَا {هَلْ أَتَاكَ حَدِيثُ الْغَاشِيَةِ}. (م,د,ن,جه)', 'ഉബൈദില്ലാഹിബ്നു അബ്ദുല്ല(റ): ളഹ്ഹാകുബ്നു ഖൈസ് നുഅ്മാനുബ്നു ബഷീറി(റ)നെഴുതി: വെള്ളിയാഴ്ച ദിവസം സൂറത്തുജുമുഅയോടൊന്നിച്ച് നബി(സ) ഓതാറുണ്ടായിരുന്ന സൂറത്തുകൾ ഏതാണെന്ന് ഞങ്ങളെ അറിയിക്കുക. അദ്ദേഹം പറഞ്ഞു: നബി(സ) അതിൽ ഹൽ അതാക്ക... ഓതാറുണ്ടായിരുന്നു. (മു,ദ,ന,ജ)', 'عُبَيْدِ اللهِ بْنِ عَبْدِ اللهِ', 'ഉബൈദില്ലാഹിബ്നു അബ്ദുല്ല(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 387, 387, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 179, 'عَنْ بِنْتِ لِحَارِثَةَ بْنِ النُّعْمَانِ قَالَتْ: مَا حَفِظْتُ {ق} إِلَّا مِنْ فِي رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، يَخْطُبُ بِهَا كُلَّ جُمُعَةٍ، قَالَتْ: وَكَانَ تَنُّورُنَا وَتَنُّورُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَاحِدًا. وَفِي رِوَيَةٍ قَالَتْ: مَا أَخَذْتُ {ق، وَالْقُرْآنِ الْمَجِيدِ..} إِلَّا مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، كَانَ يَقْرَؤُهَا فِي كُلِّ جُمُعَةٍ. (م,ن)', 'ഹാരിഥതുബ്നു നുഅ്മാ(റ)ന്റെ പുത്രി: സൂറത്തു ''ഖാഫ്'' ഞാൻ റസൂലിന്റെ നാവിൽ നിന്ന് കേട്ടുകൊണ്ടല്ലാതെ മനഃപാഠമാക്കിയിട്ടില്ല. നബി(സ) അത് എല്ലാ ജുമുഅഃ ദിവസവും ഖുത്വുബയിൽ ഓതാറുണ്ടായിരുന്നു. അവർ പറയുന്നു: നബി(സ)യുടേയും ഞങ്ങളുടേയും അടുപ്പ് ഒന്നിച്ചായിരുന്നു. മറ്റൊരു റിപ്പോർട്ടിൽ: ഞാൻ സൂറത്തുഖാഫ് നബിയുടെ അടുത്തുനിന്നാണ് പഠിച്ചത്. നബി(സ) എല്ലാ ജുമുഅയിലും അത് പാരായണം ചെയ്തിരുന്നു. (മു,ന)', 'بِنْتِ لِحَارِثَةَ بْنِ النُّعْمَانِ قَالَتْ', 'ഹാരിഥതുബ്നു നുഅ്മാ(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 387, 388, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=18 and h.hadith_no=179), 1, null, 'മറ്റൊരു നിവേദനിൽ: ഞാൻ സൂറത്തുഖാഫ് നബിയുടെ അടുത്തുനിന്നാണ് പഠിച്ചത്. നബി(സ) എല്ലാ ജുമുഅയിലും അത് പാരായണം ചെയ്തിരുന്നു. (മു,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 180, 'عَنْ أَبِي عِنَبَةَ الْخَوْلَانِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقْرَأُ فِي الْجُمُعَةِ بِ{سَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى} وَ{هَلْ أَتَاكَ حَدِيثُ الْغَاشِيَةِ}. (جه)', 'അബൂഇനബതുൽ ഖൗലാനി(റ): നബി(സ) ജുമുഅഃ നിസ്കാരത്തിൽ ''സബ്ബിഹിസ്മ റബ്ബികൽ അഅ്ലാ'' എന്ന സൂറത്തും, ''ഹൽ അതാക ഹദീസുൽ ഗാശിയ'' എന്ന സൂറത്തും ഓതാറുണ്ടായിരുന്നു. (ജ)', 'أَبِي عِنَبَةَ الْخَوْلَانِيِّ', 'അബൂഇനബതുൽ ഖൗലാനി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 388, 388, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 181, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا صَلَّيْتُمْ بَعْدَ الْجُمُعَةِ فَصَلُّوا أَرْبَعًا". وَفِي رِوَايَةٍ: قَالَ سُهَيْلٌ: "فَإِنْ عَجِلَ بِكَ شَيْءٌ فَصَلِّ رَكْعَتَيْنِ فِي الْمَسْجِدِ وَرَكْعَتَيْنِ إِذَا رَجَعْتَ". (م,ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ ജുമുഅക്കു ശേഷം നിസ്കരിക്കുമ്പോൾ നാലു റക്അത്ത് നിസ്കരിക്കുക." ഒരു റിപ്പോർട്ടിൽ: സുഹൈൽ(റ) പറഞ്ഞു: "നിങ്ങൾക്ക് വല്ല തിടുക്കവുമുണ്ടെങ്കിൽ പള്ളിയിൽ വെച്ച് രണ്ട് റക്അത്ത് നിസ്കരിക്കുക, മടങ്ങി വന്നശേഷം രണ്ടു റക്അത്തും നിസ്കരിക്കുക." (മു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','ن','جه']::text[], array['മു','ന','ജ']::text[], null, null, 388, 388, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=18 and h.hadith_no=181), 1, 'وَفِي رِوَايَةٍ: قَالَ سُهَيْلٌ: "فَإِنْ عَجِلَ بِكَ شَيْءٌ فَصَلِّ رَكْعَتَيْنِ فِي الْمَسْجِدِ وَرَكْعَتَيْنِ إِذَا رَجَعْتَ". (م,ن,جه)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 182, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّهُ كَانَ إِذَا صَلَّى الْجُمُعَةَ انْصَرَفَ فَسَجَدَ سَجْدَتَيْنِ فِي بَيْتِهِ ثُمَّ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَصْنَعُ ذَلِكَ. (م,ت)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): ജുമുഅഃ നിസ്കാരം കഴിഞ്ഞ് പിരിഞ്ഞാൽ അദ്ദേഹം തന്റെ വീട്ടിൽ വെച്ച് രണ്ട് റക്അത്ത് നിസ്കരിക്കാറുണ്ടായിരുന്നു. പിന്നെ അദ്ദേഹം പറഞ്ഞു: നബി(സ) അപ്രകാരം ചെയ്തിരുന്നു. (മു,തു)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 388, 388, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 183, 'عَنْ عُمَرَ بْنِ عَطَاءٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ نَافِعَ ابْنَ جُبَيْرٍ أَرْسَلَهُ إِلَى السَّائِبِ ابْنِ أُخْتِ نَمِرٍ، يَسْأَلُهُ عَنْ شَيْءٍ رَآهُ مِنْهُ مُعَاوِيَةُ فِي الصَّلَاةِ، فَقَالَ: نَعَمْ صَلَّيْتُ مَعَهُ الْجُمُعَةَ فِي الْمَقْصُورَةِ، فَلَمَّا سَلَّمَ الْإِمَامُ قُمْتُ فِي مَقَامِي فَصَلَّيْتُ، فَلَمَّا دَخَلَ أَرْسَلَ إِلَيَّ، فَقَالَ: لَا تَعُدْ لِمَا فَعَلْتَ. إِذَا صَلَّيْتَ الْجُمُعَةَ فَلَا تَصِلْهَا بِصَلَاةٍ حَتَّى تَكَلَّمَ أَوْ تَخْرُجَ، فَإِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَمَرَنَا بِذَلِكَ: "أَنْ لَا تُوصَلَ صَلَاةٌ بِصَلَاةٍ حَتَّى نَتَكَلَّمَ أَوْ نَخْرُجَ". (م,د)', 'ഉമറുബ്നു അത്വാഅ്(റ): മുആവിയ(റ)യുടെ നിസ്കാരത്തിൽ നിന്ന് കണ്ടതായി വല്ലതും അറിവിലുണ്ടോ എന്ന് ചോദിക്കാൻ നാഫിഉബ്നു ജുബൈർ അദ്ദേഹത്തെ സാഇബുബ്നു ഉഖ്ത്ത് നമിറിന്റെ അടുത്തേക്കയച്ചു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: അതെ, മഖ്സൂറയിൽ വെച്ച് അദ്ദേഹത്തോടൊപ്പം ഞാൻ ജുമുഅഃ നിസ്കരിച്ചു. ഇമാം സലാം വീട്ടിയപ്പോൾ ഞാൻ എന്റെ സ്ഥലത്ത് എഴുന്നേറ്റ് നിന്ന് നിസ്കരിച്ചു. മുആവിയ വന്നപ്പോൾ എന്റെ അടുത്തേക്ക് ആളെ അയച്ചു. അദ്ദേഹം പറഞ്ഞു: നീ ഇപ്പോൾ ചെയ്തത് ഇനി ആവർത്തിക്കരുത്. ജുമുഅഃ നിസ്കാരം കഴിഞ്ഞാൽ പുറത്തു പോകുന്നതു വരെയോ സംസാരിക്കുന്നതു വരെയോ നിസ്കാരമില്ല. നബി(സ) ഇപ്രകാരം കൽപിച്ചിരുന്നു: "പുറത്തു പോവുകയോ സംസാരിക്കുകയോ ചെയ്യുന്നതിനു മുമ്പ് ഒരു നിസ്കാരവും മറ്റൊരു നിസ്കാരത്തോട് കൂട്ടി ചേർക്കരുത്." (മു,ദ)', 'عُمَرَ بْنِ عَطَاءٍ', 'ഉമറുബ്നു അത്വാഅ്(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 388, 389, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 184, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا، وَقَدْ رَأَى رَجُلًا يُصَلِّي رَكْعَتَيْنِ يَوْمَ الْجُمُعَةِ فِي مَقَامِهِ فَدَفَعَهُ وَقَالَ: أَتُصَلِّي الْجُمُعَةَ أَرْبَعًا؟ وَكَانَ عَبْدُ اللهِ يُصَلِّي يَوْمَ الْجُمُعَةِ رَكْعَتَيْنِ فِي بَيْتِهِ، وَيَقُولُ: هَكَذَا فَعَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (د)', 'ഇബ്നുഉമർ(റ): ഒരാൾ വെള്ളിയാഴ്ച ദിവസം തന്റെ സ്ഥാനത്തു നിന്ന് (നിസ്കരിച്ചേടത്തു നിന്ന്) രണ്ട് റക്അത്ത് നിസ്കരിക്കുന്നത് അദ്ദേഹം കണ്ടു. അപ്പോൾ അതു തടഞ്ഞു കൊണ്ട് അദ്ദേഹം ചോദിച്ചു: നീ ജുമുഅഃ നാലു റക്അത്ത് നിസ്കരിക്കുകയാണോ? അബ്ദുല്ല തന്റെ വീട്ടിൽ വെച്ച് വെള്ളിയാഴ്ച ദിവസം രണ്ട് റക്അത്ത് നിസ്കരിക്കാറുണ്ടായിരുന്നു. അദ്ദേഹം പറഞ്ഞു: നബി(സ) ഇപ്രകാരം ചെയ്തിരുന്നു. (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 389, 389, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 185, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: كَانَ يُطِيلُ الصَّلَاةَ قَبْلَ الْجُمُعَةِ، وَيُصَلِّي بَعْدَهَا رَكْعَتَيْنِ فِي بَيْتِهِ، وَيُحَدِّثُ أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَفْعَلُ ذَلِكَ. (م,د,ت,ن,جه)', 'ഇബ്നുഉമർ(റ): അദ്ദേഹം ജുമുഅക്ക് മുമ്പുള്ള നിസ്കാരം ദീർഘിപ്പിക്കുമായിരുന്നു. ജുമുഅക്ക് ശേഷം രണ്ട് റക്അത്ത് വീട്ടിൽ വെച്ചു നിസ്കരിച്ചിരുന്നു. ശേഷം ഇപ്രകാരം പറയും: നിശ്ചയം, നബി(സ) ഇപ്രകാരം ചെയ്യാറുണ്ടായിരുന്നു. (മു,ദ,തു,ന,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 389, 389, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 186, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي بَعْدَ الْجُمُعَةِ رَكْعَتَيْنِ فِي بَيْتِهِ. (د,ت,ن,جه)', 'ഇബ്നുഉമർ(റ): നബി(സ) ജുമുഅക്കു ശേഷം വീട്ടിൽ വെച്ച് രണ്ട് റക്അത്ത് നിസ്കരിച്ചിരുന്നു. (ദ,തു,ന,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 389, 389, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 187, 'عَنْ عَطَاءٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُ رَأَى ابْنَ عُمَرَ يُصَلِّي بَعْدَ الْجُمُعَةِ، فَيَنْمَازُ عَنْ مُصَلَّاهُ الَّذِي صَلَّى فِيهِ الْجُمُعَةَ قَلِيلًا غَيْرَ كَثِيرٍ، قَالَ: فَيَرْكَعُ رَكْعَتَيْنِ، قَالَ: ثُمَّ يَمْشِي أَنْفَسَ مِنْ ذَلِكَ، فَيَرْكَعُ أَرْبَعَ رَكَعَاتٍ. قِيلَ لِعَطَاءٍ: كَمْ رَأَيْتَ ابْنَ عُمَرَ يَصْنَعُ ذَلِكَ؟ قَالَ: مِرَارًا. (د)', 'അത്വാഅ്(റ); അദ്ദേഹം കണ്ടതായി പറയുന്നു: ജുമുഅക്കു ശേഷം ഇബ്നുഉമർ(റ) നിസ്കരിക്കും. എന്നിട്ട് അദ്ദേഹം തന്റെ നിസ്കാര സ്ഥലത്തുനിന്ന് അൽപം മാറി നിൽക്കും, പിന്നെ രണ്ട് റക്അത്ത് നിസ്കരിക്കും. പിന്നെ ആദ്യത്തേതിനേക്കാൾ കുറച്ച് നടക്കും, എന്നിട്ട് നാലു റക്അത്ത് നിസ്കരിക്കും. അത്വാഇനോട് ചോദിക്കപ്പെട്ടു: ഇബ്നുഉമർ ഇപ്രകാരം ചെയ്യുന്നതായി നീ എത്ര തവണ കണ്ടു? അദ്ദേഹം പറഞ്ഞു: പല പ്രാവശ്യം. (ദ)', 'عَطَاءٍ', 'അത്വാഅ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 389, 389, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 188, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ إِذَا كَانَ بِمَكَّةَ فَصَلَّى الْجُمُعَةَ تَقَدَّمَ فَصَلَّى رَكْعَتَيْنِ، ثُمَّ تَقَدَّمَ فَصَلَّى أَرْبَعًا. وَإِذَا كَانَ بِالْمَدِينَةِ صَلَّى الْجُمُعَةَ، ثُمَّ رَجَعَ إِلَى بَيْتِهِ فَصَلَّى رَكْعَتَيْنِ، وَلَمْ يُصَلِّ فِي الْمَسْجِدِ. فَقِيلَ لَهُ، فَقَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَفْعَلُ ذَلِكَ. (د)', 'ഇബ്നുഉമർ(റ): അദ്ദേഹം മക്കയിലായിരിക്കെ ജുമുഅഃ നിസ്കരിച്ചു. ശേഷം മുന്നോട്ടു വന്ന് രണ്ട് റക്അത്ത് നിസ്കരിച്ചു. വീണ്ടും മുന്നോട്ടുവന്ന് നാലു റക്അത്ത് നിസ്കരിച്ചു. അദ്ദേഹം മദീനയിലായിരിക്കെ ജുമുഅഃ നിസ്കരിച്ചു. പിന്നെ വീട്ടിലേക്ക് മടങ്ങി രണ്ട് റക്അത്ത് അവിടെ വെച്ച് നിസ്കരിച്ചു. പള്ളിയിൽ വെച്ച് നിസ്കരിച്ചില്ല. അദ്ദേഹത്തോട് അതിനെക്കുറിച്ച് ചോദിക്കപ്പെട്ടപ്പോൾ അദ്ദേഹം പറഞ്ഞു: നബി(സ) ഇപ്രകാരം ചെയ്യാറുണ്ടായിരുന്നു. (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 389, 389, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 189, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ كَانَ مُصَلِّيًا بَعْدَ الْجُمُعَةِ فَلْيُصَلِّ أَرْبَعًا". وَفِي رِوَيَةٍ: "إِذَا صَلَّيْتُمُ الْجُمُعَةَ فَصَلُّوا بَعْدَهَا أَرْبَعًا". (م,د,ت,ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും ജുമുഅക്ക് ശേഷം നിസ്കരിക്കുകയാണെങ്കിൽ അവൻ നാലു റക്അത്ത് നിസ്കരിക്കട്ടെ." മറ്റൊരു റിപ്പോർട്ടിൽ: "നിങ്ങൾ ജുമുഅഃ നിസ്കരിക്കുകയാണെങ്കിൽ അതിനുശേഷം നാലു റക്അത്ത് നിസ്കരിക്കുക." (മു,ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 390, 390, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=18 and h.hadith_no=189), 1, null, 'മറ്റൊരു നിവേദനിൽ: "നിങ്ങൾ ജുമുഅഃ നിസ്കരിക്കുകയാണെങ്കിൽ അതിനുശേഷം നാലു റക്അത്ത് നിസ്കരിക്കുക." (മു,ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 190, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّهُ كَانَ - إِذَا صَلَّى الْجُمُعَةَ - انْصَرَفَ، فَصَلَّى سَجْدَتَيْنِ فِي بَيْتِهِ، ثُمَّ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَصْنَعُ ذَلِكَ. (م,ت,جه)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): അദ്ദേഹം ജുമുഅഃ നിസ്കരിച്ച ശേഷം പിരിഞ്ഞു പോയാൽ തന്റെ വീട്ടിൽ വെച്ച് രണ്ട് റക്അത്ത് നിസ്കരിക്കുമായിരുന്നു. പിന്നെ പറയും: നബി(സ) ഇപ്രകാരമായിരുന്നു ചെയ്തിരുന്നത്. (മു,തു,ജ)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['م','ت','جه']::text[], array['മു','തു','ജ']::text[], null, null, 390, 390, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 191, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُصَلِّي بَعْدَ الْجُمُعَةِ رَكْعَتَيْنِ. (م,ت,جه)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): നബി(സ) ജുമുഅഃ നിസ്കരിച്ചതിനു ശേഷം രണ്ട് റക്അത്ത് നിസ്കരിക്കാറുണ്ടായിരുന്നു. (മു,തു,ജ)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['م','ت','جه']::text[], array['മു','തു','ജ']::text[], null, null, 390, 390, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 192, 'عَنْ عَبْدِاللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُصَلِّي: قَبْلَ الظُّهْرِ رَكْعَتَيْنِ وَبَعْدَهَا رَكْعَتَيْنِ، وَبَعْدَ الْمَغْرِبِ رَكْعَتَيْنِ فِي بَيْتِهِ، وَبَعْدَ الْعِشَاءِ رَكْعَتَيْنِ، وَكَانَ لَا يُصَلِّي بَعْدَ الْجُمُعَةِ حَتَّى يَنْصَرِفَ، فَيُصَلِّي رَكْعَتَيْنِ. (خ)', 'ഇബ്നുഉമർ(റ): നബി(സ) ളുഹ്റിനു മുമ്പും ശേഷവും രണ്ട് റക്അത്ത് വീതവും മഗ്രിബിനു ശേഷം രണ്ട് റക്അത്ത് തന്റെ വീട്ടിൽ വെച്ചും നിസ്കരിച്ചിരുന്നു. ഇശാഇനു ശേഷം രണ്ട് റക്അത്തും നിസ്കരിച്ചിരുന്നു. ജുമുഅനിസ്കാരത്തിൽ നിന്ന് വിരമിച്ച ശേഷം പിരിഞ്ഞു പോകുന്നതുവരെ നിസ്കരിച്ചിരുന്നില്ല. പിരിഞ്ഞുപോയ ശേഷം (വീട്ടിൽ വെച്ച്) രണ്ട് റക്അത്ത് നിസ്കരിക്കും. (ബു)', 'عَبْدِاللهِ بْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 390, 390, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 193, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّهُ كَانَ يُصَلِّي بَعْدَ الْجُمُعَةِ رَكْعَتَيْنِ يُطِيلُ فِيهِمَا. وَيَقُولُ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَفْعَلُهُ. (ن)', 'ഇബ്നുഉമർ(റ): അദ്ദേഹം ജുമുഅക്കു ശേഷം രണ്ട് റക്അത്ത് ദീർഘിപ്പിച്ച് നിസ്കരിക്കാറുണ്ടായിരുന്നു. പിന്നെ ഇങ്ങനെ പറയും: റസൂൽ(സ) ഇപ്രകാരമായിരുന്നു ചെയ്തിരുന്നത്. (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 390, 390, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 194, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ لَا يُصَلِّي بَعْدَ الْجُمُعَةِ حَتَّى يَنْصَرِفَ، فَيُصَلِّي رَكْعَتَيْنِ. وَفِي رِوَيَةٍ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي بَعْدَ الْجُمُعَةِ رَكْعَتَيْنِ فِي بَيْتِهِ. (ن)', 'ഇബ്നുഉമർ(റ): നബി(സ) ജുമുഅക്കു ശേഷം അവിടെനിന്നും പിരിഞ്ഞു പോകുന്നതുവരെ നിസ്കരിച്ചിരുന്നില്ല. പിരിഞ്ഞുപോയശേഷം (വീട്ടിൽ വെച്ച്) രണ്ട് റക്അത്ത് നിസ്കരിക്കുമായിരുന്നു. മറ്റൊരു റിപ്പോർട്ടിൽ: റസൂൽ(സ) ജുമുഅക്കു ശേഷം തന്റെ വീട്ടിൽ വെച്ച് രണ്ട് റക്അത്ത് നിസ്കരിക്കാറുണ്ടായിരുന്നു. (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 390, 390, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=18 and h.hadith_no=194), 1, null, 'മറ്റൊരു നിവേദനിൽ: റസൂൽ(സ) ജുമുഅക്കു ശേഷം തന്റെ വീട്ടിൽ വെച്ച് രണ്ട് റക്അത്ത് നിസ്കരിക്കാറുണ്ടായിരുന്നു. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 195, 'عَنْ عُمَرَ رَضِيَ اللهُ عَنْهُ قَالَ: صَلَاةُ الْجُمُعَةِ رَكْعَتَانِ وَصَلَاةُ الْفِطْرِ رَكْعَتَانِ، وَصَلَاةُ الْأَضْحَى رَكْعَتَانِ، وَصَلَاةُ السَّفَرِ رَكْعَتَانِ، تمام غير قصر، على لسان محمد صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (ن)', 'ഉമർ(റ): ജുമുഅഃ നിസ്കാരവും, ചെറിയ പെരുന്നാൾ നിസ്കാരവും, ബലി പെരുന്നാൾ നിസ്കാരവും, യാത്രക്കാരന്റെ നിസ്കാരവും പൂർണ്ണമായ ചുരുക്കാത്ത നിലയിലുള്ള രണ്ട് റക്അത്തുകളാണ്. ഇക്കാര്യം നബി(സ) തന്റെ നാവുകൊണ്ട് പറഞ്ഞതാണ്. (ന)', 'عُمَرَ', 'ഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 391, 391, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 196, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ : أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ أَدْرَكَ مِنَ الْجُمُعَةِ رَكْعَةً فَلْيُصَلِّ إِلَيْهَا أُخْرَى". (جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "വല്ലവനും ജുമുഅയിൽ നിന്നും ഒരു റക്അത്ത് ലഭിച്ചാൽ അവൻ മറ്റേ റക്അത്ത് കൂടി കൂട്ടി നിസ്കരിക്കട്ടെ." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 391, 391, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 197, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أَدْرَكَ مِنَ الصَّلَاةِ رَكْعَةً فَقَدْ أَدْرَكَ". (م,د,ت,ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "വല്ലവനും നിസ്കാരത്തിൽ നിന്ന് ഒരു റക്അത്ത് ലഭിച്ചാൽ അവന് ആ നിസ്കാരം ലഭിച്ചു." (മു,ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 391, 391, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 198, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أَدْرَكَ رَكْعَةً مِنْ صَلَاةِ الْجُمُعَةِ أَوْ غَيْرِهَا فَقَدْ أَدْرَكَ الصَّلَاةَ". (ت,ن,جه)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "വല്ലവനും ജുമുഅഃ നിസ്കാരത്തിൽ നിന്നോ, മറ്റു നിസ്കാരങ്ങളിൽ നിന്നോ ഒരു റക്അത്ത് ലഭിച്ചുവെങ്കിൽ അവന് ആ നിസ്കാരം ലഭിച്ചു." (തു,ന,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ت','ن','جه']::text[], array['തു','ന','ജ']::text[], null, null, 391, 391, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 199, 'عَنْ مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ، وَقَدْ سَأَلَ زَيْدَ بْنَ أَرْقَمَ رَضِيَ اللهُ عَنْهُمْ قَالَ: أَشَهِدْتَ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عِيدَيْنِ اجْتَمَعَا فِي يَوْمٍ؟ قَالَ: نَعَمْ، قَالَ: فَكَيْفَ صَنَعَ؟ قَالَ: صَلَّى الْعِيدَ ثُمَّ رَخَّصَ فِي الْجُمُعَةِ، فَقَالَ: "مَنْ شَاءَ أَنْ يُصَلِّيَ فَلْيُصَلِّ". (د,ن,جه)', 'മുആവിയതുബ്നു അബൂസുഫിയാൻ(റ): അദ്ദേഹം സൈദുബ്നു അർഖമി(റ)നോട് ചോദിച്ചു: താങ്കൾ രണ്ടു പെരുന്നാൾ (ജുമുഅയും പെരുന്നാളും) ഒന്നിച്ചുവന്ന ദിവസത്തിൽ നബി(സ)യോടൊപ്പം ഉണ്ടായിട്ടുണ്ടോ? അദ്ദേഹം പറഞ്ഞു: നബി(സ) പെരുന്നാൾ നിസ്കരിച്ചു, പിന്നെ ജുമുഅക്ക് ഇളവ് നൽകിക്കൊണ്ട് പറഞ്ഞു: "നിസ്കരിക്കാൻ ഉദ്ദേശിക്കുന്നവൻ നിസ്കരിക്കട്ടെ." (ദ,ന,ജ)', 'مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ، وَقَدْ سَأَلَ زَيْدَ بْنَ أَرْقَمَ', 'മുആവിയതുബ്നു അബൂസുഫിയാൻ(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 391, 391, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 200, 'عَنْ عَطَاءِ بْنِ أَبِي رَبَاحٍ رَضِيَ اللهُ عَنْهُ قَالَ: صَلَّى بِنَا ابْنُ الزُّبَيْرِ فِي يَوْمِ عِيدٍ فِي يَوْمِ جُمُعَةٍ أَوَّلَ النَّهَارِ، ثُمَّ رُحْنَا إِلَى الْجُمُعَةِ فَلَمْ يَخْرُجْ إِلَيْنَا، فَصَلَّيْنَا وُحْدَانًا، وَكَانَ ابْنُ عَبَّاسٍ بِالطَّائِفِ، فَلَمَّا قَدِمَ ذَكَرْنَا ذَلِكَ لَهُ، فَقَالَ: أَصَابَ السُّنَّةَ. وَفِي رِوَيَةٍ :اجْتَمَعَ يَوْمُ جُمُعَةٍ وَيَوْمُ فِطْرٍ عَلَى عَهْدِ ابْنِ الزُّبَيْرِ، فَقَالَ: عِيدَانِ اجْتَمَعَا فِي يَوْمٍ وَاحِدٍ. فَجَمَعَهُمَا جَمِيعًا، فَصَلَّاهُمَا رَكْعَتَيْنِ بُكْرَةً، لَمْ يَزِدْ عَلَيْهِمَا حَتَّى صَلَّى الْعَصْرَ. (د,ن)', 'അതാഉബ്നു അബൂറബാഹ്(റ): ഒരു ജുമുഅഃ ദിവസം പെരുന്നാളിന് ഇബ്നുസുബൈർ(റ) ഞങ്ങൾക്ക് ഇമാമായി നിസ്കരിച്ചു. അത് പ്രഭാതത്തിൽ തന്നെയായിരുന്നു. പിന്നെ ഞങ്ങൾ ജുമുഅഃ നിസ്കാരത്തിനായി ചെന്നു. എന്നാൽ ഇബ്നുസുബൈർ ഞങ്ങൾക്ക് ഇമാമായി നിസ്കരിക്കാൻ വന്നില്ല. ഞങ്ങൾ ഒറ്റക്ക് നിസ്കരിച്ചു. ഇബ്നു അബ്ബാസ്(റ) അപ്പോൾ ത്വാഇഫിലായിരുന്നു. അദ്ദേഹം വന്നപ്പോൾ സംഭവങ്ങൾ അദ്ദേഹത്തോട് പറഞ്ഞു. അദ്ദേഹം പറഞ്ഞു: നിങ്ങൾക്ക് സുന്നത്ത് ലഭിച്ചു. മറ്റൊരു റിപ്പോർട്ടിൽ: ഇബ്നുസുബൈറി(റ)ന്റെ കാലത്ത് ജുമുഅയും ഈദുൽ ഫിത്വറും ഒന്നിച്ചുവന്നു. അദ്ദേഹം പറഞ്ഞു: ഒരേ ദിവസം രണ്ട് ആഘോഷങ്ങൾ ഒന്നിച്ചിരിക്കുന്നു. അവർ അത് രണ്ടിനേയും യോജിപ്പിച്ചു. കാലത്തു തന്നെ അവയെ അവർ രണ്ട് റക്അത്തായി നിസ്കരിച്ചു. അസർ നിസ്കരിക്കും വരെ മറ്റൊന്നും നിസ്കരിച്ചില്ല. (ദ,ന)', 'عَطَاءِ بْنِ أَبِي رَبَاحٍ', 'അതാഉബ്നു അബൂറബാഹ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 391, 392, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=18 and h.hadith_no=200), 1, null, 'മറ്റൊരു നിവേദനിൽ: ഇബ്നുസുബൈറി(റ)ന്റെ കാലത്ത് ജുമുഅയും ഈദുൽ ഫിത്വറും ഒന്നിച്ചുവന്നു. അദ്ദേഹം പറഞ്ഞു: ഒരേ ദിവസം രണ്ട് ആഘോഷങ്ങൾ ഒന്നിച്ചിരിക്കുന്നു. അവർ അത് രണ്ടിനേയും യോജിപ്പിച്ചു. കാലത്തു തന്നെ അവയെ അവർ രണ്ട് റക്അത്തായി നിസ്കരിച്ചു. അസർ നിസ്കരിക്കും വരെ മറ്റൊന്നും നിസ്കരിച്ചില്ല. (ദ,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 201, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: "قد اجْتَمَعَ فِي يَوْمِكُمْ هَذَا عِيدَانِ: فَمَنْ شَاءَ أَجْزَأَهُ مِنَ الْجُمُعَةِ، وَإِنَّا مُجَمِّعُونَ". (د,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾക്ക് ഈ ദിവസം രണ്ട് ആഘോഷങ്ങൾ ഒന്നിച്ചു വന്നിരിക്കുന്നു. ഉദ്ദേശിക്കുന്നവർക്ക് അതുകൊണ്ട് (പെരുന്നാൾ നിസ്കാരത്തെ കൊണ്ട്) മതിയാക്കാം. നാം ജുമുഅഃ നിസ്കരിക്കുന്നുണ്ട്." (ദ,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 392, 392, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 202, 'عَنْ أَوْسِ بْنِ أَوْسٍ رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ مِنْ أَفْضَلِ أَيَّامِكُمْ يَوْمَ الْجُمُعَةِ، فِيهِ خُلِقَ آدَمُ عَلَيْهِ السَّلَامُ، وَفِيهِ قُبِضَ، وَفِيهِ النَّفْخَةُ، وَفِيهِ الصَّعْقَةُ، فَأَكْثِرُوا عَلَيَّ مِنَ الصَّلَاةِ، فَإِنَّ صَلَاتَكُمْ مَعْرُوضَةٌ عَلَيَّ". قَالُوا: يَا رَسُولَ اللهِ، وَكَيْفَ تُعْرَضُ صَلَاتُنَا عَلَيْكَ وَقَدْ أَرِمْتَ؟ أَيْ بَلِيتَ. قَالَ: "إِنَّ اللهَ عَزَّ وَجَلَّ قَدْ حَرَّمَ عَلَى الْأَرْضِ أَنْ تَأْكُلَ أَجْسَادَ الْأَنْبِيَاءِ عَلَيْهِمُ السَّلَامُ". (ن,جه)', 'ഔസുബ്നു ഔസ്(റ): നബി(സ) പറഞ്ഞു: "നിശ്ചയം, നിങ്ങളുടെ ദിവസങ്ങളിൽ ഏറ്റവും ശ്രേഷ്ഠമായത് വെള്ളിയാഴ്ച ദിവസമാണ്. അന്ന് ആദം(അ) സൃഷ്ടിക്കപ്പെടുകയും മരണപ്പെടുകയും ചെയ്തു, ഊത്തും അട്ടഹാസവും (അവസാന നാളിന്റെ അടയാളങ്ങൾ) അന്ന് തന്നെയാണ്. അതുകൊണ്ട് നിങ്ങൾ എന്റെ മേൽ സ്വലാത്ത് ചൊല്ലൽ അധികരിപ്പിക്കുക. നിശ്ചയം, നിങ്ങളുടെ സ്വലാത്ത് എനിക്ക് വെളിവാക്കപ്പെടുന്നു. അവർ ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, താങ്കൾ മണ്ണായിപ്പോയിരിക്കെ ഞങ്ങളുടെ സ്വലാത്ത് എങ്ങിനെയാണ് അങ്ങയുടെ മേൽ വെളിവാക്കപ്പെടുക?" നബി(സ) പറഞ്ഞു: "നിശ്ചയം, പ്രവാചകന്മാരുടെ ശരീരം തിന്നുന്നത് അല്ലാഹു ഭൂമിക്ക് മേൽ കൽപഹറാമാക്കിയിരിക്കുന്നു (നിഷിദ്ധമാക്കിയിരിക്കുന്നു)." (ന,ജ)', 'أَوْسِ بْنِ أَوْسٍ', 'ഔസുബ്നു ഔസ്(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 392, 392, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=1 and b.book_no=18 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
